INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URIAGE BARIESUN SPF50+ CREME TEINTEE DOREE 50ML','Uriage','Solaires','Grâce à un complexe filtrant très performant, la crème apporte une très haute protection contre les UVA, les UVB, les radicaux libres et prévient du dessèchement cutané.
Sa texture légère, non grasse et agréablement parfumée garantit un plaisir d''utilisation renouvelé à chaque application.
Cette crème subtilement nacrée sublime le teint d''un éclat doré tout en garantissant une haute sécurité, une grande tolérance et une pénétration rapide.

Indication:

Hypoallergénique
Non comédogène
Sans alcool

Conseils d''utilisation:

