INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URIAGE BEBE 1ER SPRAY CU-ZN+ 100ML','Uriage','Bébé & Maman','Spray anti-irritations des zones humides irritées, plis, zones de macération. — Apaise rapidement — Purifie — Répare Conseil d’utilisation Bien agiter avant emploi. Vaporiser sur les zones cutanées suintantes ou de macération. Laisser agir en attendant l’absorption complète du produit. Eviter le contact avec les yeux. En cas de persistance des signes, consulter votre médecin.',11900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/URIAGESOIN.png?v=1690807749',10,1,'7455251300527','42301558522031','https://beautymarket.ma/products/uriage-bebe-1er-spray-cu-zn-100ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/URIAGESOIN.png?v=1690807749"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIODERMA ATODERM CREME DE DOUCHE 1L','Bioderma','Corps','Atoderm crème lavante 1L a été spécialement formulée pour un nettoyage en douceur des peaux sensibles et sèches. La crème lavante Bioderma hydrate et nourrit la peau, grâce à sa texture spécifique, particulièrement onctueuse, pour une sensation de bien-être et une réduction durable des irritations.
Après la douche, les peaux sensibles sont douces, leur film lipidique est reconstitué et la peau est protégée. Cet effet est obtenu par la présence dans la formule d’Atoderm crème lavante d’actifs surgraissants. La formule contient aussi différents actifs nettoyants et purifiants, de manière à limiter les micro-organismes souvent impliqués dans les problèmes de peaux sèches et réactives.

En quoi Atoderm crème lavante est-elle différente de
s savons ou gels classiques ? Ces derniers irritent la peau et la dessèchent au fil des douches, en agressant le film lipidique et protecteur naturellement présent à la surface de notre épiderme. Ce film est constitué d’une association d’eau, de sébum, de composés minéraux et organiques. On peut donc parler de film hydrolipidique. Sa fonction est d’isoler la peau des agressions extérieures. Trop de gels et de savons détruisent ce film.
A l’inverse, Atoderm crème lavante contribue non seulement à le préserver, mais aussi à le reconstituer, pour que votre peau soit protégée de son environnement.',23900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3701129802007-bioderma-atoderm-creme-de-douche-1l-boticinal-1.webp?v=1778500754',10,1,'7455255756975','42301568286895','https://beautymarket.ma/products/bioderma-atoderm-creme-de-douche-1l',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3701129802007-bioderma-atoderm-creme-de-douche-1l-boticinal-1.webp?v=1778500754"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIODERMA ATODERM CREME DE DOUCHE 200ML','Bioderma','Corps','Atoderm crème lavante 200ml a été spécialement formulée pour un nettoyage en douceur des peaux sensibles et sèches. La crème lavante Bioderma hydrate et nourrit la peau, grâce à sa texture spécifique, particulièrement onctueuse, pour une sensation de bien-être et une réduction durable des irritations.
Après la douche, les peaux sensibles sont douces, leur film lipidique est reconstitué et la peau est protégée. Cet effet est obtenu par la présence dans la formule d’Atoderm crème lavante d’actifs surgraissants. La formule contient aussi différents actifs nettoyants et purifiants, de manière à limiter les micro-organismes souvent impliqués dans les problèmes de peaux sèches et réactives.

En quoi Atoderm crème lavante est-elle différente de
s savons ou gels classiques ? Ces derniers irritent la peau et la dessèchent au fil des douches, en agressant le film lipidique et protecteur naturellement présent à la surface de notre épiderme. Ce film est constitué d’une association d’eau, de sébum, de composés minéraux et organiques. On peut donc parler de film hydrolipidique. Sa fonction est d’isoler la peau des agressions extérieures. Trop de gels et de savons détruisent ce film.
A l’inverse, Atoderm crème lavante contribue non seulement à le préserver, mais aussi à le reconstituer, pour que votre peau soit protégée de son environnement.',10200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hhv.png?v=1691752878',10,1,'7455256248495','42301569269935','https://beautymarket.ma/products/bioderma-atoderm-creme-de-douche-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hhv.png?v=1691752878"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIODERMA ATODERM GEL DOUCHE 1L','Bioderma','Corps','NETTOYANT TRèS DOUX : Conçu pour les peaux sensibles normales à sèches, ce gel douche nettoie en douceur, respecte l''équilibre cutané, apaise et protège la peau, Sa mousse onctueuse et délicatement parfumée apporte une agréable sensation de bien-être, Votre peau est douce après la douche,

MODE D''ACTION BIOLOGIQUE : Ce nettoyant moussant sans savon intègre le complexe Skin Protect, qui augmente le niveau d''hydratation de la peau en stimulant la production d''acide hyaluronique et protège durablement la peau grâce à son action relipidante, Sa formule douce respecte l''équilibre cutané,

FACILE à UTILISER : Ce gel douche peut s''utiliser 1 à 2 fois par jour, 7 jours/7, Naturellement bleuté, le Gel Douche Atoderm est sans colorant, sans savon, sans allergène et sans paraben,

Grâce à ses formules dermo-brevetées, Atoderm permet de restaurer biologiquement et durablement le film hydrolipidique des peaux en manque d''hydratation et de lipides,

Basés sur le respect absolu de la peau, les produits BIODERMA imitent ses mécanismes biologiques naturels, dans leurs composants et dans leur mode d''action, Pour leur formulation, BIODERMA sélectionne les actifs les plus purs, des molécules déjà présentes naturellement dans la peau pour une meilleure tolérance,',26900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bebemaman-bioderma-atoderm-gel-douche.webp?v=1778500347',10,1,'7455256641711','42301571203247','https://beautymarket.ma/products/bioderma-atoderm-gel-douche-1l',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bebemaman-bioderma-atoderm-gel-douche.webp?v=1778500347"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
