INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Nuhanciam Soin Corps Extrême 500 ml','Nuhanciam','Corps','Nuhanciam Soin Corps Extrême – 500 ml

