INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PRESIDENT DENTIFRICE BLANCHEUR 75 ML','President','Hygiène','spécifique pour ceux qui souhaitent maintenir la blancheur naturelle des dents, sans avoir recours à des produits nocifs ou très abrasifs.',5100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/president-president-dentifrice-blancheur-75-ml-dentaire.jpg?v=1678459701',10,1,'7475603603631','42361531203759','https://beautymarket.ma/products/president-dentifrice-blancheur-75-ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/president-president-dentifrice-blancheur-75-ml-dentaire.jpg?v=1678459701"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PRESIDENT Dentifrice blancheur plus 30ml','President','Hygiène','Passant du temps, l''émail des dents montre une perte naturelle et physiologique de la luminosité et la blancheur, en particulier à cause d''une hygiène buccale non constante, continue et appropriée, montre une perte naturelle et physiologique de la luminosité et la blancheur. Si ce processus se répand largement, ajouter plus d''interférence négative, comme l''utilisation intensive de tabac, l''apport de café, thé, certains antibiotiques (à base de tétracycline), par conséquent, apparaissent sur la surface des dents et brunissement forts spots disgracieux noirâtre. L''utilisation hebdomadaire d''un dentifrice abrasif bien équilibré est recommandée dans ce cas (RDA supérieur à 200). Grâce à son mélange de silice micronisée abrasive, obtenue à partir de coquillages appartenant à la famille des Diatomées, cette dentifrice anti-tache restaure la couleur naturelle de vos dents après quelques applications, en éliminant les différences de couleur dans l''émail',5300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/president-president-dentifrice-blancheur-plus-30ml-white-plus-dentaire.jpg?v=1678459822',10,1,'7475604193455','42361532022959','https://beautymarket.ma/products/president-dentifrice-blancheur-plus-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/president-president-dentifrice-blancheur-plus-30ml-white-plus-dentaire.jpg?v=1678459822"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Dermina - Sunlina - Crème Solaire Minéral Unifiante SPF50 40ml','Dermina','Visage','La Crème solaire minérale unifiante SUNLINA à la texture fondante qui ne colle pas, facile à étaler et qui unifie le teint sans laisser de trace blanche sur la peau, est un soin solaire spécialement formulé pour protéger les peaux sensibles intolérantes aux filtres solaires chimiques. Sa formule est composée de filtres solaires 100% minéraux (zinc oxyde, titanium dioxyde) qui assurent une protection optimale UVA/UVB sans risque d’intolérance (SPF50), et de la glycyrrhizine aux propriétés apaisantes pour lutter contre les dommages liés aux rayons UV. Testé sous contrôle dermatologique, hypoallergénique sans parfum.

Avant de s’exposer au soleil, appliquer uniformément une quantité suffisante de crème sur les parties exposées (2mg/cm2). Attention : en réduisant cette quantité, le niveau de protection est nettement diminué. Renouveler fréquemment l’application pour maintenir la protection surtout après avoir transpiré, avoir nagé ou s’être essuyé.',18000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Design-sans-titre-3_1.png?v=1758536042',10,1,'7479327981743','42373010718895','https://beautymarket.ma/products/dermina-sunlina-creme-solaire-mineral-unifiante-spf50-40ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Design-sans-titre-3_1.png?v=1758536042"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ISISPHARMA Teen Derm GEL sensitive 250 ml','Isispharma','Visage','Gel micro-exfoliant (micro-particules) traitant, nettoyant et séborégulateur. Teen Derm Gel est spécialement formulé pour réaliser une micro exfoliation du relief cutané.

