INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Ziaja Argan & Tsubaki Oils Masque Capillaire Lissant Concentré – 200ml','Ziaja','Cheveux','Le masque capillaire concentré à l’huile d’argan et de tsubaki est idéal pour les cheveux secs et abîmés. Fournit une protection efficace contre la chaleur. L’huile d’argan est une huile pressée à froid à partir des graines de l’arganier. Il est composé à 80% d’acides gras insaturés et de vitamine E, qui nourrit les cheveux, reconstruit la structure capillaire et stimule la croissance des cheveux. L’huile de Tsubaki est extraite des graines du camélia. Il est riche en acide linoléique (oméga 6) et en acide oléique (oméga 9), qui donnent de la brillance aux cheveux. De plus, les cheveux sont protégés du dessèchement.',8200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ZIAJA8.png?v=1693049527',10,1,'7479831101615','42374451101871','https://beautymarket.ma/products/ziaja-argan-tsubaki-oils-masque-capillaire-lissant-concentre-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ZIAJA8.png?v=1693049527"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
