INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Eucerin complete repair emollient reparateur 5% uree','Eucerin','Visage','Ce soin quotidien est utilisé pour les états de sécheresse cutanée sévère : peaux sèches constitutionnelles, peaux atopiques, prurigineuses, à tendance ichtyosique et xéroses, peaux desséchées par les traitements médicamenteux.

