INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SVR DENSITIUM BAUME NUIT 50ML','SVR','Visage','SVR Densitium Baume Nuit Réparation Globale 50 ml est un soin de nuit qui stimule le processus de régénération cutanée pour une action anti-âge globale.
