INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SVR PHYSIOPURE EAU MICELLAIRE 200ML','SVR','Visage','L’Eau Micellaire PHYSIOPURE nettoie votre peau en profondeur et en douceur. Les particules polluantes s’envolent, le maquillage s’efface. La peau est nette et fraiche.

