INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ISIS PHARMA TEEN DERM  HYDRA 40 ML','Isispharma','Visage','TEEN DERM | ISISPHARMA TEEN DERM HYDRA 40ML
TEEN DERM Hydra a été spécialement développé pour accompagner les peaux à tendance acnéique fragilisées par les traitements desséchants. Riche en puissants actifs hydratants, restructurants et apaisants, il hydrate, nourrit et apaise durablement. La peau retrouve confort et souplesse. Texture légère.
INFORMATION
PROPRIÉTÉS DES PRINCIPAUX ACTIFS
• BEURRE DE CACAO et GLUCOSE + XYLITOL NATUREL : hydratants / restructurants et protecteurs
• BISABOLOL et POLYMERE BIOMIMÉTIQUE : apaisants
• BUTYL AVOCADATE : séborégulateur
Efficacité cliniquement prouvée.
0% PHÉNOXYÉTHANOL • HYPOALLERGÉNIQUE • NON COMÉDOGÈNE
MODE D’EMPLOI
Appliquer matin et soir sur l’ensemble du visage et du cou préalablement nettoyés et séchés ou comme indiqué par votre dermatologue ou professionnel de santé. Éviter le contact avec les yeux.',19500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hydra.png?v=1690633496',10,1,'7531108729007','42466218148015','https://beautymarket.ma/products/isis-teen-derm-hydra-40-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hydra.png?v=1690633496"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ALGOLOGIE GOMMAGE DES VAGUES CREME EXFOLIANTE HYDRA FRAICHEUR 50ML','Algologie','Visage','Un gommage, frais et onctueux, qui élimine en douceur cellules mortes et impuretés tout en gorgeant la peau d’hydratation.

