INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('XEROLYS LYSASKIN 50','Xerolys','Visage','XEROLYS50 est un soin kératolytique et hydratant pour les callosités :

mains, coudes, pieds, ongles(Avulsion chimique), cuir chevelu...

