INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DERMINA SUNLINA CREME ANTI TACHES SPF50+ 40ML','Dermina','Solaires','La Crème Anti-taches SPF50+ SUNLINA discount du laboratoire DERMINA, le soin conçu pour protéger tous les types de peaux du visage et agir sur les taches brunes, à prix discount dans votre parapharmacie en ligne.

