INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Bella Aurora écran solaire anti-taches SPF50+ Peau Normale et Sèche 50ml + Trousse Offerte','Bella Aurora','Solaires','Écran solaire fluide SPF50 + formulé pour les peaux normales ou sèches. Fournit une protection élevée contre le rayonnement solaire UVA, UVB, la lumière visible (HEV) et l''infrarouge (IR).

• Réduit les imperfections cutanées. Sa formulation comprend de puissants actifs dépigmentants qui traitent les taches existantes, les atténuent visiblement et préviennent l''apparition de nouvelles.

• Calme la peau lors de l''exposition au soleil et réduit l''inflammation.

• Protection cellulaire maximale contre les radicaux libres qui protègent la peau contre le photovieillissement.

Protection SPF50 + protection UVA + UVB + Lumière visible (HEV) + Infrarouge (IR)

Testé sous contrôle dermatologique.

idéal pour Peaux normales ou sèches préoccupées par les effets du soleil sur la peau et souhaitent se protéger de l''apparition de taches et / ou atténuer celles existantes.',19900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ChatGPTImageSep25_2026_01_02_02PM_1.png?v=1790341349',10,1,'7561166454959','42562262237359','https://beautymarket.ma/products/bella-aurora-fluide-solaire-anti-tache-spf-50-50-ml-trousse-offerte',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ChatGPTImageSep25_2026_01_02_02PM_1.png?v=1790341349","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bella-aurora-ecran-solaire-anti-taches-spf50-spf50-peau-normale-et-seche-50ml_ba222ca7-b05e-4e9e-ba58-9548be70bfe3_1.webp?v=1714993797"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MGD propolis 120 gélules','MGD','Bien-être','La propolis est élaborée par les abeilles à partir des substances résineuses des végétaux (bourgeons, pommes de pin, écorces). Les abeilles l’utilisent pour colmater et isoler leur ruche, la protégeant ainsi des éventuels agresseurs extérieurs.
La propolis est utilisée depuis l’Antiquité pour ses nombreuses qualités. Riche en flavonoïde, elle est traditionnellement consommée en hiver.

Ingrédients :

Gélule
Propolis : 225 mg, tunique : gélifiant pullulan, maltodextrine.

Précautions d’emploi :
À consommer dans le cadre d’un régime alimentaire varié. Ne pas dépasser la dose journalière indiquée. Tenir hors de portée des jeunes enfants. Conserver à l’abri de la chaleur.

Posologie :
Gélule
3 à 6 gélules par jour.',14300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/PROPOLIS_1PRO_150x69_12093d3d-6570-4445-b4a2-31b27b981fad.jpg?v=1685545005',10,1,'7561675571375','42564293591215','https://beautymarket.ma/products/mgd-propolis-120-gelules',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/PROPOLIS_1PRO_150x69_12093d3d-6570-4445-b4a2-31b27b981fad.jpg?v=1685545005"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
