INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HEI POA Pur Monoi de Tahiti Hei Poa Vanille 100ml','Hei Poa','Solaires','Le Pur Monoï Vanillier Hei Poa est l’association gourmande de Monoï de Tahiti AO et de la vanille, parfum évocateur des îles. Soin multi-usages, il hydrate et répare la peau et les cheveux..',9900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/EFEF_1.jpg?v=1747828966',10,1,'7563820138671','42571768266927','https://beautymarket.ma/products/pur-monoi-de-tahiti-hei-poa-vanille-100ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/EFEF_1.jpg?v=1747828966"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('L''Oréal Professionnel série expert vitamino color masque 500ml','L''Oréal Professionnel','Cheveux','Spécialement conçu pour les cheveux colorés, ce masque a tout pour plaire avec sa texture gelée rafraîchissante et son application ultra rapide. En seulement une minute, il sublime vos reflets les plus précieux. Envie de découvrir le secret professionnel des plus belles couleurs ? Le masque Vitamino Color contient du Resveratrol, une molécule qui prévient l''altération de votre coloration au fil du temps. Associé au Shampoing Vitamino Color, votre chevelure garde sa vitalité et sa belle couleur jusqu’à 8 semaines*. Le masque Vitamino Color cible les mèches plus endommagées et les nourrit en profondeur. Il dépose un voile protecteur léger sur vos cheveux colorés, pour garder cette teinte bien-aimée le plus longtemps possible. Grâce à ce masque, le cheveu retrouve de sa force et de sa douceur.

Ce masque anti-affadissement se fait l''allié de toutes les nuances, du châtain caramel au blond platine, en passant par les jolis pastels. Tous les types de cheveux, des plus fins aux plus épais, peuvent bénéficier de ce produit. Un masque pour cheveux colorés facile à utiliser, à appliquer chaque semaine. Pour un résultat optimal, vous pouvez opter pour le Shampoing fixateur de couleur et le lait 10-en-1 pour cheveux colorés Vitamino Color. Cette touche finale apportera de la lumière à votre chevelure.

Conseils d''utilisation:

Appliquez ce masque nourrissant dans ou en dehors de la douche, sur vos cheveux préalablement essorés.
Laissez poser environ une minute sur les longueurs et les pointes.
Rincez longuement, en finissant avec un jet d''eau froide pour encore plus de brillance.',31400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/gftf.jpg?v=1714214299',10,1,'7563822760111','42571778228399','https://beautymarket.ma/products/loreal-professionnel-serie-expert-vitamino-color-masque-500ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/gftf.jpg?v=1714214299","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/VR051416_1.jpg?v=1714214299"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
