INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CENTAUREA CREME HYDRATANTE COMPENSATRICE 50ML','Centaurea','Visage','La crème hydratante de laboratoire Centaurea est une crème indiquée en cas d’acné, elle est spécialement formulée pour les peaux acnéiques fragilisées par des traitements irritants et desséchants. Riche en actifs hydratants, elle limite la desquamation excessive et les sensations de tiraillements. Les actifs hydratant (glycérine, vitamine E) et restructurant (Niacinamide) de la crème hydratante compensatrice Centaurea combat la desquamation et les sensations de tiraillements.les actifs apaisants (Tocophérol, allantoïne) atténuent les rougeurs et calment l’épiderme.',13500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/centaurea-creme-hydratante-compensatrice-50ml.jpg?v=1686150191',10,1,'7564661883055','42575120597167','https://beautymarket.ma/products/centaurea-creme-hydratante-compensatrice-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/centaurea-creme-hydratante-compensatrice-50ml.jpg?v=1686150191"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
