INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DCP HAIRLOSS SERUM CAPILLAIRE 100ml','DCP','Cheveux','Indications :
– Active la microcirculation
– Limite et contrôle la chute de cheveux
– Stimule la repousse des cheveux
