INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ISDINCEUTICS Flavo-c Forts Serum 15% 1 Flacon','Isdin','Cheveux','Le sérum est activé dès sa première utilisation pour contribuer à maintenir le collagène, à améliorer la fermeté de la peau et à gommer visiblement les rides.
Il révèle une peau radieuse, éclatante, protégée de la pollution et hydratée.

Son emballage unique garantit l’efficacité des vitamines pendant les 10 jours d’utilisation.

Testé sous contrôle dermatologique.

Remplacez le capuchon d’origine par celui contenant la vitamine C.
Pour activer le sérum, appuyez fermement sur le capuchon et secouez vigoureusement pendant 30 secondes.
Remplacez le capuchon par l’applicateur de gouttes.

Appliquez chaque matin 3-4 gouttes et massez jusqu’à absorption complète.
Une fois activé, conserver à moins de 30°C et jeter après 10 jours.',32900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/flavo.png?v=1762271836',10,1,'7587663184047','42669535887535','https://beautymarket.ma/products/isdinceutics-flavo-c-forts-serum-15-1-flacon',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/flavo.png?v=1762271836"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ISDINCEUTICS FLAVO C FORTE SERUM 15% 3 FLACONS','Isdin','Cheveux','Flavo-C Forte est un puissant sérum intensif pour le visage avec 15 % de vitamine C pure et fraîche qui revitalise, illumine et aide à réduire les signes de fatigue de la peau. Il augmente également la production de collagène, apporte de la fermeté et aide à réduire les rides en seulement 10 jours, tout en protégeant la peau du stress oxydatif et de la pollution. Son format innovant avec de la vitamine C en poudre maintient la vitamine C fraîche et stable jusqu’au premier moment d’utilisation, quand il est mélangé avec une solution liquide avec des ingrédients antioxydants, hydratants et anti-pollution.',64500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3FLACONS.png?v=1690362437',10,1,'7587665707183','42669538607279','https://beautymarket.ma/products/isdinceutics-flavo-c-forte-serum-15-3-flacons',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3FLACONS.png?v=1690362437"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
