INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Hydra phyt’s Levure de biere & selenium 400cps','Hydra Phyt''s','Corps','La principale propriété du sélénium est une amélioration significative de l’activité physique et mentale du corps.
La levure de bière est une source supplémentaire de sélénium, vitamines B1, B2, B6, acide folique, contenant de la vitamine PP.
Le sélénium a des propriétés antioxydantes, un effet protecteur sur le système immunitaire, empêchant la formation de radicaux libres qui endommagent les tissus corporels. Le sélénium augmente la formation d’anticorps dans les maladies infectieuses, aide à normaliser le système cardiovasculaire, le foie, le pancréas, participe à la glande thyroïde, régule les processus métaboliques dans le corps humain, ralentissant le processus de vieillissement.
Les vitamines B contribuent au fonctionnement normal du système nerveux, maintiennent le statut immunitaire du corps et améliorent l’état de la peau et des cheveux.

Conseils d’utilisation: Avaler (sans croquer) 6 comprimés par jour avec un verre d`eau.',8600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LEVURE.png?v=1690539796',10,1,'7588767695023','42672199467183','https://beautymarket.ma/products/hydra-phyt-s-levure-de-biere-selenium-400cps',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LEVURE.png?v=1690539796"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Mustela hydra bébé crème visage 40ml','Mustela','Bébé & Maman','Hydra-Visage Bébé de MUSTELA, le soin douceur pour redonner du confort et de la souplesse aux peaux fragiles et sèches du visage pour les tout-petits dès la naissance même prématurés et les enfants.
Dans les années 50, un produit totalement innovant révolutionne les soins bébé : un produit 2en1 nettoyant et adoucissant à l’odeur évocatrice : le lait emblématique MUSTELA. 60 ans plus tard, MUSTELA propose toujours des produits sûrs, efficaces, aux formules les plus naturelles possibles pour protéger la peau sensible des bébés. La gamme de soins quotidiens MUSTELA Bébé est composée de produits conçus pour préserver le capital cellulaire des nourrissons grâce à un actif biomimétique exclusif : le Perséose d’Avocat®. Hydra-Visage Bébé nourrit, protège et restructure en reformant et renforçant le film protecteur de l’épiderme fragile et en le restaurant, préserve la richesse cellulaire de la peau, hydrate et apaise de tout inconfort grâce sa richesse en beurre de karité, huile de jojoba, vitamine E.

Sa formule haute tolérance et hypoallergénique permet de ne pas irriter la peau ni la dessécher.
Sa texture fluide et fondante pénètre rapidement à l’application pour laisser la peau très douce.
Après l’application, la peau de bébé est souple, soyeuse et retrouve tout son confort et sa douceur.',6600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/HDRABEBE.png?v=1690541732',10,1,'7588786995375','42672281583791','https://beautymarket.ma/products/mustela-hydra-bebe-creme-visage-40ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/HDRABEBE.png?v=1690541732"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
