INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ISISPHARMA GLYCO-A INTENSE Peeling 30ml','Isispharma','Visage','La crème de nuit GLYCO-A INTENSE Peeling offre à tous l’efficacité d’un peeling chez soi, avec une concentration d’acide glycolique idéale de 25% pour une peau plus lisse, plus ferme et un teint lumineux; Le pH de GLYCO-A INTENSE Peeling est de 3,1 pour un parfait équilibre entre tolérance de la peau et efficacité du soin.

