INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BATISTE SHAMPOING SEC ET SOIN PROTEGE 200 ML N1','Batiste','Cheveux','Le geste beauté qui permet de redonner un coup de boost à nos cheveux en 3 pschitts sans passer par la case shampooing, cheveux mouillés et brushing c’est juste le rêve. Résultat ? Des cheveux reboostés et 20 minutes de plus sous la couette plutôt que sous son sèche-cheveux ! Au bureau, dans notre sac, à la maison, c’est le petit vapo qui ne nous quitte plus.',7800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/protege.png?v=1691160488',10,1,'7591072399535','42681604735151','https://beautymarket.ma/products/batiste-shampoing-sec-et-soin-protege-200-ml-n1',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/protege.png?v=1691160488"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BATISTE SHAMPOOING SEC BLUSH FLORAL 200ML','Batiste','Cheveux','Fatiguée des cheveux raplapla ou gras qui gâchent ton look ? Le shampoing sec Batiste Blush est ton allié secret pour des cheveux frais, volumineux et délicatement parfumés — sans passer par la case douche !
Sa formule à base de poudre d’amidon de riz absorbe instantanément l’excès de sébum à la racine, tout en redonnant du corps et de la légèreté à la chevelure. Résultat : des cheveux propres à l’œil, texturisés et sublimés d’un volume aérien en quelques secondes seulement.

Son parfum floral doux et sensuel apporte une touche de féminité irrésistible, tandis que son format spray léger permet une application rapide et homogène. Et pour un coup de fraîcheur express où que tu sois, découvre aussi son format mini 50 ml, idéal à glisser dans ton sac à main !
Batiste Blush — ta touche de séduction nomade, fraîche et pétillante.

Composition & bienfaits

Amidon de riz (Oryza Sativa Starch) — absorbe le sébum et donne du volume instantané.
Parfum floral Blush — allie douceur, sensualité et légèreté.
Sans sulfates, sans silicones — respecte la fibre capillaire et laisse un fini naturel.
Formule à sec — rafraîchit sans mouiller ni alourdir les cheveux.

Ingrédients : Butane, Isobutane, Propane, Oryza Sativa (Rice) Starch, Alcohol Denat., Parfum (Fragrance), Cetrimonium Chloride, Distearyldimonium Chloride, Linalool, Butylphenyl Methylpropional.

Résultats visibles

Racines purifiées, sans aspect gras

Volume instantané et effet “cheveux propres”

Chevelure fraîche, souple et légère

Parfum floral irrésistible',5900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3331300062632-1.jpg?v=1767094312',10,1,'7591073349807','42681606635695','https://beautymarket.ma/products/batiste-blush-shampooing-sec-200-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3331300062632-1.jpg?v=1767094312"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
