INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BEXIDENT BAIN DE BOUCHE BLANCHEUR 500ML','Isdin','Bien-être','Le rince-bouche blanchissant Bexident est indiqué pour l’hygiène bucco-dentaire quotidienne dans les situations de changement de couleur des dents, il rend le blanc naturel à vos dents. Il ne provoque pas de sensibilité dentaire associée à l’utilisation d’agents blanchissants. La combinaison de ses ingrédients produit une triple action anti-plaque, empêchant la formation de biofilm buccal, l’un des facteurs déclenchant du changement de couleur des dents.DENT',6900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bexident.png?v=1691162878',10,1,'7591084884143','42681694388399','https://beautymarket.ma/products/bexident-bain-de-bouche-blancheur-500ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bexident.png?v=1691162878"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BEXIDENT BAIN DE BOUCHE DENTS SENSIBLES 250ML','Isdin','Bien-être','Le rince-bouche dents sensibles Bexident est formulé avec des ingrédients qui réduisent la sensibilité (nitrate de potassium), favorisent la minéralisation de l’émail (fluorure de sodium) et anti-plaque qui réduisent les douleurs dentaires et ont des gencives saines et protégées. Grâce à son excipient bioadhésif, son action est prolongée dans le temps. Tous les produits Bexident Dents Sensibles, bien que contenant du nitrate de potassium, ont un goût agréable pour assurer une utilisation à long terme. Pas d’alcool.',5700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dentsensibles.png?v=1691163253',10,1,'7591085605039','42681696682159','https://beautymarket.ma/products/bexident-bain-de-bouche-dents-sensibles-250ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dentsensibles.png?v=1691163253"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
