INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('VITIS GINGIVAL MOUTHWASH 500ML','Vitis','Bien-être','Le bain de bouche gingival VITIS est spécifiquement formulé pour contrôler la gingivite. L’utilisation à long terme aide à prévenir l’inflammation et le saignement gingivaux. Il inhibe également la formation de biofilmoral (plaque bactérienne) et réduit son accumulation dans la cavité buccale.VITIS gingival ne contient pas de gluten et convient donc aux personnes atteintes de la maladie cœliaque.Perméthol –  Réduit le saignement et la sensibilité gingivale tout en augmentant la résistance des gencives à l’inflammation.Panthénol (Provitamine B5) –  Réduit l’inflammation, protège et revitalise les gencives.Chlorure de cétylpyridinium (CPC) – Antiseptique à  usage quotidien qui inhibe la formation de biofilm oral (plaque bactérienne) et réduit son accumulation, contrôlant l’apparition et le développement de la gingivite.Lactate de zinc –  Inhibe et réduit les saignements gingivaux, tout en augmentant l’effet antiseptique du chlorure de cétylpyridinium (CPC).

Conseils dutilisation

Rincer avec 15 ml de rince-bouche gingival VITIS sans diluer pendant 30 secondes.Pour de meilleurs résultats, ne pas rincer à l’eau et éviter de manger ou de boire immédiatement après usage.',8200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DDF.jpg?v=1772644167',10,1,'7591103398063','42681731285167','https://beautymarket.ma/products/vitis-gingival-mouthwash-500ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DDF.jpg?v=1772644167"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Vitis Bain De Bouche Gingival Mouthwash 150ml','Vitis','Bien-être','Le bain de bouche gingival VITIS est spécialement formulé pour prévenir et traiter les saignements et l’inflammation des gencives.',6300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/vitis-gingival-150ml-2_1-e1697189351971.webp?v=1792061212',10,1,'7591103856815','42681731842223','https://beautymarket.ma/products/lightbox-vitis-bain-de-bouche-gingival-mouthwash-150ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/vitis-gingival-150ml-2_1-e1697189351971.webp?v=1792061212"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
