INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAUDALIE VINOPURE LOTION PURIFIANTE PEAU NETTE 200 ML','Caudalie','Visage','Étape fondamentale de votre programme peaux mixtes, la Lotion Vinopure enrichie en acide salicylique naturel, polyphénols de raisins et huiles essentielles bios*, purifie la peau et la prépare à recevoir son soin quotidien. La peau est immédiatement clarifiée, les pores sont resserrés et les imperfections diminuées.

Sa texture eau, ultra-fluide apporte un effet rafraîchissant immédiat.

Interprétation olfactive légère, 100% naturelle, issue du cocktail d''huiles essentielles qui délivre un souffle de fraîcheur à chaque application.',20000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3522931005031.jpg?v=1778603055',10,1,'7591725007023','42684434940079','https://beautymarket.ma/products/caudalie-vinopure-lotion-purifiante-peau-nette-200-ml-1',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3522931005031.jpg?v=1778603055"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
