INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAUDALIE Vinotherapist  Crème Réparatrice Mains et Ongles 75ML','Caudalie','Corps','La Crème Réparatrice Mains et Ongles Vinotherapist™ nourrit et répare les mains sèches sans effet gras, tout en les protégeant de la déshydratation et des agressions extérieures. Les sensations de tiraillements sont apaisées, la peau est plus douce et les ongles et cuticules sont fortifiés.',16500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ther.png?v=1691408408',10,1,'7591728447663','42684454338735','https://beautymarket.ma/products/caudalie-vinotherapist-creme-reparatrice-mains-et-ongles-75ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ther.png?v=1691408408"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAUDALIE Vinotherapist Crème Beauté des Pieds 75ML','Caudalie','Corps','La Crème Beauté des Pieds Vinotherapist™ nourrit et répare les pieds secs, même craquelés. Elle réduit les sensations de tiraillement et les rugosités pour une peau plus douce et plus souple.',19500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/PIES.png?v=1691408568',10,1,'7591728775343','42684454600879','https://beautymarket.ma/products/caudalie-vinotherapist-creme-beaute-des-pieds',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/PIES.png?v=1691408568"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAUDALIE Vinotherapist Soin Corps Nourrissant 400ML','Caudalie','Visage','Le Soin Corps Nourrissant Hyaluronique hydrate et nourrit instantanément pour une peau douce, souple et lumineuse tout au long de la journée, comme après un soin au Spa Vinothérapie™. Sa texture fraîche et légère pénètre rapidement sans effet gras et laisse la peau délicatement parfumée.',39000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/THER1.png?v=1691409020',10,1,'7591729332399','42684455190703','https://beautymarket.ma/products/caudalie-vinotherapist-soin-corps-nourrissant-400ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/THER1.png?v=1691409020"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAUDALIE Vinotherapist Soin Corps Nourrissant 200ML','Caudalie','Visage','Le Soin Corps Nourrissant Hyaluronique hydrate et nourrit instantanément pour une peau douce, souple et lumineuse tout au long de la journée, comme après un soin au Spa Vinothérapie™. Sa texture fraîche et légère pénètre rapidement sans effet gras et laisse la peau délicatement parfumée.

Conseils d''utilisation:

Matin et soir, faites chauffer une noix de Soin Corps Nourrissant Hyaluronique entre vos mains, appliquez-le sur l''ensemble du corps puis massez de bas en haut en mouvements circulaires.',22000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/THERA.png?v=1691409609',10,1,'7591730184367','42684457156783','https://beautymarket.ma/products/caudalie-vinotherapist-soin-corps-nourrissant-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/THERA.png?v=1691409609"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAUDALIE VINOTHERAPIST SOIN BEURRE CORPS 250 ML','Caudalie','Corps','Inspiré de l''expertise des spas VinothérapieTM de Caudalie, ce beurre corporel est composé d''actifs naturels issus de la vigne et du raisin, et enrichi en lipides d''origine végétale. On retrouve notamment l''huile de pépins de raisin, qui est associée à d''autres huiles végétales : dattier du désert, amande douce et tournesol. Ces ingrédients apportent leur richesse en acides gras essentiels et leurs propriétés nourrissantes, assouplissantes et adoucissantes. Le beurre corps Caudalie VinotherapistTM contient également du beurre de karité, réputé pour son action nourrissante, réparatrice et protectrice. Enfin, la glycérine complète la formule et apporte ses vertus émollientes. Elle participe au maintien de la barrière cutané et prévient la déshydratation.',33900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BEURRE.png?v=1691409934',10,1,'7591731167407','42684457615535','https://beautymarket.ma/products/caudalie-vinotherapist-soin-beurre-corps-250-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BEURRE.png?v=1691409934"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MATIS L’ESSENCE EAU DE SOIN SUBLIMATRICE AU CAVIAR 200ML A0210071','Matis Paris','Visage','L’ESSENCE, Eau de soin sublimatrice au CAVIAR, véritable pré-soin, offre une expérience sensorielle parfaite.Sa formule associe toute la puissance du caviar français reconnu pour sa richesse naturelle en oméga-3, protéines, minéraux et vitamines, au collagène marin pour aider jour après jour le visage, à retrouver l’éclat de la jeunesse.',42900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/matis1.png?v=1715349937',10,1,'7591732773039','42684460826799','https://beautymarket.ma/products/matis-l-essence-eau-de-soin-sublimatrice-au-caviar-200ml-a0210071',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/matis1.png?v=1715349937"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MATIS LA CREME SOIN ANTI AGE ABSOLU AU CAVIAR 50ML A0210031','Matis Paris','Visage','LA CRÈME, Soin anti-âge absolu au CAVIAR et à la rose de Damas, offre une solution anti-âge globale unique. Sa formule associe toute la puissance du caviar français, reconnu pour sa richesse naturelle en omégas 3, protéines, minéraux et vitamines, au collagène marin, booster de fibroblastes.',127200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LACREMECAVIAR.png?v=1715349809',10,1,'7591733067951','42684461875375','https://beautymarket.ma/products/matis-la-creme-soin-anti-age-absolu-au-caviar-50ml-a0210031',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LACREMECAVIAR.png?v=1715349809"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MATIS LE SERUM ELIXIR SUPREME AU CAVIAR 30 ML','Matis Paris','Cheveux','Ce soin offre une solution anti-âge globale unique et une expérience sensorielle inédite.Sa formule exceptionnelle au Caviar, reconnu pour sa richesse naturelle en oméga-3, protéines, minéraux et vitamines dynamise le renouvellement cellulaire. Complétée par un puissant actif naturel raffermissant et anti-rides, la peau retrouve sa beauté et sa fermeté.

Conseils d''utilisation:

Appliquer matin et/ou soir sur le visage, le cou et le décolleté avant LA CRÈME ou LA NUIT.',143500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LESERUM.png?v=1715349983',10,1,'7591733723311','42684463218863','https://beautymarket.ma/products/matis-le-serum-elixir-supreme-au-caviar-30-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LESERUM.png?v=1715349983"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MATIS LA NUIT SOIN REGENERANT ABSOLUE AU CAVIAR 50 ML','Matis Paris','Visage','GIFT BOX MATIS LA NUIT SOIN REGENERANT + SAC MATIS en cuir + surprise boxe

Texture luxueuse et réconfortante pour donner à la peau les moyens de réduire les effets du temps. Subissant moins d’agressions extérieures qu’en journée, la nuit, la peau bénéficie d’une certaine « tranquillité ». Nuit après nuit, ce soin absolu au caviar donne à la peau les moyens d’atténuer les effets négatifs de la journée.

Conseils d''utilisation:

Appliquer chaque soir sur le visage et le cou parfaitement nettoyés.',158500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LANUIT.png?v=1715350182',10,1,'7591734050991','42684463775919','https://beautymarket.ma/products/matis-la-nuit-soin-regenerant-absolue-au-caviar-50-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LANUIT.png?v=1715350182"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Fortiphane cheveux et ongles 60 gelules','Fortiphane','Cheveux','Fortiphane gélules est un complément alimentaire apportent toutes les vitamines du groupes B, ainsi que le cystine. cystine et zinc pour une belle croissance de vos cheveux et ongles et une fortification de vos racine de cheveux qui va limiter la perte de cheveux.

Conseils d’utilisation :

2 Gélules Par Jour, le matin.',18600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/FORT.png?v=1691414652',10,1,'7591736869039','42684467478703','https://beautymarket.ma/products/fortiphane-cheveux-et-ongles-60-gelules',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/FORT.png?v=1691414652"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MATIS REPONSE CORRECTIVE LOTION DEFROISSANTE 200 ML','Matis Paris','Visage','Introduisant une nouvelle étape dans votre routine beauté – cette lotion de traitement de haute technologie est le produit préparatoire correctif parfait. Utilisez comme première étape de votre routine de beauté matinale pour lisser les traits et lisser les rides. La lotion HYALU-ESSENCE est enrichie en acide hyaluronique, l’ingrédient phare du secteur de la médecine esthétique. Il est également infusé d’un puissant actif relaxant pour la peau qui s’inspire de la toxine botulique pour adoucir les rides du visage et minimiser les rides de tension. Un ingrédient actif tonifiant est également ajouté pour une peau instantanément plus ferme.

Conseils d''utilisation:

Appliquer avec un coton ou du bout des doigts',39600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MATIS.png?v=1691417031',10,1,'7591752761519','42684588097711','https://beautymarket.ma/products/matis-reponse-corrective-lotion-defroissante-200-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MATIS.png?v=1691417031"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MATIS REPONSE CORRECTIVE HYALURNIC AGE SOIN RIDES PROFONDDES 50ML A1010051','Matis Paris','Visage','Soin rides profondes, de tension et d’expression
Sa formule agit en surface et en profondeur pour combler et lisser les rides. HYALURONIC-AGE associe la puissance de 3 types d’acide hyaluronique, molécule star de la médecine esthétique, de bas poids et haut poids moléculaire et de comblement. L’acide glycolique (classiquement utilisé pour les peelings anti-âge) et un actif à l’effet myo-relaxant renforcent l’action anti-rides globale. Le visage est décontracté, les traits sont lissés, tous les types de rides même profondes sont estompées.',104000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MATIS2.png?v=1691417306',10,1,'7591752925359','42684588458159','https://beautymarket.ma/products/matis-reponse-corrective-hyalurnic-age-soin-rides-profonddes-50ml-a1010051',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MATIS2.png?v=1691417306"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MATIS REPONSE CORRECTIVE HYALUPERF SERUM 30ML','Matis Paris','Cheveux','Avec sa texture fine et fondante, HYALUPERF-SERUM développe son efficacité grâce à un duo d’acide hyaluronique pour une action hautement repulpante et anti-rides. Sa formule associe également l’acide glycolique (pour améliorer la texture et l’apparence de la peau) à un actif myorelaxant (pour limiter les contractions cutanées et ainsi agir sur le creux de la ride). Le visage est décontracté, hydraté, les traits sont lissés, le teint est uniforme.',91000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MATIS3.png?v=1691417567',10,1,'7591753613487','42684589736111','https://beautymarket.ma/products/matis-reponse-corrective-hyaluperf-serum-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MATIS3.png?v=1691417567"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Matis Réponse Corrective Hyaluronic Perf 50 ml – Soin Repulpant & Hydratation Intense','Matis Paris','Visage','Matis Réponse Corrective Hyaluronic Perf – Soin Repulpant 50 ml

Le Matis Réponse Corrective Hyaluronic Perf Soin Repulpant est un soin visage
haute performance formulé pour repulper intensément la peau, lisser les rides
de déshydratation et restaurer un niveau d’hydratation optimal.
Grâce à l’acide hyaluronique, ce soin aide la peau à retrouver volume, souplesse et confort
dès les premières applications.
Un soin hydratant expert très recherché en parapharmacie maroc.

Les Bienfaits du Soin Repulpant Hyaluronic Perf Matis



Hydratation intense : recharge la peau en eau.



Effet repulpant : peau plus rebondie et lissée.



Lisse les rides de déshydratation : grain de peau affiné.



Confort immédiat : sensation de fraîcheur durable.



Texture fondante : pénètre rapidement sans effet gras.

Indications


Peaux déshydratées


Rides de déshydratation


Peaux normales à sèches


Manque de confort et de souplesse

Actifs Clés & Technologie Hyaluronic Perf



Acide hyaluronique : hydrate, repulpe et lisse la peau.



Complexe hydratant : aide à maintenir l’eau au cœur de la peau.



Expertise Matis : soin professionnel haute performance.

Résultats Attendus


Peau visiblement plus hydratée


Effet repulpant immédiat


Rides de déshydratation estompées


Peau douce, souple et confortable

Conseils d’Utilisation


Appliquer matin et/ou soir sur peau propre.


Masser délicatement le visage et le cou.


Utiliser seul ou après un sérum Matis.

Astuce Hydratation

Idéal après un sérum à l’acide hyaluronique pour renforcer l’effet repulpant.

Pourquoi Choisir Matis Chez Beauty Market ?


Soins professionnels disponibles en parapharmacie maroc.


Formules hautement concentrées et efficaces.


Résultats visibles et durables.


Livraison rapide partout au Maroc.

Collections Associées

Découvrir les soins hydratants :

Soins à l’Acide Hyaluronique.

Voir la gamme Matis Réponse Corrective :

Réponse Corrective.',78900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MATIS4.png?v=1691417912',10,1,'7591754694831','42684591308975','https://beautymarket.ma/products/matis-reponse-corrective-hyaluronic-perf-soin-repulpant-50-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MATIS4.png?v=1691417912"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
