INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Ziaja Gel Nettoyant Intime Apaisant à la Camomille – 200ml','Ziaja','Corps','Un gel lavant doux et apaisant aux herbes, conçu pour l''hygiène intime quotidienne, notamment pour les zones sujettes aux irritations. Sa formule gel transparente nettoie délicatement tout en procurant confort, fraîcheur et équilibre du pH physiologique. Enrichi en extrait de camomille, en acide lactique et en provitamine B5, il contribue à apaiser les irritations, à réduire les rougeurs et à préserver la flore vaginale.

Recommandé pour les zones intimes sensibles et adapté à une utilisation pendant la grossesse, dans le cadre d''une routine de soins quotidiens apaisante et protectrice.

Bienfaits de la formule

Nettoie en douceur les zones intimes sans les irriter
Contribue au maintien du pH physiologique
Préserve la flore vaginale
Apaise les irritations, les rougeurs et les sensations d''inconfort
Aide à prévenir les irritations, y compris après l''épilation
Procure une sensation de propreté et de fraîcheur longue durée

Ingrédients et leurs bienfaits

Acide lactique : contribue au maintien du pH physiologique et préserve la flore vaginale, pour une hygiène intime quotidienne protectrice.

Extrait de camomille : apaise les irritations existantes et contribue à prévenir leur apparition. Reconnu pour ses propriétés calmantes, il aide à réduire les rougeurs et à soulager les sensations de démangeaisons et de brûlures. La provitamine B5 (D-panthénol) favorise l''hydratation, apaise les irritations et contribue au confort de l''épiderme.',5900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/5901887044437-1_jpg.webp?v=1776274545',10,1,'7595219779759','42697553674415','https://beautymarket.ma/products/ziaja-gel-nettoyant-intime-apaisant-a-la-camomille-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/5901887044437-1_jpg.webp?v=1776274545"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NEUTROGENA Crème Pieds Très Secs Et Abîmés 100 Ml','Neutrogena','Corps','La crème pieds très secs et abîmés FORMULE NORVEGIENNE®hydrate intensément pour soulager immédiatement même la peau des pieds les plus secs. Développée avec nos dermatologues, sa formule enrichie en glycérine aide à réparer la peau de vos pieds dès le 1er jour, et:

        ?     Assure une hydratation pendant 24h
        ?     Aide à prévenir la formation de rugosités

    Dès la première application, vos pieds sont soulagés, votre peau est visiblement plus douce et plus souple. Sa texture non collante est rapidement absorbée.',5900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3574660183818.jpg?v=1790797036',10,1,'7595236491439','42697592832175','https://beautymarket.ma/products/neutrogena-creme-pieds-tres-secs-et-abimes-100-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3574660183818.jpg?v=1790797036"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
