INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Somatoline Anti-cellulite Gel Cryoactif 250ml','Somatoline','Corps','Le gel Anti-cellulite de Somatoline Cosmetic est formulé pour combattre la cellulite (peau d’orange, nodules, liquides cutanés) . Il s’absorbe rapidement. Sa formule enrichie en principes actifs spécifiques (caféine dosée à 5%, l’extrait de maca et de Physalis angulata) possède action complète contre la cellulite.
Dès 2 semaines d’utilisation, le gel diminue l’aspect des nodules de cellulite et lisse la peau. Les résultats augmentent après 4 semaines de traitement et certains peuvent même doubler

Conseils d’utilisation

Appliquer quotidiennement pendant 15 jours minimum pour avoir des résultats visibles.

Composition

Ingrédients INCI : Aqua,Cyclopentasiloxane, Cafeine, Pentylene Glycol, Alcohol Denat, BIS-PEG-18 Methyl Ether Divethyl Silane, C15-19 Alkane, Polyacrylate Crosspolymer-6, Sodium Salycilate, Physalis Angulata Extract, Lepidium Meyenii Extract, Schinus TerebinThifo Lius Seed Extract, Menthol, Escin, Lecithin, Beta-Sitosterol, 1-3 Propanediol, PEG-8, Parfum, Sodium Benzoate, Dimethicone, Crosspolymer, Dimethicone/Vinyl Dimethicone Crosspolymer, Caprylic/Capric Triglycerine, Divethinocol, Tocopherol, CI28440.',44900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/45299.jpg?v=1792065889',10,1,'7597710344367','42708848312495','https://beautymarket.ma/products/somatoline-anti-cellulite-gel-creoactif-250ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/45299.jpg?v=1792065889","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/45300.jpg?v=1792065898"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Eucerin émollient 10% d''urée urearepair plus 250 ml','Eucerin','Corps','Émollient 10% d’Urée UreaRepair PLUS Lorsque la peau de notre corps présente une fonction barrière stable, elle nous protège des irritants externes et permet de maintenir son niveau optimal d''hydratation. Mais, lorsque la barrière est affaiblie, la peau peut perdre de son hydratation et présenter par conséquent une apparence et une sensation sèche. L''Émollient 10% d’Urée UreaRepair PLUS d''Eucerin procure à la peau très sèche, rugueuse du corps le soin quotidien dont elle a besoin. Elle contient une combinaison unique d''ingrédients – Urée, Céramide et autres Facteurs Naturels d’Hydratation (NMF) – qui fixent l''eau et aident à renforcer la barrière protective naturelle de la peau en la protégeant d''une perte d''eau supplémentaire. Il a été cliniquement et dermatologiquement prouvé que la formule procurait un apaisement immédiat et une hydratation intense et durable, retardant de 48 heures toute sensation de dessèchement et de rugosité. La peau est hydratée intensément et elle est souple et douce au toucher. Cette lotion 10% d''Urée convient aux peaux matures et aux peaux des personnes sujettes au diabète, à la kératose pilaire et au psoriasis. Elle peut aussi être utilisée comme soin d’appoint.',19500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/eucerin-eucerin-emollient-corps-reparateur-10-duree-250-ml-hydratation-corps.jpg?v=1743599478',10,1,'7597719879855','42709020541103','https://beautymarket.ma/products/eucerin-emollient-10-duree-urearepair-plus',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/eucerin-eucerin-emollient-corps-reparateur-10-duree-250-ml-hydratation-corps.jpg?v=1743599478"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
