INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Forte Pharma TURBODRAINE ANANAS 500ML','Forte Pharma','Corps','La boisson Turbo Draine au goût Ananas des laboratoires Forté Pharma est conçue spécialement pour brûler les calories, drainer et purifier l’organisme. Grâce aux propriétés drainantes de la queue de Cerise, l’Hibiscus, le Cactinéa et la Reine des prés, elle élimine efficacement l’eau. Le Thé vert contribue à brûler les graisses tout en stimulant la dégradation au niveau des lipides. Le Ginseng, l’Algue Aosa et la Goyave apportent les ions et les minéraux à l’organisme. La boisson Turbo Draine a un goût agréable et dégage un doux parfum fruité.',18000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ghyty.png?v=1697470117',10,1,'7598116110511','42711708565679','https://beautymarket.ma/products/forte-pharma-turbodraine-ananas-500ml-free-bottle',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ghyty.png?v=1697470117"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
