INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('INNOAESTHETICS DEEP CLEANSER 200ML','Innoaesthetics','Visage','Nettoyant sans huile et non comédogène pour peaux grasses qui détoxifie en profondeur votre peau et élimine toutes les impuretés. Il aide également à réguler la production de sébum, étant idéal pour les peaux à tendance acnéique.',27500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/deep.png?v=1693046227',10,1,'7598665302191','42714634354863','https://beautymarket.ma/products/innoaesthetics-deep-cleanser-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/deep.png?v=1693046227"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Ziaja Med Atopique Lotion Pour Le Corps 400ml','Ziaja','Visage','Recommandé pour les peaux atopiques sujettes aux irritations, fortes démangeaisons et hypersensibles aux allergènes. Restaure la barrière hydrolipidique naturelle de l’épiderme.

Adoucit, hydrate et réduit le dessèchement de la peau.

Apaise les irritations cutanées et prévient leur réapparition. Réduit les démangeaisons, les brûlures et les rougeurs.

Ne contient que les composants essentiels de la formulation.',10300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ET_dd1692fb-677a-4447-ab81-96592ff3ab1c.png?v=1693046865',10,1,'7598665662639','42714634551471','https://beautymarket.ma/products/ziaja-med-atopique-lotion-pour-le-corps-400ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ET_dd1692fb-677a-4447-ab81-96592ff3ab1c.png?v=1693046865"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Ziaja med Atopic Creme 50ml','Ziaja','Visage','Crème visage apaisante aux propriétés hydratantes. Recommandé pour les peaux atopiques sujettes aux irritations, fortes démangeaisons et hypersensibilité aux allergènes. Restaure la barrière hydrolipidique naturelle de l''épiderme.
Adoucit et hydrate la peau. Réduit la sécheresse cutanée et les démangeaisons excessives. Équilibre la flore bactérienne. Apaise les irritations et prévient leur réapparition. Ne contient que les composants essentiels de la formulation.
COMMENT UTILISER
Appliquer sur une peau nettoyée et tapoter délicatement. Utiliser au moins deux fois par jour.',8700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ZIAJA4.png?v=1765984227',10,1,'7598665957551','42714634682543','https://beautymarket.ma/products/ziaja-med-creme-visage-atopique-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ZIAJA4.png?v=1765984227"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Ziaja Med Crème de Jour Protectrice Éclaircissante Spf20 – 50ml','Ziaja','Solaires','Crème pour le visage qui offre une protection élevée contre les rayons UV, aidant à uniformiser le teint de la peau. Émulsion éclaircissante recommandée pour les peaux présentant des taches pigmentaires causées par le soleil, la grossesse et le vieillissement cutané. Prévient et éclaircit les taches brunes, en particulier sur le visage, le cou et le décolleté.

Unifie le teint de la peau.

Lisse l’épiderme.

Retarde le processus de vieillissement cutané.

