INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Ziaja Med Crème Solaire Teintée Natural Spf50 - 50ml','Ziaja','Solaires','Cette crème neutralise les radicaux libres responsables du photovieillissement. Unifie le teint et couvre les imperfections cutanées. Restaure l’éclat de la jeunesse. Prévient les coups de soleil et la décoloration de la peau. Protège les lésions pigmentaires épidermiques – marques et grains de beauté. Ingrédients clés : filtres UVA/UVB photostables, vitamine E, provitamine B5, pigments qui procurent un effet maquillage naturel.',14800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ZIAJA11.png?v=1693052611',10,1,'7598679818415','42714672562351','https://beautymarket.ma/products/ziaja-med-creme-solaire-teintee-natural-spf50-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ZIAJA11.png?v=1693052611"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
