INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NIACIDE ADVANCE CREME 50g','Niacide','Visage','NIACIDE Crème est indiqué comme adjuvant au traitement d''acné. NIACIDE existe sous forme de base crémeuse pour des peaux sèches et irritables. Cette formulation au PH neutre, garanti une réelle efficacité dans le controle et la correction de l''acné, avec une dimension cosmétique effective, résultant de l''incorporation des acides a-hydroxy et de l''acide salicylique. NAICIDE crème est dépourvu et potentiel irritant, allergisant ou photosensibilisant.',18900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/nicidecreme.png?v=1693303200',10,1,'7599402549423','42717719658671','https://beautymarket.ma/products/niacide-creme-50g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/nicidecreme.png?v=1693303200"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
