INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVITALASH COLLECTION POUR LASH','RevitaLash','Autres soins','Ce sérum primé et leader dans sa catégorie est doté d’une technologie exclusive et scientifiquement avancée pour renforcer les cils et les protéger contre la casse tout en améliorant la flexibilité et la brillance, ce qui donne des cils d’apparence spectaculaire.
Une formule révolutionnaire de masque pour les cils et les sourcils s’attaque aux signes visibles et physiques des cils et des sourcils fragilisés. Que ce soit en raison d’un coiffage excessif, d’un maquillage quotidien ou de dommages causés par des services professionnels de cils ou de sourcils, ce masque répare les cheveux abîmés et fragilisés en les infusant d’une explosion immédiate d’ingrédients intenses et riches en nutriments pour favoriser l’apparence de cheveux plus sains, plus doux, des cheveux plus brillants et plus souples.',144700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ummer.png?v=1694699542',10,1,'7604276134063','42738619875503','https://beautymarket.ma/products/revitalash-collection-pour-cils',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ummer.png?v=1694699542"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('JANSSEN Crème Raffermissante Légère | 50ml','Janssen Cosmetics','Visage','Appliquer matin et/ou soir sur la peau nettoyée du visage, du cou et du décolleté et laisser pénétrer. Base idéale pour le maquillage.',45800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/GYF.png?v=1694704509',10,1,'7604317978799','42738696618159','https://beautymarket.ma/products/janssen-creme-raffermissante-legere-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/GYF.png?v=1694704509"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
