INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('A-DERMA Pain dermatologique apaisant 100GR','A-Derma','Visage','Enrichi en lait d’avoine, le pain dermatologique Aderma est différent des savons traditionnels, décapants et trop agressifs pour les peaux sensibles ou réactives.',7000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/aderma-pain-dermatologique-apaisant-100g-2.webp?v=1781611938',10,1,'7604737704111','42740965245103','https://beautymarket.ma/products/a-derma-pain-lait-avoine-100gr',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/aderma-pain-dermatologique-apaisant-100g-2.webp?v=1781611938","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hg_9e75e722-ab1d-466a-af2b-3cb714925b72.jpg?v=1715072247"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NEORETIN TRANSITION CREME 50ML','Cantabria','Visage','Neoretin Discrom Control Transition Cream Pigment Lightener  est une crème de lissage non comédogène à utiliser en alternance avec l"éclaireur pigmentaire en émulsion Neoretin Discrom Control Ultra. Cette crème de confort contient une formulation d"acide tranexamique (0,5%) et de niacinamide qui sont des agents dépigmentants qui rétablissent également l"équilibre physiologique de la peau, renforçant ainsi sa fonction de barrière. De plus, sa composition est enrichie avec la technologie RetinSphere® qui donnera à la peau une texture plus élastique et plus ferme. Enfin, EDAFENCE® protège la peau de la pollution et des agressions environnementales. Ce produit testé dermatologiquement et ophtalmologiquement optimise les processus de rétinisation et assure une tolérance optimale sur la peau. Dans l’ensemble, cette crème agit comme un maintien des résultats après l’utilisation du Pigment Lightener Neoretin Discrom Control Ultra ou d’autres traitements dépigmentants.',39800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/uu.png?v=1695037098',10,1,'7605159428271','42742819651759','https://beautymarket.ma/products/neoretin-transition-creme-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/uu.png?v=1695037098"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CLINICEUTICA CERACAP AC LOTION ENERGISANT 150ML','Cliniceutica','Cheveux','La Lotion énergisante CERACAP AC est spécifiquement formulée à partir d’ingrédients hautement qualifiés pour fortifier, renforcer et aider à fournir visiblement des cheveux clairsemés en complément d’un traitement anti- chute. ansi que du palmier nain et ortie piquante aux propriétés revitalisantes et volumisantes. Un apport riche en Ceramides, en Papyrus et en Caféine vous procurera tous les éléments essentiels pour hydrater et améliorer l’apparence de cheveux fins, clairsemés et fragilisés.',36000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/150CERR.png?v=1695037188',10,1,'7605164736687','42742828630191','https://beautymarket.ma/products/clinceutica-ceracap-ac-lotion-energisant-150ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/150CERR.png?v=1695037188"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Cliniceutica Ceracap NR Shampooing Nutri-Réparateur – 250ml','Cliniceutica','Cheveux','Le shampooing ceracap NR réparateur nourrissant est spécifiquement formulé à partir d’ingrédients hautement nutritifs et réparateurs de la tige capillaire. La combinaison exclusive de Céramides, de Xylishine™ et d’huile de Macadamia, riche en acides gras, favorise les cheveux secs et abîmés avec tous les éléments essentiels pour aider à apporter force, volume, brillance et effet soyeux.',17900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/2020D.png?v=1695037352',10,1,'7605165129903','42742829482159','https://beautymarket.ma/products/cliniceutica-ceracap-nr-shampooing-nutri-reparateur-250ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/2020D.png?v=1695037352"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CLINICEUTICA CERACAP MASQUE NUTRI REPARATEUR 200ML','Cliniceutica','Cheveux','CHEVEUX SECS ET ABÎMÉS

Le Masque NUTRI-RÉPARATEUR CERACAP NR est particulièrement formulé à partir d’une combinaison riche en céramides en Xylishine ™ et en huile de Macadamia. L’utilisation du système Keratrix ™ à libération prolongée d’agents réparateurs procurent aux cheveux secs et abîmés tous les éléments essentiels afin d’améliorer la souplesse, la force, le volume et la brillance du cheveux avec un effet démêlant et soyeux.',22700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SRD.png?v=1695037723',10,1,'7605165588655','42742833545391','https://beautymarket.ma/products/cliniceutica-ceracap-masque-nutri-reparateur-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SRD.png?v=1695037723"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
