INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ISDIN CICAPOST CREME 50G','Isdin','Corps','ISDN Cicapost est une crème réparatrice spécifique pour le soin dermatologique des zones cutanées cicatricielles. Une cicatrice est le résultat final d’un processus de cicatrisation, qui peut être le résultat d’une intervention chirurgicale ou d’une blessure accidentelle, et son tissu est plus fragile, moins élastique et vascularisé, et généralement plus pigmenté que le tissu normal.',14300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/itr.png?v=1695117368',10,1,'7605372518575','42744032231599','https://beautymarket.ma/products/isdin-cicapost-creme-50g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/itr.png?v=1695117368"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DARK SPOT ERASER [DSE Plus+] 24H CREAM','Innoaesthetics','Autres soins','Achetez Innoaesthetics Dark Spot Eraser Crème Anti-Points Noirs -',94500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dark-spot-eraser_1.jpg?v=1695119909',10,1,'7605376516271','42744037572783','https://beautymarket.ma/products/dark-spot-eraser-dse-plus-24h-cream',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dark-spot-eraser_1.jpg?v=1695119909"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET Bois d''orange eau parfumee 100ml','Roger&Gallet','Corps','Une orange gorgée de jus comme une explosion de vitamines, la fraîcheur ensoleillée de la feuille et du fruit, le parfum texturisé et vibrant du bois. Hommage aux agrumes qu’il affectionne particulièrement, le Maître Parfumeur Dominique Ropion a imaginé un parfum qui réunit toutes les dimensions de l''oranger amer, des racines jusqu''à la cime, ses branches, ses feuilles et ses fruits… Enrichi d’essence naturelle d''orange amère aux vertus énergisantes, Bois d''Orange est un parfum qui redonne le sourire. Le cœur du fruit s''offre juteux, vitaminé, généreux, nuancé par l''amertume rieuse du petit-grain et la sensualité boisée du patchouli.',56000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bois1.png?v=1695134195',10,1,'7605410594991','42744129814703','https://beautymarket.ma/products/roger-gallet-bois-dorange-eau-parfumee-100ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bois1.png?v=1695134195","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bois.png?v=1695134196"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CLINICEUTICA CERACAP. NR SERUM ELIXIR LISSANT 115ML','Cliniceutica','Cheveux','Le Sérum CERACAP NR est un Élixir capillaire lissant et Nutri-réparateur, idéal pour les cheveux secs, abimés, rebelles et difficiles à coiffer. Sa formule douce et luxueuse riche en Céramides A2 et en huile de Macadamia, aide à nourrir les cheveux fragilisés, combattre les frisottis et réparer visiblement les pointes fourchues, tout en protégeant la chevelure de la décoloration et de la chaleur. Les cheveux sont immédiatement soyeux, souples et faciles à coiffer.

Conseils d''utilisation:

Appliquer généreusement une quantité de sérum sur les cheveux secs ou essorés, en insistant sur les longueurs et pointes fourchues. Peignez pour répartir uniformément et laisser sécher naturellement ou au séchoir.

Ne pas rincer.

Au besoin, 3 à 4 fois par semaine.',33300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ttt.png?v=1695136752',10,1,'7605417902255','42744149246127','https://beautymarket.ma/products/cliniceutica-ceracap-nr-serum-elixir-lissant-115ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ttt.png?v=1695136752"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET Bois D''orange Gel Douche Bienfaisant 200ml','Roger&Gallet','Corps','Une orange gorgée de jus comme une explosion de vitamines, la fraîcheur ensoleillée de la feuille et du fruit, le parfum texturisé et vibrant du bois... Enrichi d''Essence naturelle d''orange amère aux vertus énergisantes et d''aloe vera, le Gel Douche Bienfaisant Bois d''Orange à la mousse onctueuse réveille nos sens. Sa base lavante est 100% d''origine végétale pour une application ultra-douce pour la peau et facile à rincer. Sous la douche ou dans le bain, sa mousse fine et généreuse laisse votre peau hydratée et délicieusement parfumées aux notes vitaminées et boisées de Bois d''Orange.',13000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/drtxdr.png?v=1695137327',10,1,'7605419933871','42744156192943','https://beautymarket.ma/products/roger-gallet-gel-douche-bienfaisant-200ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/drtxdr.png?v=1695137327"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET BOIS D''ORANGE Savon Bienfaisant 100 g','Roger&Gallet','Corps','',9500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fycf.png?v=1695138338',10,1,'7605422751919','42744167727279','https://beautymarket.ma/products/roger-gallet-bois-dorange-savon-bienfaisant-100-g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fycf.png?v=1695138338"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET Cedrat gel douche 200ml','Roger&Gallet','Corps','Une balade au grand air sur les terres de la Méditerranée. Le vent qui déferle sur la peau et insuffle une nouvelle énergie. Le gel douche bienfaisant Cédrat à la mousse onctueuse révèle les notes boisées pétillantes de la pulpe du cédrat balayées par une friction de notes aromatiques, cardamone, basilic, thym. Enrichi d''huile essentielle de Cédrat aux vertues naturellement vivifiantes et d''aloe vera, sa base lavante est 100% d''origine végétale pour une application ultra-douce pour la peau et facile à rincer. Sous la douche ou dans le bain, sa mousse fine et généreuse laisse votre peau hydratée et délicieusement parfumée aux notes citronnées aromatiques de Cédrat.',13000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/gelceedr.png?v=1695199074',10,1,'7605667365039','42745209684143','https://beautymarket.ma/products/roger-gallet-cedrat-gel-douche-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/gelceedr.png?v=1695199074"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET CEDRAT eau parfumee 100ml','Roger&Gallet','Corps','Une balade au grand air sur les terres de la Méditerranée. Le vent qui déferle sur la peau et insuffle une nouvelle énergie. La mer n''est pas loin, on peut la deviner. Le duo de Maîtres Parfumeurs Karine Dubreuil et Mathilde Bijaoui ont imaginé un trio d''agrumes balayé par le vent et enrichi d''huile essentielle de cédrat aux vertus naturellement vivifiantes. Les notes pétillantes de la pulpe du cédrat se mêlent au sillage légèrement boisé de son écorce. Une fraîcheur qui atteint le summum de sa puissance au contact d''une friction de notes aromatiques, cardamone, basilic, thym.',56000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cedr.png?v=1695199251',10,1,'7605667627183','42745210110127','https://beautymarket.ma/products/roger-gallet-cedrat-eau-parfumee-100ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cedr.png?v=1695199251"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET CÉDRAT SAVON BIENFAISANT 100G','Roger&Gallet','Corps','La fraicheur au grand air d’un zeste pur de cédrat frictionné de notes aromatiques sauvages : cardamone, basilic, thym.',9500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cedartsavon.png?v=1695199985',10,1,'7605669068975','42745214632111','https://beautymarket.ma/products/roger-gallet-cedrat-savon-bienfaisant-100g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cedartsavon.png?v=1695199985"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('K-ACNE Crème Anti-Imperfections Matifiante et Hydratante 40 ml – Soin visage purifiant','Kaline','Visage','K-ACNE Crème Anti-Imperfections Matifiante et Hydratante 40 ml

La K-ACNE Crème Anti-Imperfections Matifiante et Hydratante est un soin dermatologique complet qui matifie, purifie et hydrate la peau tout en réduisant visiblement les imperfections. Adaptée aux peaux mixtes à grasses, cette crème aide à désobstruer les pores, affiner le grain de peau et restaurer la barrière cutanée.


Les bienfaits de la K-ACNE Crème Anti-Imperfections

Matifie et désobstrue les pores

Sa formule à base d’acide salicylique et de bakuchiol aide à éliminer les impuretés, resserrer les pores et prévenir la formation de nouvelles imperfections tout en maintenant une peau nette et lisse.

Affinement du grain de peau

Grâce à son Effect Plus Complex et son action kératolytique douce, elle affine le grain de peau sans irriter ni dessécher. Le teint est plus uniforme, la peau plus douce et visiblement purifiée.

Hydrate et renforce la barrière cutanée

Enrichie en niacinamide et en post-biotiques marins, cette crème hydrate intensément tout en renforçant la barrière protectrice naturelle de la peau. Elle réduit les rougeurs et favorise la cicatrisation des imperfections.

Formule dermatologique testée

Sans paraben

Sans phénoxyéthanol

Sans silicone volatile

Testée sous contrôle dermatologique

Avec parfum hypoallergénique

Composition clé

Effect Plus Complex – action purifiante et équilibrante

Acide Salicylique – désincruste et régule l’excès de sébum

Post-biotiques marins – rééquilibrent le microbiome cutané

Niacinamide – apaise, répare et unifie le teint

Bakuchiol – l’actif végétal anti-imperfections et anti-âge

Conseils d’utilisation

Appliquez le soir sur une peau propre et sèche, en couche fine sur l’ensemble du visage. Peut s’utiliser quotidiennement en soin unique ou après un sérum purifiant. Évitez le contour des yeux.

Résultat beauté

Une peau nette, matifiée et hydratée dès les premières applications. Les pores sont resserrés, les imperfections diminuées et le teint retrouve son éclat naturel.



Où acheter K-ACNE Maroc ?',8600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DSC_3190_50eeb99a-94df-4a31-a625-94aba3a718b3.jpg?v=1762357549',10,1,'7605674410159','42745220104367','https://beautymarket.ma/products/kaline-k-acne-creme-anti-imperfections-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DSC_3190_50eeb99a-94df-4a31-a625-94aba3a718b3.jpg?v=1762357549"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
