INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Maybelline New York - Brillant à lèvres Superstay Vinyl Ink - 45 Capricious','Maybelline','Maquillage','Maybelline New York – Encre à lèvres effet vinyl longue tenue, ultra-confortable et sans transfert, tenue 16h
Vinyl Ink habille vos lèvres d''une couleur ultra-saturée, ultra-glossy. Sans transfert
Secouer le pack pendant 5 secondes avant application. L''application flèche permet un tracé précis et glisse sur les lèvres pour délivrer une fiche couche de formule.
(Auto-évaluation de 114 femmes)',12300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/24947_1_Maybelline_Fluessig-Lippenstift_-_Superstay_Vinyl_Ink_1.jpg?v=1770133385',10,1,'7608618418351','42756601151663','https://beautymarket.ma/products/maybelline-new-york-brillant-a-levres-superstay-vinyl-ink-45-capricious',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/24947_1_Maybelline_Fluessig-Lippenstift_-_Superstay_Vinyl_Ink_1.jpg?v=1770133385","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/45gg.png?v=1770133385"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SKIN CHEMISTS LOTION ECLAIRCISSANTE ADVANCEE 250ML','SkinChemists','Visage','LA LOTION A DES PROPRIÉTÉS NOURISSANTES POUR LE TEINT, ELLE EST ENRICHIE EN VITAMINE B3, VITAMINE C ET PROVITAMINE B5. CETTE LOTION EST SOYEUSE, DE TEXTURE LÉGÈRE, HYDRATE, RÉDUIT LES PORES ET REND LA PEAU PÂLE.',36000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fgytf.png?v=1696075198',10,1,'7608761352367','42757453054127','https://beautymarket.ma/products/skin-chemists-lotion-eclaircissante-advancee-250ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fgytf.png?v=1696075198"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DEPILIA CICAPRO PLUS CREME REPARATRICE 50ML','Depilia','Visage','DEPILIA CICAPRO PLUS est une crème réparatrice, émolliente, hydratante, et apaisante spécialement développée pour les peaux sensibles du nourrisson, l’enfant, et l’adulte. Enrichie en Extrait de Centella Asiatica, Miel, Propolis, Allantoïne, Aloe Vera, Vitamine B3,  Provitamine B5, Vitamine E, Huiles de Ricin, d’olive, et d’amande douce.

CICAPRO PLUS stimule la régénération cellulaire pour une meilleure cicatrisation.

CICAPRO PLUS est recommandée dans les phénomènes irritatifs cutanés et après petites chirurgies dermatologiques. Elle forme un film hydrolipidique protecteur créant ainsi les conditions favorables à la cicatrisation. Elle apporte du confort en assouplissant la peau et en soulageant les tiraillements.',15200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/TY7Y.png?v=1696236027',10,1,'7608762073263','42757453709487','https://beautymarket.ma/products/depilia-cicapro-plus-creme-reparatrice-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/TY7Y.png?v=1696236027"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Cerave crème lavante hydratante 473 ml','Cerave','Visage','Nettoie et hydrate en douceur, aide à renforcer la barrière protectrice de la peau. Texture crémeuse, hydratante et non moussante. Idéal pour toute la famille.

• Besoin : Nettoyer | Hydrater | Peau normale à sèche | Peau sensible.
• Ingrédients Clés : Céramides (1, 3 et 6-II) pour protéger et nourrir | Acide Hyaluronique pour maintenir la peau hydratée.
• Sécurité : Sans Parfum | Hypoallergénique | Non-Comédogène.
• Utilisation : Appliquer sur une peau humide. Rincer à l’eau. Visage et Corps.

Approuvé par les membres de l’Association Française de l’Eczéma.

Caractéristiques :
Développée avec des dermatologues, la Crème Lavante Hydratante CeraVe nettoie et hydrate efficacement sans altérer la barrière protectrice de la peau. Enrichie aux 3 céramides essentiels (1, 3, 6-II) et acide hyaluronique, cette crème onctueuse, non moussante, nettoie et hydrate la peau dès la première utilisation, tout en laissant un fini de peau doux et soyeux.

– Texture crémeuse, hydratante et non moussante.

Sécurité :
– Sans Parfum.
– Hypoallergénique.
– Testé sous contrôle dermatologique.
– Non-Comédogène : ne bouche pas les pores.

Ingrédients & Principes Actifs Clés :
– 3 Céramides Essentiels : tous les produits CeraVe contiennent les 3 céramides essentiels (1, 3 et 6-II) dont une peau saine a besoin pour restaurer et maintenir sa barrière protectrice naturelle.

– Technologie brevetée de diffusion MVE : libération contrôlée et prolongée d’actifs pour une hydratation continue pendant 24h.

– Acide hyaluronique : maintient l’hydratation naturelle de la peau.

Conseils d’Utilisation :
– Appliquez quotidiennement sous la douche votre crème lavante.
– Déposez une noisette de crème onctueuse au creux de votre main et appliquez sur votre peau humide ; visage et corps. Evitez le contour des yeux.
– Ensuite, rincez soigneusement à l’eau claire puis séchez délicatement.',14600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1.jpg_e.jpg?v=1737563476',10,1,'7609023594671','42759425654959','https://beautymarket.ma/products/cerave-creme-lavante-hydratante-473-ml-1',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1.jpg_e.jpg?v=1737563476","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cerave-creme-lavante-hydratante-peau-normale-a-seche-473ml-2.jpg?v=1737563476","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cerave-creme-lavante-hydratante-peau-normale-a-seche-473ml-5.jpg?v=1737563476","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cerave-creme-lavante-hydratante-peau-normale-a-seche-473ml-6.jpg?v=1737563476","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cerave-creme-lavante-hydratante-peau-normale-a-seche-473ml-9.jpg?v=1737563476"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('L''oréal paris -telescopic lift mascara - washable','L''Oréal Paris','Maquillage','Découvrez le nouveau Mascara volume et longueur Telescopic Lift de L''Oréal Paris. Jusqu''à +5mm de longueur visible pour des cils d''une autre dimension. Sa formule est enrichie en céramide pour des cils intensément fortifiés. Sa brosse exclusive aux picots double face vous procurera longueur et lift. S''adapte à tous les types de cils.

Conseils d''application:
1. Réhaussez et courbez vos cils à l''aide des picots avant de la brosse, de la racine jusqu''aux pointes.
2. Utilisez les picots latéraux pour séparer vos cils et obtenir plus de volume et de longueur.

