INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Souakine Bain De Bouche Plus 500ml','Souakine','Hygiène','L’écorce séchée de jeunes rameaux de noyer appelé « SOUAK » est utilisée depuis des millénaires comme stimulateur gingivo-dentaire ayant la qualité de libérer des composants trés efficaces pour l’hygiène et le soin bucco-dentaire tels que: tanins, juglone et complexe vitaminique. Le BAIN DE BOUCHE SOUAKINE tonifie et renforce les gencives sensibles, combat la fragilité ginvivo-dentaire et purifie l’haleine.

Conseils d’utilisation
