INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DUCRAY DEXYANE MeD Palpébral 15ml','Ducray','Visage','DEXYANE MeD Palpébral est un dispositif médical* traitant les eczémas atopiques ou de contact localisés sur les paupières• Sa formule hautement hydratante agit tel un pansement qui, d''une part soulage et décongestionne, et d''autre part restaure la barrière cutanée et limite l''adhésion des bactéries• Une efficacité cliniquement démontrée et une bonne tolérance• À utiliser seul, en association ou en relais des dermocorticoïdes pour traiter les lésions d''eczémas et limiter leur réapparition*DEXYANE MeD Palpébral est un dispositif médical, produit de santé réglementé qui porte au titre de cette règlementation le marquage CE. Lire attentivement les instructions figurant dans la notice. Ne pas utiliser sur la femme enceinte ou allaitante. Eviter tout contact direct avec les yeux.

Conseils d''utilisation:

• Appliquer en fine couche directement sur les lésions inflammatoires d’eczéma des paupières avec un doigt propre, en évitant tout contact avec l’œil
• Usage externe
• A utiliser seul, en association et/ou en relais des dermo-corticoïdes',15500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ducray-ducray-dexyane-med-palpebral-15ml-yeux.jpg?v=1711028546',10,1,'7618972745903','42798946713775','https://beautymarket.ma/products/ducray-dexyane-med-palpebral-15ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ducray-ducray-dexyane-med-palpebral-15ml-yeux.jpg?v=1711028546"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
