INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ADDAX EXPERT SOLUTION ONGLES ABIMES ET MYCOSES 3ML','Addax','Corps','ADDAX EXPERT SOLUTION ONGLES MYCOSES d OMEGA PHARMA est un soin sous forme de dispositif médical et indiqué dans le traitement et la prévention des infections fongiques des ongles. Il permet d éliminer rapidement et efficacement les mycoses des ongles. La SOLUTION ONGLES MYCOSES ADDAX EXPERT permet également de prévenir la propagation des mycoses, par formation d un film protecteur non perméable sur votre ongle qui détruit les champignons à l origine de la mycose.

Conseils d''utilisation :

Appliquez ADDAX EXPERT SOLUTION ONGLES MYCOSES matin et soir sur vos ongles soigneusement nettoyés. - Commencez par secouer le tube afin d homogénéiser le soin. - Appliquez ensuite 3 fois de suite sur l ongle atteint, en laissant sécher entre chaque couche. - Poursuivez l application matin et soir durant 4 à 12 semaines. Surtout, n utilisez pas de vernis cosmétiques ou toutes autres applications qui réduiraient l efficacité de votre soin OMEGA PHARMA. Continuez le traitement jusqu à la disparition complète des symptômes.',12300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ADDAX-EXPERT-SOLUTION-ONGLES-ABIMES-ET-MYCOSES-3ML.jpg?v=1697805698',10,1,'7624428945583','42814016553135','https://beautymarket.ma/products/addax-expert-solution-ongles-abimes-et-mycoses-3ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ADDAX-EXPERT-SOLUTION-ONGLES-ABIMES-ET-MYCOSES-3ML.jpg?v=1697805698"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
