INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SVR Biotic Cera Baume Régénérant Comblant 50 ml','SVR','Visage','SVR Biotic Cera Baume Régénérant Comblant 50 ml est un baume qui est fait pour régénérer votre peau grâce à une combinaison de 4 actifs essentiels à la fonction de la peau :

des probiotiques pasteurisés : ils protègent et renforcent la barrière cutanée. de la vitamine C stabilisée : elle protège des radicaux libres, raffermie et défatigue la peau. de l''Acide Hyaluronique : il lisse les rides, les ridules et hydrate. Les céramides : restaurent la barrières cutanée, corrigent les rides. Jour après jour, la peau est nourrie, comblée et lissée. Souvent confondue avec la déshydratation qui est un état cutané, la peau sèche est un type de peau à part entière et les peaux fines et sensibles y sont plus sujettes. Lorsqu''elle est sèche, la peau est en manque de lipides dont les céramides et elle ne peut plus assurer correctement son rôle de barrière de protection. La peau devient perméable aux agents pathogènes et se déshydrate.',32700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cera-biotic_2000x2000_1_600x600_crop_center_947c8ff3-ccf0-40ba-b814-b1c7405e742a.jpg?v=1698238832',10,1,'7630491910319','42834254856367','https://beautymarket.ma/products/svr-biotic-cera-baume-regenerant-comblant-50-ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/cera-biotic_2000x2000_1_600x600_crop_center_947c8ff3-ccf0-40ba-b814-b1c7405e742a.jpg?v=1698238832"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('EUCERIN DERMOPURE CLINICAL GEL NETTOYANT CORRECTEUR 150ML','Eucerin','Visage','Le Gel Nettoyant Triple Action DermoPure d''Eucerin avec 2 % d''Acide Salicylique vous permet enfin d''aider à lutter contre les imperfections et les marques post-acné grâce à 3 facteurs clés :

1. Anti-imperfections: 2 % d''Acide Salicylique antibactérien pour réduire efficacement les imperfections et désobstruer les pores
2. Anti-marques : Complexe exfoliant d''acides AHA/BHA/PHA pour aider à éliminer les cellules mortes et à réduire les marques d''hyperpigmentation post-inflammatoire.
3. Anti-brillance: Nettoie pour éliminer l''excès de sébum, les impuretés et le maquillage.',15600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Eucerin-Dermopure-Gel-Nettoyant.webp?v=1767345357',10,1,'7630582153391','42834618187951','https://beautymarket.ma/products/eucerin-dermopure-gel-nettoyant-triple-action-150-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Eucerin-Dermopure-Gel-Nettoyant.webp?v=1767345357","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/49c5cb3a20a441e3bcd94a2d7a6be0fb-screen.webp?v=1767345357"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('AVENT BIBERON NATURAL 4.0 TEAT 6M+ 330ML SCY906/01','Philips Avent','Bébé & Maman','• Tétine à Réponse Naturelle : la tétine de ce biberon Philips Avent permet au bébé de téter et de se nourrir confortablement à son propre rythme.
• Fonctionne comme le sein : la tétine libère le lait lorsque le bébé tète activement, ce qui est différent des tétines traditionnelles à débit libre. Comme pour l’allaitement, il faut du temps pour que le bébé s’y habitue.
• Valve anti-coliques : les biberons Philips Avent sont conçus pour empêcher l’air d’entrer dans le ventre du bébé pendant la tétée.
• Le bon débit pour la tétine : trouvez le débit idéal pour votre bébé et personnalisez votre biberon Philips Avent.
• Tétine anti-goutte : l’ouverture de la tétine du biberon libère le lait uniquement lorsque le bébé tète.',15200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1_543d1ac4-9c93-4a2e-87f6-0c1687ad5559.png?v=1786440417',10,1,'7630592016559','42834664685743','https://beautymarket.ma/products/avent-biberon-naturel-330ml-scf036-17',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1_543d1ac4-9c93-4a2e-87f6-0c1687ad5559.png?v=1786440417","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/2_51f1e3dd-71e5-491a-bdbe-a76cbdbb0ee4.png?v=1786440417"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
