INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Klorane change Eryteal 3 en 1 au Calendula BIO apaisant - Bébé - Change 100 ML','Klorane','Bébé & Maman','Conçue pour le change, la Pommade Eryteal Klorane Bébé 3 en 1 apaise dès la première application, assainit et favorise la réduction des rougeurs du siège exposé à l''acidité et à l''humidité. Ce soin ciblé est enrichi en Calendula, huile d''olive et oxyde de zinc, actifs naturels apaisants et protecteurs. Sa formule onctueuse sans parfum soulage les sensations d''inconfort et limite la prolifération bactérienne, pour prendre quotidiennement soin des fesses fragiles de bébé.

"- Apaise : la texture riche de la Pommade change Eryteal procure soin et confort au fessier de bébé, pour un soulagement dès la première application.
- Assainit : enrichie en oxyde de zinc protecteur aux vertus antibactériennes, la pommade assainit l''épiderme et empêche l''aggravation des rougeurs du siège et des irritations liées à la sécheresse.
- Protège : la pommade contient de l''huile d''olive, riche en acide gras, pour aider à réparer le film hydrolipidique de la peau et faire barrière face aux agressions."

Appliquer en couche épaisse après chaque change sur une peau propre et sèche.',10000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/klorane-bebe-eryteal-pommade-75ml_1.webp?v=1724833803',10,1,'7644151316655','42867490422959','https://beautymarket.ma/products/klorane-bebe-eryteal-creme',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/klorane-bebe-eryteal-pommade-75ml_1.webp?v=1724833803"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
