INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('La roche posay lipikar lait urea 10% 400 ml','La Roche-Posay','Corps','Peau sèche, rugueuse et squameuse. Convient aux enfants, aux adultes et aux personnes âgées. Convient également aux peaux sujettes à la kératose pilaire, à la xérose et au psoriasis.',23600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1_06d0fcfe-5fe4-4199-baf6-c1abe2b65582.jpg?v=1714654425',10,1,'7658292347055','42904773787823','https://beautymarket.ma/products/la-roche-posay-lipikar-lait-urea-10-400-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1_06d0fcfe-5fe4-4199-baf6-c1abe2b65582.jpg?v=1714654425"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
