INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('bjorn axen creme smooth a l''huile d''argan 150 ml','Björn Axén','Cheveux','Une crème coiffante lissante et nourrissante enrichie en huile d''argan bio et en kératine vegan. Il offre une protection contre la chaleur, réduit les frisottis ainsi que répare et renforce. Convient aux cheveux épais, crépus, épais et secs nécessitant un contrôle supplémentaire. Laisse les cheveux doux et lisses avec beaucoup de brillance. Le produit est végétalien et testé dermatologiquement.',24800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/wsrsdtr.png?v=1719588207',10,1,'7669502738607','42943958483119','https://beautymarket.ma/products/bjorn-axen-creme-smooth-a-lhuile-dargan-150-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/wsrsdtr.png?v=1719588207"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
