INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Ziaja Elegance Déodorant Crème Anti-Transpirante – 60ml','Ziaja','Corps','Inhibe les processus de transpiration. Régule l’activité des glandes sudoripares, ce qui entraîne une réduction de la quantité de sueur. A un parfum délicat de note de fleur de coton blanc. La combinaison d’ingrédients crée un parfum unique rappelant le satin doux, le cachemire et la soie.',4900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ziaja-elegance-anti-transpirant-60ml.jpg?v=1701361972',10,1,'7672454447279','42951402422447','https://beautymarket.ma/products/ziaja-elegance-deodorant-creme-anti-transpirante-60ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ziaja-elegance-anti-transpirant-60ml.jpg?v=1701361972"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Babybio Petits Pots bébé Carotte Patate douce Blé','Babybio','Bébé & Maman','Idéal pour le repas du soir, avant le coucher, le petit pot bébé Babybio réunit de la carotte des Landes, de la patate douce et du blé, dans un délicieux menu équilibré et riche en saveur. Cette denrée convient spécialement aux enfants âgés d''au moins 6 mois et permet d''accompagner la diversification alimentaire. Chaque légume a été finement sélectionné et provient d''une agriculture biologique, garante de la qualité de la nourriture, sans trace de pesticide.',4700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RSDRTR.png?v=1701442629',10,1,'7672698142895','42953256534191','https://beautymarket.ma/products/babybio-petits-pots-bebe-carotte-patate-douce-ble',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RSDRTR.png?v=1701442629","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/rere.png?v=1701442689"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('La roche-posay effaclar h iso-biome creme lavante 390ml','La Roche-Posay','Visage','Achetez en ligne LA ROCHE-POSAY EFFACLAR H ISO-BIOME CREME LAVANTE 390ML sur Angel Care pour Visage',23600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1_fb8621a9-5098-4e72-9b2e-0d505ebf53a4.jpg?v=1714661816',10,1,'7672717672623','42953279635631','https://beautymarket.ma/products/la-roche-posay-effaclar-h-iso-biome-creme-lavante-390ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1_fb8621a9-5098-4e72-9b2e-0d505ebf53a4.jpg?v=1714661816"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIODERMA ATODERM INTENSIVE SOIN YEUX ANTI IRRITATIONS 3 EN1 100 ML','Bioderma','Visage','Le soin anti-irritations 3-en-1 de Bioderma Atoderm Intensive eye a été conçu pour soulager la peau des paupières et du contour des yeux. Elle a également une action réparatrice et elle peut servir de démaquillant. La peau des paupières et du contour des yeux est très sensible. Pour les personnes souffrant de sécheresse de la peau ou d''atopie, elle peut aussi devenir très désagréable et inconfortable. En effet, la peau sèche est mal protégée et elle va réagir trop fortement aux éléments extérieurs. La peau atopique est sensible aux allergènes présents dans l''environnement, même en quantité infime. Les paupières irritées doivent donc bénéficier d''une attention particulière.  C''est ce que propose Bioderma Atoderm Intensive avec son soin anti-irritations 3-en-1. Il va hydrater la peau grâce à sa formule à la glycérine. Celle-ci va également aider à renforcer ses défenses. Il intègre le complexe breveté Skin barrier therapy, qui va réduire l''adhésion de germes nocifs susceptibles d''aggraver la sécheresse de la peau. Il contient la technologie Lipigenium, qui contient des acides gras et des céramides. Elle va permettre la création d''un film de protection à la surface de la peau irritée. Enfin, ce soin apporte de l''enoxolone, un actif anti-inflammatoire qui va réduire les démangeaisons.',19900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Offert_11.png?v=1778501022',10,1,'7672736579759','42953316139183','https://beautymarket.ma/products/bioderma-atoderm-intensive-soin-yeux-anti-irritations-3-en1-100-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Offert_11.png?v=1778501022"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Remescar Sérum à la Vitamine C + Retinol Serum','Remescar','Cheveux','Remescar Sérum réparateur à la Vitamine C & acide hyaluronique a pour but de réduire les taches foncées et l’hyperpigmentation. Il aide à protéger la peau contre les rayons UV et à réparer les dommages causés par le soleil. L’objectif principal est d’obtenir une peau plus saine et plus uniforme en réduisant naturellement les rougeurs et les impuretés.

L’utilisation d’un complexe vitamine C 45 % puissant et stabilisé permet d’obtenir des avantages et des résultats optimaux',55000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/trdyrd.png?v=1704293774',10,1,'7673104695471','42954992156847','https://beautymarket.ma/products/copie-de-remescar-serum-a-la-vitamine-c',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/trdyrd.png?v=1704293774"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NaturEsoin Argile Verte 100 G','NaturEsoin','Visage','NaturEsoin Argile verte 100% naturelle sans conservateurs dotée de pouvoirs ,ultiples:
Antiseptique absorbante, cicatrisante, stimulante et purifiante.
