INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('THE ORDINARY Rétinol 1% dans du Squalane - Sérum Anti-age 30ML','The Ordinary','Visage','Une solution vegan sans eau offrant une concentration de rétinol pur de 1%, permettant de lutter contre les signes de l’âge, notamment les rides et le photo-vieillissement.

Appliquer une petite quantité sur le visage le soir, après les sérums à base d’eau mais avant les crèmes plus épaisses.',19000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/HIUJHIOUIO.png?v=1702988996',10,1,'7689637691567','43028540588207','https://beautymarket.ma/products/the-ordinary-retinol-1-dans-du-squalane-serum-anti-age-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/HIUJHIOUIO.png?v=1702988996"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('THE ORDINARY Solution à la Cafeine 5% + EGCG - Contour des Yeux 30ML','The Ordinary','Visage','Ce sérum vegan léger contient une très forte concentration de 5% de caféine ainsi qu''une forme purifiée de Glucoside de Gallate d''Épigallocatéchine (EGCG) issue des feuilles de thé vert.',17500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BJHUIYHU.png?v=1702989289',10,1,'7689642868911','43028548124847','https://beautymarket.ma/products/the-ordinary-solution-a-la-cafeine-5-egcg-contour-des-yeux',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BJHUIYHU.png?v=1702989289"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Camomilla Blu Active Nettoyant Intime ph 3.5 300ml','Camomilla Blu','Corps','Nettoyant intime délicat à l’extrait de camomille qui favorise la restauration des défenses naturelles et l’équilibre physiologique normal des zones intimes de la femme, notamment en âge de procréer.

Son utilisation est également indiquée dans la période menstruelle et post-partum, en complément d’un traitement antiseptique.',9400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/U8UU8.jpg?v=1760615525',10,1,'7690627678383','43031515791535','https://beautymarket.ma/products/camomilla-blu-active-nettoyant-intime-ph-3-5-300ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/U8UU8.jpg?v=1760615525"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIODERMA SENSIBIO DEFENSIVE SERUM 30 ML','Bioderma','Cheveux','Concentré hydratant apaisant longue durée Réduit les signes du vieillissement prématuré des peaux sensibles et sensibilisées causés par les agressions extérieures',27000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Bioderma-Sensibio-Defensive-Serum-30Ml-3701129804995-639084187795058395-1.jpg?v=1778493307',10,1,'7690627842223','43031517364399','https://beautymarket.ma/products/bioderma-sensibio-defensive-serum-30-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Bioderma-Sensibio-Defensive-Serum-30Ml-3701129804995-639084187795058395-1.jpg?v=1778493307"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DOPPEL HERZ AKTIV SELENIUM 30 COMPRIMES','Doppelherz','Corps','AKTIV SÉLÉNIUM est un Complexe antioxydant à haute puissance et avec la meilleure assimilation.

Doppelherz® aktiv Sélénium contient une combinaison d''antioxydants qui agissent en synergie pour protéger les cellules contre les radicaux libres, soutenir le fonctionnement du système immunitaire et réduire la fatigue.

Le sélénium est un oligo-élément impliqué dans plusieurs processus vitaux: la production d''hormones thyroïdiennes actives, l''inflammation, l''immunité et le fonctionnement du système reproducteur masculin dépendent tous d''un apport adéquat en sélénium.',10700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RTY7T768768.png?v=1703084061',10,1,'7690684367023','43031670489263','https://beautymarket.ma/products/doppelherz-aktiv-selenium-30-comprimes',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RTY7T768768.png?v=1703084061"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DOPPEL HERZ AKTIV SIROP OMEGA-3 MULTI-VITAMINES JUNIOR 150 ML','Doppelherz','Corps','Le sirop riche en oméga-3 de poisson, sans goût de poisson

L’acide gras oméga-3 DHA soutient le développement cérébral et cognitif

Contient en plus du DHA 11 vitamines essentielles au fonctionnement des neurones et du système nerveux',14700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BHJHUIUO.png?v=1703084378',10,1,'7690685644975','43031674192047','https://beautymarket.ma/products/doppelherz-aktiv-sirop-omega-3-multi-vitamines-junior-150ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BHJHUIUO.png?v=1703084378"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DOPPEL HERZ PROSTACALM SANTE DE PROSTATE 30 CAPSULES','Doppelherz','Bien-être','Doppelherz® aktiv Prostacalm est une combinaison d‘extraits naturels de plantes et d‘antioxydants organiques et minéraux qui contribuent au fonctionnement normal de la prostate et renforcent les défenses cellulaires face aux effets néfastes des radicaux libres.

Conseils d''utilisation:

Une fois par jour, après le repas, avaler une gélule avec un grand verre d’eau. Ne pas croquer la gélule.',9900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SERTERYT.png?v=1703084686',10,1,'7690687152303','43031679500463','https://beautymarket.ma/products/doppelherz-prostacalm-sante-de-prostate-30-capsules',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SERTERYT.png?v=1703084686"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ACTI CEUTIC Sérum vitamine c 10','Acti Ceutic','Visage','ACTI CEUTIC Sérum vitamine c 10 acide hyaluronique pour tous types des peaux',23700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/C10.png?v=1703085922',10,1,'7690697375919','43031703912623','https://beautymarket.ma/products/acti-ceutic-serum-vitamine-c-10',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/C10.png?v=1703085922"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SVR [PEPTI] BIOTIC GEL MAT REGENERANT LISSANT PEAUX A IMPERFECTIONS 50ML','SVR','Visage','SVR Biotic Pepti Gel-Mat Régénérant Lissant 50 ml est une crème qui est faite pour régénérer votre peau grâce à une combinaison de 4 actifs essentiels à la fonction de la peau :

les probiotiques pasteurisés : ils protègent et renforcent la barrière cutanée.

l''acide hyaluronique : il lisse les rides, les ridules et hydrate.

la vitamine C stabilisée : elle protège des radicaux libres, raffermie et défatigue la peau.

les peptides : ils lissent les irrégularités, contrôlent la brillance.',34100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/XDRTERS6ER.png?v=1703162695',10,1,'7691550785711','43034864615599','https://beautymarket.ma/products/svr-pepti-biotic-gel-mat-regenerant-lissant-peaux-a-imperfections-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/XDRTERS6ER.png?v=1703162695"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON AZELAIC ACID 10 %','Dalton','Visage','Ce Haut Concentré est tout ce dont vous avez besoin si vous souffrez d''une peau sujette aux imperfections, à l''acné et aux rougeurs. 10 % d’acide azélaïque et d’algues vertes antioxydantes apportent à votre routine beauté une mise à jour qui sauvera littéralement votre peau. Le sérum d''acide azélaïque hautement dosé a un effet antibactérien et apaise les rougeurs déclenchées par l''inflammation, ce qui le rend idéal pour la couperose et les peaux sujettes à la rosacée. Il régule également la production de sébum, possède des propriétés exfoliantes douces et débouche les pores. Cela peut aider à traiter, réduire et prévenir les points noirs et autres imperfections et apporter une amélioration durable à l’apparence de votre peau. En plus de cela, le sérum offre des bienfaits antioxydants : il neutralise les radicaux libres et protège la peau du stress oxydatif et de l’inflammation.',43500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/vghuy.png?v=1703172720',10,1,'7691600330927','43034961838255','https://beautymarket.ma/products/dalton-azelaic-acid-10',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/vghuy.png?v=1703172720"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON BRIGHT PERFECTION PIGMENTATION CONTROL CREME NUIT','Dalton','Visage','Cette crème de nuit anti-âge cible l''hyperpigmentation avec des effets longue durée. Les exopolysaccharides marins, l''acide hyaluronique de faible poids moléculaire avec l''acide alpha-linolénique et la niacinamide sont de puissants ingrédients anti-taches qui aident à éclaircir progressivement les taches pigmentaires foncées et à favoriser un teint équilibré et uniforme. Dans le même temps, notre extrait marin Celumer unique offre de puissants bienfaits anti-âge et aide à diffuser les autres ingrédients actifs dans les couches plus profondes de la peau. La crème éclaircissante repulpe les rides et ridules, tandis que le beurre de karité nourrit la peau et la vitamine E la rend plus résistante. Pour un teint lisse et harmonieux au matin.',64600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dser.png?v=1703172835',10,1,'7691601150127','43034963345583','https://beautymarket.ma/products/dalton-bright-perfection-pigmentation-control-creme-nuit',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dser.png?v=1703172835"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON BRIGHT PERFECTION PIGMENTATION CONTROL SERUM','Dalton','Cheveux','Ce sérum hautement concentré est un outil polyvalent idéal si vous souhaitez obtenir un teint impeccable et unifié. Il contient une combinaison équilibrante et éclaircissante d''ingrédients anti-taches : exopolysaccharides marins, acide hyaluronique de faible poids moléculaire avec acide alpha-linolénique et niacinamide pour cibler la décoloration, le teint irrégulier, les taches de vieillesse, le mélasma et les marques post-acnéiques avec des résultats durables. . L''acide alpha-linolénique aide également à contrôler la production de mélanine et prévient ainsi l''hyperpigmentation. Notre extrait marin unique de Celumer stimule le processus naturel de régénération de la peau et garantit que les autres ingrédients actifs peuvent pénétrer profondément dans la peau. Les algues rouges hydratent et apaisent la peau, tandis que l''urée protège la peau du dessèchement. De plus, le sérum éclaircissant repulpe les rides et ridules. Sa formule légère pénètre rapidement et laisse un teint frais et éclatant.',48500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SER6TE565E.png?v=1703173038',10,1,'7691602493615','43034965901487','https://beautymarket.ma/products/dalton-bright-perfection-pigmentation-control-serum',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SER6TE565E.png?v=1703173038"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON BRIGHT PERFECTION PIGMENTATION CONTROL SPF 50+','Dalton','Solaires','Cette crème pour le visage à absorption rapide avec SPF cible la cause profonde de l''hyperpigmentation : les dommages causés par le soleil. De puissants filtres UV protègent votre peau des rayons UVA et UVB nocifs qui peuvent provoquer une surproduction de mélanine, entraînant des taches brunes et d''autres changements de pigmentation. Des ingrédients actifs éclaircissants pour la peau comme les exopolysaccharides marins, l''acide hyaluronique de faible poids moléculaire avec l''acide alpha-linolénique et la niacinamide aident à atténuer l''hyperpigmentation, les taches de vieillesse et la peau foncée. Le squalane protège la peau de la perte d''hydratation, tandis que l''arginine aide à réparer les dommages cutanés visibles. La vitamine E riche en antioxydants protège la peau des dommages causés par les radicaux libres et du vieillissement cutané prématuré. La crème a une texture non grasse et non collante qui pénètre rapidement sans laisser de trace blanche. Pour un teint impeccable, lumineux et uniforme.',64600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/WXTERT.png?v=1703173252',10,1,'7691604426927','43034968162479','https://beautymarket.ma/products/dalton-bright-perfection-pigmentation-control-spf-50',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/WXTERT.png?v=1703173252"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON COMFORT CLEAN GOMMAGE','Dalton','Visage','Ce gommage exfoliant doux et onctueux contient des granules de silice très fines et arrondies. Les grains éliminent les cellules mortes de la surface de la peau et stimulent la circulation sanguine dans les couches supérieures de la peau. La peau est revitalisée, lissée et plus réceptive aux actifs des produits appliqués ensuite. Le Gommage Exfoliant est riche en lipides et sa texture onctueuse laisse la peau agréablement douce.GOMMAGE',29500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ER56R567.png?v=1703173473',10,1,'7691606524079','43034971504815','https://beautymarket.ma/products/dalton-comfort-clean-gommage',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ER56R567.png?v=1703173473"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON EXFOLIANT CARE 12% PHA','Dalton','Visage','Bien que ce produit PHA soit un exfoliant plus doux, il n’est pas moins efficace que les produits contenant des acides alpha-hydroxy ou des acides bêta-hydroxy. Il contient deux acides puissants pour favoriser une peau saine : 4 % d''acide lactobionique sert d''humectant et aide la peau à retenir l''humidité, la protège des radicaux libres et stimule la production de collagène et d''élastine, 8 % de gluconolactone renforce la barrière cutanée et hydrate la peau. Le gel PHA exfolie également les cellules mortes de la peau et laisse un grain de peau lisse et uniforme. La combinaison d''ingrédients marins et d''acides polyhydroxylés (PHA) hautement dosés en font un choix parfait pour les peaux sensibles et sujettes aux rougeurs, à la couperose et aux capillaires dilatés. Les minéraux marins améliorent l''absorption des principes actifs, les algues brunes aident à fournir de l''oxygène à la peau et lui donnent un bel éclat, et l''algue marine apaise la peau. L''acide linoléique et l''acide linolénique renforcent la barrière cutanée, favorisent la régénération cellulaire, offrent des propriétés anti-inflammatoires et stimulent la production de céramides dans la peau.
?',43700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/XRT5E65E6.png?v=1703173601',10,1,'7691607900335','43034973601967','https://beautymarket.ma/products/dalton-exfoliant-care-12-pha',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/XRT5E65E6.png?v=1703173601"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON EXFOLIANT CARE 2 % PHA','Dalton','Visage','This BHA exfoliant contains the highest concentration of beta-hydroxy acid aka salicylic acid allowed in cosmetics. It penetrates deep into the pores, clears pores clogged with sebum and reduces blemishes such as pimples and blackheads',38000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DRT6R6R.png?v=1703173806',10,1,'7691610095791','43034976649391','https://beautymarket.ma/products/dalton-exfoliant-care-2-pha',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DRT6R6R.png?v=1703173806"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON EXFOLIANT CARE 20% PHA','Dalton','Visage','Notre puissant peeling visage aux AHA exfolie les cellules mortes de la peau et laisse un teint lisse et doux. Le mélange hautement concentré de 10 % d’acide glycolique et de 10 % d’acide lactique opère sa magie pour vous rapprocher toujours plus d’une peau parfaite. L''exfoliant AHA aide à réparer les cellules fatiguées et booste la régénération cellulaire. Mais ce n’est pas tout : cet exfoliant chimique améliore également l’absorption des principes actifs. Pour maximiser le pouvoir des acides, nous avons ajouté des algues vertes antioxydantes, des minéraux marins à action profonde et de l''acide hyaluronique pour hydrater également la peau. S''il est utilisé régulièrement, l''exfoliant possède des propriétés anti-âge impressionnantes : il stimule la production de collagène et d''acide hyaluronique, ce qui réduit les rides et ridules. L’exfoliant à domicile peut également aider à réduire l’hyperpigmentation, les taches brunes et les marques de boutons – pour un teint lisse et beau.',43700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/HBHGGHH.png?v=1703173909',10,1,'7691610882223','43034977960111','https://beautymarket.ma/products/dalton-exfoliant-care-20-pha',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/HBHGGHH.png?v=1703173909"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON FACE CARE GEL YEUX LISSANT','Dalton','Visage','Le gel rafraîchissant pour les yeux réduit les poches et lisse visiblement les rides et ridules. Il atténue l’apparence des pattes d’oie et réduit la profondeur des rides de 16 %* en seulement 15 minutes. La combinaison de notre extrait marin Celumer unique et d''un extrait de plancton raffermissant est responsable de minimiser les rides des yeux et de stimuler la production de collagène, laissant la peau jeune et fraîche. L''acide hyaluronique hydratant infuse la peau d''une hydratation intense et procure un effet repulpant cutané. Le gel anti-âge pour les yeux est doté d''un applicateur facile à utiliser qui améliore l''effet rafraîchissant et aide à éliminer les poches sous les yeux. Notre arme secrète pour une peau plus lisse et plus lumineuse au niveau de la zone délicate des yeux.',43700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SET6E56.png?v=1703174621',10,1,'7691665473711','43034993393839','https://beautymarket.ma/products/dalton-face-care-gel-yeux-lissant',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SET6E56.png?v=1703174621"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON FACE CARE MASQUE CLARIFIANT','Dalton','Visage','Rafraîchissant, revitalisant et agréable sensation de picotement : ce masque de beauté détox apporte un regain de fraîcheur instantané et laisse un teint magnifique et lisse. Formulé à base d''hamamélis et d''argile blanche de kaolin, ce masque facial sans parfum stimule le métabolisme de la peau, améliore son élasticité et aide à détoxifier et purifier la peau. Il affine le grain de peau et laisse un teint lisse, frais et hydraté. Le camphre offre des propriétés anti-inflammatoires, tandis que l''allantoïne laisse la peau douce et souple. Ce n’est pas pour rien que ce masque facial extrêmement populaire pour affiner les pores est l’un de nos produits les plus vendus pour tous les types de peau.',31300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DR6R565.png?v=1703174810',10,1,'7691668127919','43034997850287','https://beautymarket.ma/products/dalton-face-care-masque-clarifiant',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DR6R565.png?v=1703174810"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON HYALURONIC UREA','Dalton','Visage','Notre crème hydratante anti-âge douce et soyeuse à l''urée et à l''acide hyaluronique est le désaltérant parfait pour les peaux sèches et déshydratées. La combinaison d’acides hyaluroniques à chaîne courte et longue garantit que non seulement la surface de la peau, mais également les couches plus profondes de la peau, sont entièrement hydratées, tandis que l’urée lie et retient l’humidité de la peau. En outre enrichi de notre extrait marin rajeunissant de Celumer, cet hydratant lisse les rides et ridules et laisse votre peau visiblement plus rebondie et rafraîchie. Mais ce n''est pas tout : il booste également votre production naturelle d''acide hyaluronique et l''augmente jusqu''à 48 %*.',76000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/FTCYRTRT.png?v=1703175009',10,1,'7691670323375','43035002699951','https://beautymarket.ma/products/dalton-hyaluronic-urea',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/FTCYRTRT.png?v=1703175009"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON HYALURONIC UREA LIGHT','Dalton','Visage','Cet hydratant anti-âge léger reconstitue les niveaux d’hydratation de la peau et lisse les rides et ridules causées par la sécheresse. Les acides hyaluroniques de faible et de haut poids moléculaire hydratent la peau de la surface jusqu''aux couches les plus profondes de la peau. L''urée retient l''hydratation et protège la peau de la perte d''humidité. Notre extrait marin Celumer unique offre des bienfaits anti-âge supplémentaires, aide à diffuser les actifs en profondeur dans la peau et augmente la production naturelle d''acide hyaluronique jusqu''à 48 %*. Sa formule légère et non grasse fait de cette crème hydratante pour le visage un booster d''hydratation idéal pour les mois d''été et une alternative plus légère à la crème hydratante anti-âge HYALURONIC UREA.',76000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hbkjhiui.png?v=1703175666',10,1,'7691678515375','43035017511087','https://beautymarket.ma/products/dalton-hyaluronic-urea-light',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hbkjhiui.png?v=1703175666"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON HYDRO LIFT EXPRESS MASK','Dalton','Visage','Notre masque en tissu repulpant et raffermissant associe un regain d''hydratation à un effet anti-âge instantané : il contient notre extrait marin unique de Celumer et un extrait de plancton qui réduit la profondeur des rides jusqu''à 16 % après seulement 15 minutes, tout en étant à chaîne courte. et les acides hyaluroniques à longue chaîne infusent à la peau sèche une hydratation longue durée. Ce masque facial hydratant imbibé de sérum est fabriqué à partir d''un matériau en feuille durable obtenu à partir du lait et des fibres de noix de coco. Il enveloppe le visage comme une seconde peau, afin que les ingrédients bénéfiques soient plus facilement absorbés. Le masque facial rend la peau plus ferme, minimise l''apparence des ridules et des rides du visage et laisse la peau lisse et rebondie.',17100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/37358e874bf9fb57599c6aba3b6c7375.png?v=1703175908',10,1,'7691680874671','43035021050031','https://beautymarket.ma/products/dalton-hydro-lift-express-mask',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/37358e874bf9fb57599c6aba3b6c7375.png?v=1703175908"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON NIACINAMIDE 10% SERUM','Dalton','Cheveux','Êtes-vous prêt pour des soins de la peau de niveau supérieur ? Le Sérum Niacinamide 10% est un professionnel chevronné lorsqu''il s''agit d''améliorer votre teint. Ce sérum sans parfum réduit l’apparence des pores dilatés, lisse la surface de la peau et aide à remédier aux changements cutanés induits par la lumière tels que l’hyperpigmentation et les rougeurs. Mais cela ne s’arrête pas là. L’ingrédient clé, la niacinamide, également connue sous le nom de vitamine B3, peut faire encore plus. Il soutient la production de céramides dans la peau, ce qui renforce la barrière cutanée et protège la peau de la perte d''humidité. De plus, le Sérum Niacinamide aide à réguler la production de sébum et prévient l''apparition d''imperfections, ce qui profite particulièrement aux peaux grasses. Un autre ingrédient de soin puissant présent dans ce sérum est l''algue verte, qui crée un effet flou en améliorant visiblement le teint et la texture de la peau et favorise un microbiome cutané équilibré, qui est le système immunitaire de la peau. Si vous recherchez un fini naturel et magnifique , ce booster redonnera à la peau terne et fatiguée son éclat radieux.',40000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/z_e_e.png?v=1703176071',10,1,'7691697062063','43035024064687','https://beautymarket.ma/products/alton-niacinamide-10-serum',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/z_e_e.png?v=1703176071"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON OYSTER SKIN BALANCE','Dalton','Visage','The mattifying moisturizer is formulated with oyster extract and pistacia lentiscus gum to control excess sebum production in the T-zone and reduce oily skin, while still managing to moisturize, hydrate and nourish dry skin areas. The anti-aging cream is great for both combination skin and blemish-prone skin, as it helps to clear clogged pores and blackheads and keeps the skin shine-free and matte. On top of that, our unique Celumer Marine Extract targets the first signs of wrinkles for smoother and younger-looking skin. If used regularly, the pore-minimizing moisturizer can restore balance to the different zones of combination skin – for a balanced and matte complexion.',51000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dr.png?v=1703176172',10,1,'7691718492335','43035025866927','https://beautymarket.ma/products/dalton-oyster-skin-balance',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dr.png?v=1703176172"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON Q 10 ENERGY BOOST EYE CREAM','Dalton','Visage','Une goutte de cette délicate crème pour les yeux au Q10 suffit à apporter à la peau sèche du contour des yeux de précieux nutriments, lipides et hydratation tout au long de la journée. Il ne contient pas d’huiles qui « s’infiltrent » dans les yeux et nourrit la peau sans provoquer d’irritation. La Crème Contour des Yeux Q10 augmente le niveau d''énergie cellulaire de 90%* après seulement deux heures ! Il ravive les yeux fatigués, réduit les rides et ridules causées par la sécheresse, favorise le renouvellement et la régénération cellulaires et laisse la peau visiblement plus lisse et plus ferme. La vitamine E riche en antioxydants protège les cellules des radicaux libres, tandis que la glycérine hydrate et l''huile de ricin nourrit la peau sèche. Notre extrait marin Celumer unique aide à diffuser les ingrédients dans les couches profondes de la peau et offre des bienfaits anti-âge durables. Le résultat : un contour des yeux magnifique et une apparence radieuse.',40000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/serezrer.png?v=1703176304',10,1,'7691744280751','43035027833007','https://beautymarket.ma/products/dalton-q-10-energy-boost-eye-cream',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/serezrer.png?v=1703176304"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON Q 10 ENERGY BOOST LIGHT CREME','Dalton','Visage','La crème hydratante légère Q10 pour peaux sèches pénètre rapidement et donne à la peau terne, stressée et fatiguée un nouveau regain d''énergie. Il contient de minuscules perles rouges de Q10 vitalisantes qui éclatent lorsqu''elles sont appliquées sur la peau et libèrent les principes actifs pour être facilement absorbés. Après seulement 2 heures, les niveaux d’énergie de la peau sont jusqu’à 90 % supérieurs à la normale, ce qui stimule les cellules cutanées et améliore la régénération cutanée. L''allantoïne apaise la peau et la vitamine E offre des propriétés antioxydantes pour prévenir les dommages causés par les radicaux libres et les signes prématurés du vieillissement. Dans le même temps, l''huile d''amande et l''acide hyaluronique hydratent et nourrissent la peau sèche avec de précieux lipides, tout en aidant à réduire les rides et ridules. Notre extrait marin Celumer unique garantit que les ingrédients actifs peuvent pénétrer profondément dans la peau et offre de puissants bienfaits anti-âge. Idéal pour les peaux sèches - pour un teint frais, lisse et éclatant',63100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/wserezrtez.png?v=1703176481',10,1,'7691745886383','43035030192303','https://beautymarket.ma/products/dalton-q-10-energy-boost-light-creme',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/wserezrtez.png?v=1703176481"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON Q10 ENERGY BOOST','Dalton','Visage','100 % de puissance Q10 ! Cette crème visage antirides donne à la peau fatiguée et stressée un regain d''énergie dont elle a tant besoin. Il contient de petites perles rouges de coenzyme Q10 hautement dosées qui éclatent lorsqu''elles sont massées sur la peau et produisent un effet immédiat. Après seulement 2 heures, les niveaux d''énergie sont jusqu''à 90 % supérieurs à la normale, ce qui stimule les cellules de la peau et améliore sa régénération. La vitamine E riche en antioxydants protège les cellules des dommages causés par les radicaux libres. L''huile de jojoba nourrit la peau sèche avec des lipides précieux, tandis que le panthénol apaise la peau et que l''acide hyaluronique procure une hydratation longue durée. Notre extrait marin Celumer unique aide à diffuser ces ingrédients bénéfiques en profondeur dans la peau et offre lui-même de puissants bienfaits anti-âge. C''est ainsi que cette crème nourrissante pour peaux matures hydrate, réduit les rides et ridules, améliore l''élasticité de la peau et revitalise les peaux ternes et fatiguées.',63100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/xdrytyty.png?v=1703234466',10,1,'7692326437039','43037435265199','https://beautymarket.ma/products/dalton-q10-energy-boost',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/xdrytyty.png?v=1703234466"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON REDNESS CONTROL CONCENTRE','Dalton','Visage','Le Concentré Anti-Rougeurs offre une aide efficace contre la couperose et les rougeurs du visage. Sa formule sans huile et sans parfum le rend également adapté aux peaux sujettes à la rosacée. Il a été prouvé qu''il réduit les rougeurs de près de 35 % et les télangiectasies visibles de plus de 20 %*. Notre formule apaisante aux 5 herbes à base de marron d''Inde, de petit houx, de racine de réglisse, de calendula et d''hydrocotyle asiatique renforce les capillaires et raffermit la structure de la peau, ce qui prévient l''apparition de vaisseaux sanguins dilatés. Le produit aide également à calmer les irritations et minimise l’apparence de la peau rouge et tachée du visage. L’acide hyaluronique rétablit les niveaux d’hydratation de la peau et hydrate la peau. Pour un teint équilibré et unifié.',25200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bjhjiji.png?v=1703237009',10,1,'7692339609775','43037454401711','https://beautymarket.ma/products/dalton-redness-control-concentre',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bjhjiji.png?v=1703237009"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON REDNESS CONTROL CREME LIGHT','Dalton','Visage','La crème hydratante anti-rougeurs a une formule très légère à absorption rapide qui convient particulièrement aux peaux grasses et aux peaux mixtes sujettes aux rougeurs et aux veines filantes du visage. Il hydrate la peau tout en minimisant l’apparence des vaisseaux sanguins dilatés et des varicosités. Grâce à l''effet astringent de notre formule aux 5 herbes (marron d''Inde, petit houx, racine de réglisse, calendula, ombelle asiatique), la crème sans parfum agit en renforçant les parois capillaires et le tissu conjonctif, ce qui conduit à un effet astringent de 21% réduction des capillaires brisés sur le visage et réduction de 35 % des rougeurs du visage* – pour un teint calme et équilibré. L''allantoïne apaise la peau et l''urée aide la peau à retenir l''humidité.',38000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7351450_redness-control_cream-light_650x650_1.jpg?v=1703237223',10,1,'7692340494511','43037455679663','https://beautymarket.ma/products/dalton-redness-control-creme-light',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7351450_redness-control_cream-light_650x650_1.jpg?v=1703237223"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON REDNESS CONTROL CREME RICHE','Dalton','Visage','Cette crème pour le visage riche et nourrissante a été spécialement conçue pour cibler les peaux très sèches sujettes à la couperose, un stade précoce de la rosacée. Les ingrédients naturels comme l''extrait de levure, l''huile de ricin, la cire d''abeille et notre formule aux 5 herbes ont un effet apaisant et aident à renforcer la barrière naturelle de la peau. La crème améliore l''apparence des taches rouges de près de 35 % et réduit les varicosités visibles (télangiectasie) sur le visage. La peau est protégée, régénérée et hydratée.',38000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7351250_redness-control_cream_rich_650x650_d0e2b271-9995-4890-9275-6cb65f92f7e3.jpg?v=1703237450',10,1,'7692341477551','43037456761007','https://beautymarket.ma/products/dalton-redness-control-creme-riche',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7351250_redness-control_cream_rich_650x650_d0e2b271-9995-4890-9275-6cb65f92f7e3.jpg?v=1703237450"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON REDNESS CONTROL MASQUE','Dalton','Visage','Ce produit est une excellente option si vous cherchez des moyens de réduire les rougeurs du visage ! Le masque anti-rougeurs calme les peaux à tendance couperose et rosacée, apaise les irritations et renforce les capillaires et le tissu conjonctif. Sa texture douce et crémeuse est absorbée presque complètement en 15 à 20 minutes et aide à rééquilibrer la peau irritée. La combinaison de notre formule aux 5 herbes (marron d''Inde, petit houx, racine de réglisse, calendula et ombelle asiatique), du panthénol apaisant et de la craie cicatrisante de l''île de Rügen renforce les capillaires et favorise la capacité naturelle d''auto-guérison de la peau - pour un teint apaisé et réduction de 21% des capillaires brisés sur le visage.',25200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7351850_redness-control_maske_650x650_2_1.jpg?v=1703237688',10,1,'7692342689967','43037458038959','https://beautymarket.ma/products/dalton-redness-control-masque',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7351850_redness-control_maske_650x650_2_1.jpg?v=1703237688"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON REDNESS CONTROL SERUM','Dalton','Cheveux','Le sérum léger à effet antirides aide à réduire les symptômes de la couperose (capillaires cassés et peau rouge et tachée) ainsi que les signes visibles du vieillissement. La combinaison de notre formule aux 5 herbes, composée de marron d''Inde, de petit houx, de racine de réglisse, de calendula et d''hydrocotyle asiatique, de notre extrait marin unique Celumer et de notre extrait de levure, est particulièrement adaptée aux peaux sujettes aux vaisseaux sanguins dilatés visibles. Le sérum réduit les rougeurs cutanées jusqu''à 35 %* et les vaisseaux sanguins brisés jusqu''à 21 %*. L''acide hyaluronique hydrate la peau, tout en lissant les rides et ridules. De plus, le sérum anti-âge contient de minuscules pigments verts chatoyants qui agissent comme un filtre flou en dissimulant les taches rouges disgracieuses sur le visage, révélant un teint équilibré et unifié et une peau visiblement plus jeune.',48500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fgfgf.png?v=1703237801',10,1,'7692343312559','43037458759855','https://beautymarket.ma/products/dalton-redness-control-serum',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fgfgf.png?v=1703237801"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON RETINOL SERUM','Dalton','Cheveux','L''association du rétinol, du rétinal et d''un équivalent maritime en vitamine A issue du criste marin procure un effet synergique efficace pour la peau. En effet, nous accordons autant d’importance à la douceur qu’à l’efficacité maximale. Ce sérum anti-âge est la meilleure preuve que ce n''est pas seulement la concentration élevée en rétinol d''un seul principe actif qui compte. La combinaison innovante de 3 ingrédients actifs différents est ce qui différencie notre produit des autres sérums au rétinol. Ces ingrédients anti-âge favorisent le renouvellement cellulaire et la régénération de la peau, tout en réduisant l''hyperpigmentation, les rides et ridules. Ils stimulent la production d’acide hyaluronique, ce qui entraîne une meilleure élasticité de la peau. En même temps, le sérum au rétinol améliore votre teint en minimisant l''apparence des taches brunes, des boutons et autres petites imperfections. Essayez-le vous-même : ce sérum anti-âge aux multiples talents au rétinol a tout pour plaire ! Particulièrement adapté aux peaux normales à grasses.',43700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dtdrtr.png?v=1703238381',10,1,'7692346818735','43037475504303','https://beautymarket.ma/products/dalton-retinol-serum',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dtdrtr.png?v=1703238381"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON SUN CARE SPF 50+','Dalton','Visage','Notre crème solaire SUN CARE avec SPF 50+ offre une excellente protection UVA et UVB. La formule légère et non grasse est idéale pour une utilisation sur le visage et ne laisse pas de trace blanche. Au contraire : il pénètre rapidement tout en imprégnant la peau d''humidité et de précieux nutriments naturels. Les algues spiruline et la vitamine E jouent un rôle essentiel en tant qu''éliminateurs de radicaux libres et protègent la peau du vieillissement cutané prématuré induit par les UV.',25200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/xdytyt.png?v=1703238677',10,1,'7692348293295','43037478387887','https://beautymarket.ma/products/dalton-sun-care-spf-50',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/xdytyt.png?v=1703238677"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON TRIPLE CERAMIDE SERUM','Dalton','Cheveux','Notre sérum contenant trois céramides différents - le qualifier de mise à niveau en matière de soins de la peau serait honnêtement un euphémisme. Il constitue la condition préalable à une peau belle et surtout saine. Ce n''est que lorsque la barrière cutanée est intacte que les principes actifs puissants peuvent être absorbés et traités à 100 %. Il n’y a pas que les peaux sensibles et les peaux sèches qui souffrent souvent d’une barrière cutanée compromise. Des facteurs externes tels que les rayons UV et des facteurs internes tels que les changements hormonaux peuvent également affaiblir la barrière protectrice de la peau. La combinaison de céramides NP, NG et AP est particulièrement importante pour aider notre peau à se protéger et à prévenir la perte d''hydratation. Le panthénol retient l''hydratation, améliore l''élasticité de la peau, favorise la cicatrisation et aide à réparer la peau endommagée.',43700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/tryertyr.png?v=1703238840',10,1,'7692349178031','43037479633071','https://beautymarket.ma/products/dalton-triple-ceramide-serum',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/tryertyr.png?v=1703238840"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON TRIPLE HYALURONIC BOOSTER','Dalton','Visage','Ce sérum à l''acide hyaluronique élève les soins de la peau à un tout autre niveau ! Il est facile à intégrer à votre routine existante – adaptée aux besoins de votre peau à ce moment-là. Une hydratation puissante sur pas moins de quatre niveaux différents : trois types différents d''acide hyaluronique sont associés à un « acide hyaluronique marin » issu d''algues brunes pour hydrater la peau jusqu''à la couche la plus profonde et repulper les rides et ridules de l''intérieur. Les acides hyaluroniques à chaîne moyenne, courte et extrêmement courte offrent une hydratation intense en trois étapes. 1. Le sérum hydratant hydrate la peau de votre visage directement en surface. 2. Il reconstitue les réserves d''hydratation en profondeur et lisse les rides et ridules, pour que la peau paraisse visiblement plus rebondie. 3. Les algues brunes aident la peau à retenir l’humidité et à prévenir la peau sèche. Grâce à sa formule sans parfum, ce concentré hyaluronique peut également être utilisé pour les peaux sensibles.',52300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/srdtr_e.png?v=1703239039',10,1,'7692349997231','43037480583343','https://beautymarket.ma/products/dalton-triple-hyaluronic-booster',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/srdtr_e.png?v=1703239039"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON VITAMINE C 15% SERUM','Dalton','Cheveux','Grâce à 15% de vitamine C, de plancton et d''acide férulique, ce Sérum Vitamine C est votre meilleur allié dans la lutte contre le vieillissement cutané et procure également un bel éclat naturel. Le sérum végétalien hautement dosé stimule la production de collagène tout en inhibant la dégradation de cette importante protéine structurelle, ce qui entraîne une amélioration de l''élasticité de la peau. Ses fortes propriétés antioxydantes peuvent neutraliser les radicaux libres et protéger la peau du stress environnemental et des dommages causés par les UV. Il éclaircit également les taches pigmentaires, les décolorations et les taches brunes – pour un teint unifié et une peau éclatante. Le Sérum Vitamine C convient à tous les types de peau.',54400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/nkjliouo.png?v=1703239297',10,1,'7692351635631','43037482614959','https://beautymarket.ma/products/dalton-vitamine-c-15-serum',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/nkjliouo.png?v=1703239297"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BJORN AXEN REPAIR PACK SHAMPOOING + CONDITIONER 250ML','Björn Axén','Cheveux','Le pack contient :

BJORN AXEN CONDITIONER REPARATEUR POUR CHEVEUX SECS 250ml

Un après-shampooing nourrissant qui répare les cheveux secs et abîmés. Enrichi d''une forte concentration de minéraux et de protéines réparatrices, en plus de l''huile d''argan biologique, pour hydrater les cheveux et le cuir chevelu. Laisse les cheveux forts, brillants et renouvelés. Le produit est végétalien et testé dermatologiquement.

BJORN AXEN SHAMPOING REPARATEUR CHEVEUX SECS 250ml

Un shampooing nourrissant qui répare les cheveux secs et abîmés. Enrichi en huile d''argan biologique, protéines et minéraux de la mer qui renforcent, hydratent et reconstruisent. Laisse les cheveux forts, brillants et renouvelés. Le produit est végétalien et testé dermatologiquement.',32900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/R5YRT65R.png?v=1762592063',10,1,'7692380045487','43037529243823','https://beautymarket.ma/products/bjorn-axen-repair-pack',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/R5YRT65R.png?v=1762592063"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
