INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DALTON SEA CELLULES SOUCHES MARINES Crème','Dalton','Visage','The Marine Stem Cell Cream combines a sense of pure luxury with highly effective skincare benefits. It is formulated with an exclusive composition of our unique Celumer Marine Extract, millions of maritime stem cells and Crambe maritima to boost the cells’ natural defense mechanisms, promote cell renewal, enhance epidermal regeneration, hydrate the skin and increase collagen production by up to 43%*. Almond oil and shea butter smooth and nourish the skin. The result: Youthful, plump and firm skin and defined facial contours. The moisturizer’s exquisite scent and silky-soft texture melt right into the skin and leave it feeling as smooth as velvet.',112000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/sea.png?v=1703667103',10,1,'7695037530287','43048824897711','https://beautymarket.ma/products/dalton-sea-cellules-souches-marines-creme',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/sea.png?v=1703667103"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
