INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DODIE TASSE D''APPRENTISSAGE +6 MOIS  200ML 1635','Dodie','Bébé & Maman','Une tasse d’apprentissage conçue pour faciliter la transition du biberon de bébé à la tasse.

Cette tasse possède une valve anti-fuite qui évite les petits accidents, et les taches dû aux fuites. Son bec souple est agréable pour les gencives délicates des bébés de plus de 6 mois. Le capuchon protecteur ferme efficacement la tasse pour éviter que tout liquide ne fuît lors de son transport.',11800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1635.psd.png?v=1703849072',10,1,'7695815245999','43053054394543','https://beautymarket.ma/products/dodie-tasse-dapprentissage-6-mois-200ml-1635',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1635.psd.png?v=1703849072"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
