INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Dodie – Sucette Physiologique p33 soleil 0102','Dodie','Bébé & Maman','Cette sucette physiologique appelée aussi asymétrique, dispose d’un bouclier en forme de papillon et légèrement incurvée afin de se placer le mieux possible sur la bouche',6200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/p33_f1f27e18-16f4-4f39-bc58-1fe5981c16c9.png?v=1703858814',10,1,'7695837462703','43053170000047','https://beautymarket.ma/products/dodie-sucette-physiologique-p33-soleil-0102',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/p33_f1f27e18-16f4-4f39-bc58-1fe5981c16c9.png?v=1703858814","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/p33.png?v=1703858814"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
