INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BEBE CONFORT BAVOIR TEXTILE AVEC RAMASSE MIETTES JUNGLE VIBES +4Mois','Bebe Confort','Bébé & Maman','Bavoir textile avec ramasse miettes plastiques Jungle Vibes Bébé Confort pour permettre à bébé de rester propre durant tout le repas. Notre équipe d''experts est là pour vous aider à choisir le bavoir adapté à votre enfant.',17400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8242.png?v=1703859949',10,1,'7695841591471','43053177634991','https://beautymarket.ma/products/bebe-confort-bavoir-textile-avec-ramasse-miettes-jungle-vibes',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8242.png?v=1703859949"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DODIE initiation Tétine  Ronde 3 Vitesses  + ANTI-Colique 4 liquide épais','Dodie','Bébé & Maman','Les tétines anti-colique ont une forme large et ronde proche de la forme du sein et adaptée à la bouche de bébé. Dotée d’une valve brevetée assurant une circulation de l’air régulière, les tétines EASY AIR aident à réduire les risques de coliques, de régurgitations et d’aérophagie

Les tétines EASY AIR s’adaptent à tous les biberons Dodie Initiation+ et Évolution+3 vitesses',9400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dodie-tetine-ronde-anti-colique-6-mois-3-vitesses-debit-rapide.jpg?v=1771594094',10,1,'7695842148527','43053183205551','https://beautymarket.ma/products/dodie-tetine-ini-anti-colique-d4-6m-liquide-epais-x2',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dodie-tetine-ronde-anti-colique-6-mois-3-vitesses-debit-rapide.jpg?v=1771594094"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Dodie Tétine SENSATION+ Plate Anti-Colique 4 liquide épais','Dodie','Bébé & Maman','Le système anti-colique est intégré à la tétine grâce à une valve brevetée, qui favorise la circulation de l''air et réduit les risques de coliques, d''aérophagie et de régurgitations. Les tétines Sensation+ s''adaptent sur tous les biberons Dodie col large (gammes Sensation+ et Initiation+)',9400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3700763501567.webp?v=1771594639',10,1,'7695851389103','43053227311279','https://beautymarket.ma/products/dodie-tetine-sensation-plate-anti-colique-4-liquide-epais',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3700763501567.webp?v=1771594639"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Dodie Tétine Plate Sens + Anti Colique D5 + 18M X2','Dodie','Bébé & Maman','La Tétine Plate Col Large Sensation+ +18 Mois de Dodie s''adapte à tous les biberons à col large des gammes Sensation+ et Initiation+. Proposées en lot de 2, ces tétines anti-coliques de débit 5 ou rapide sont spécialement conçues pour les bébés de 18 mois et plus. Leur embout large et plat imite la forme aplatie du sein lors de la tétée. Grâce à son système de valve exclusif intégré, ces tétines aident à combattre les troubles digestifs. En limitant l''entrée d''air dans le biberon et en favorisant le passage du lait, elles minimisent le risque de coliques, de régurgitations et d''aérophagie. Fabriquées en silicone souple, ces tétines plates disposent de stries pour éviter le collage des parois lors de la tétée. Reconnues pour être facilement acceptées par la grande majorité des bébés, quel que soit leur âge, elles offrent un maximum de confort de succion. Les trous sont suffisamment larges pour laisser passer des préparations épaisses. Garanties sans BPA ni BPS, les Tétines Sensation+ sont fabriquées en France.',9400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/18888.png?v=1703865219',10,1,'7695856009391','43053252313263','https://beautymarket.ma/products/dodie-tetine-plate-sens-anti-colique-d5-18m-x2',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/18888.png?v=1703865219"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Dodie tetine plate anti colique D3 +6 Mois','Dodie','Bébé & Maman','La Tétine Plate Col Large Sensation+ +6 Mois Débit 3 de Dodie dispose de la double valve anti-colique exclusive. Breveté par la marque, ce système a été spécialement conçu pour réduire le risque de régurgitations, de coliques et d''aérophagie, tout en permettant au bébé de boire à son rythme. Il favorise le passage du lait tout en limitant l''entrée de l''air dans le biberon pour s''adapter à l''appétit de l''enfant. Grâce à l''embout large, la succion se déroule de façon naturelle, sans fatigue. Vendues par lot de 2, ces tétines anti-coliques ont une tête plate afin de copier la forme que prend le sein lors de la tétée. Fabriquées en France et garanties sans BPA ni BPS, elles sont en silicone extra souple pour offrir un maximum de confort et de douceur durant l''allaitement. Les stries sur la surface interne de la tétine empêchent que les parois ne se collent et bloquent le passage du lait. Prévues pour des bébés de plus de 6 mois, elles assurent un débit rapide. Comme toutes les tétines plates de Dodie, elles sont compatibles avec les biberons Sensation+ et Initiation+ à col large. Grâce aux innovations technologiques et à l''expertise de Dodie, elles sont facilement acceptées par plus de 95 % des bébés.',9400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/03700763501550_A1N1_s02.jpg?v=1771594509',10,1,'7695856304303','43053254213807','https://beautymarket.ma/products/dodie-tetine-plate-anti-colique-d3-6-mois',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/03700763501550_A1N1_s02.jpg?v=1771594509"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Dodie Tétine Plate Sens + Anti Colique D1 + 18M X2','Dodie','Bébé & Maman','La Tétine Plate Col Large Sensation+ 0 À 6 Mois - Débit 1 de Dodie se distingue par la forme plate de son embout, spécialement étudiée pour reproduire la forme aplatie du sein lors de la tétée. Vendues par lot de 2, les tétines Sensation+ de Dodie disposent du système de double valve anti-colique exclusif breveté. Ce dernier facilite la succion et réduit le risque de coliques, de régurgitations et d''aérophagie. En limitant l''entrée de l''air dans le biberon, il aide à combattre les coliques et respecte le rythme de tétée de l''enfant. Acceptée par plus de 95 % des bébés, la Tétine Plate Col Large Sensation+ 0 À 6 Mois possède un embout large adapté à la bouche des nourrissons. Les stries permettent d''éviter que les parois se collent durant la succion. Compatibles avec les biberons Sensation +, Initiation+ et Évolution de Dodie, les tétines plates anti-coliques sont fabriquées en France et garanties sans BPA ni BPS. Grâce à leur design exclusif et au système de valve anti-colique intégré, elles sont conçues pour offrir des sensations naturelles et un confort optimal aux bébés, qui peuvent téter, comme au sein, sans se fatiguer.',9400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dodie-tetine-plate-debit1.jpg?v=1771594380',10,1,'7695857090735','43053258866863','https://beautymarket.ma/products/dodie-tetine-plate-sens-anti-colique-d1-18m-x2',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dodie-tetine-plate-debit1.jpg?v=1771594380"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
