INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('La roche posay hydraphase ha uv riche spf 25 -40 ml','La Roche-Posay','Visage','HYDRAPHASE HA UV SPF 25 Riche est notre première crème hydratante pour les peaux sensibles et déshydratées, à combiner une hydratation intense de 72H à une haute protection SPF 25 contre les UVA et les UVB. Elle contient de l''Acide Hyaluronique d''origine naturelle issu de la technologie verte, actif reconnu pour hydrater la peau et la repulper, ainsi que de l''Eau Thermale de La Roche-Posay à haute concentration apaisante et hautement hydratante. Instantanément, la peau est confortable, hydratée et protégée. Le teint est frais et éclatant. Sa texture est riche, confortable, et non collante.',22200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1_7a2874df-c044-421a-8b78-f69031586d45.jpg?v=1714655404',10,1,'7696138666159','43055123824815','https://beautymarket.ma/products/la-roche-posay-hydraphase-ha-uv-riche-spf-25-40-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1_7a2874df-c044-421a-8b78-f69031586d45.jpg?v=1714655404"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('VICHY NORMADERM FLUIDE DOUBLE CORRECTION HYDRATANT 50 ML','Vichy','Solaires','Normaderm Phytosolution des laboratoires Vichy est un soin quotidien double correction qui est destiné à purifier et corriger les imperfections, les boutons, les pores dilatés, les points noirs des peaux grasses à tendance acnéique.',22100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DTRETR.png?v=1703929959',10,1,'7696159998127','43055201321135','https://beautymarket.ma/products/vichy-normaderm-fluide-double-correction-hydratant-50-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DTRETR.png?v=1703929959"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Vichy normaderm fluide double correction hydratant 30 ml','Vichy','Solaires','Vichy Normaderm Double Correction Daily Care er en ansiktskrem for kombinert, fet og uren hud som bidrar til å styrke hudbarrieren samtidig som huden vil kunne føles mindre fet.

Vichy Normaderm Double Correction Daily Care bidrar til en synlig effekt på kviser, hudormer og aknearr. Ansiktskremen har en behagelig vannbasert formulering som raskt absorberes og tilfører fukt til huden i opptil 24 timer. Den effektive formuleringen med aktive ingredienser som salisylsyre, hyaluronsyre, phytosakkarider og bifida-fermenteringslysat er med på å forebygge og korrigerer urenheter i tillegg til å tilføre en naturlig glød.

Passer best til fet og uren hud. Testet under dermatologisk kontroll. Tilstopper ikke porene. Med parfyme.',11900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SRDTRTR.png?v=1703930375',10,1,'7696165208239','43055221211311','https://beautymarket.ma/products/vichy-normaderm-fluide-double-correction-hydratant-30-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SRDTRTR.png?v=1703930375"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('La roche-posay silicium 24 rouge 6ml','La Roche-Posay','Maquillage','Filtre les UV pour protéger la couleur et faire durer l''éclat.
- Soin fortifiant protecteur enrichi en Mexoryl XL .
- Répare, renforce, protège l''ongle des UV et prévient le jaunissement.
- Hypoallergénique.
- Couleur plus éclatante.',11100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1_c84e703c-621d-4b8a-ab39-b3193e36e412.jpg?v=1714654257',10,1,'7696184344751','43055312634031','https://beautymarket.ma/products/la-roche-posay-silicium-24-rouge-6ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1_c84e703c-621d-4b8a-ab39-b3193e36e412.jpg?v=1714654257"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('La roche-posay toleriane teint fluide – n°14– 30 ml','La Roche-Posay','Maquillage','Corrige toutes les imperfections et unifie parfaitement le teint grâce à son pouvoir couvrant élevé. Enrichie d’un nouvel agent texturisant breveté, la formule ultra-étirable se module facilement pour un résultat maquillage naturel sans surcharge et un confort longue durée.',20500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1_d5bbe557-7574-406f-9ecb-4bcc4fe0a9ef.jpg?v=1714654590',10,1,'7696194044079','43055357853871','https://beautymarket.ma/products/la-roche-posay-toleriane-teint-fluide-n-14-30-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Untitled-1_d5bbe557-7574-406f-9ecb-4bcc4fe0a9ef.jpg?v=1714654590"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DODIE TASSE PAILLE +18M 350ML JAUNE','Dodie','Bébé & Maman','La Tasse paille jaune de DODIE est destinée aux bébés de plus de 18 mois. Elle les accompagne pour épancher leur soif en toute sécurité.

Equipée d''une paille en silicone souple, les bébés pourront boire plus facilement, a un débit modéré.

Ses anses amovibles et ergonomiques aident à la bonne prise en main. Cette tasse s''ouvre et se referme sans difficulté, pour une manipulation rapide.

Elle est spécialement conçue pour éviter les fuites de liquides.

Par ailleurs, elle est entièrement démontable, ce qui permet un nettoyage facile et plus précis de chaque partie.

Ce produit est fabriqué en polypropylène, sans BPA et sans BPS.

NOUS VOUS RECOMMANDONS',15200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/kjbieh.png?v=1703934829',10,1,'7696223076527','43055475425455','https://beautymarket.ma/products/dodie-tasse-paille-18m-350ml-jaune',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/kjbieh.png?v=1703934829"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Photo White Ecran Invisible Spf 50+= Photo White Correcteur Teint Fluide N°11 20ml Offert','Photo White','Solaires','Crème solaire à large spectre à texture légère, adaptée aux peaux sensibles ayant tendance à développer des taches cutanées et des intolérances au soleil.

 Photo White Correcteur Teint Fluide N°11 Produit multifonctionnel qui combine en une seule application l’action hydratante et protectrice d’une crème de jour et le pouvoir colorant d’un fond de teint. Grâce à son pouvoir couvrant élevé, il unifie le teint et masque efficacement les imperfections sans l’alourdir.',16100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/drtdrtdr.png?v=1704194504',10,1,'7697347838127','43060635599023','https://beautymarket.ma/products/photo-white-ecran-invisible-spf-50-photo-white-correcteur-teint-fluide-n-11-20ml-offert',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/drtdrtdr.png?v=1704194504"]','0') ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Codexial enocare baume à lèvres','Codexial','Solaires','A la texture barrière inédite et à la concentration optimisée en provitamine B5, le Baume Lèvres Nourrissant apaise, hydrate efficacement et favorise la réparation des lèvres gercées tout en les protégeant des agressions extérieures (froid, pollution…).

Comment retrouver des lèvres souples, soyeuses et protégées de la déshydratation ?

Grâce à un complexe d’actifs reconnus pour ses propriétés réparatrices, hydratantes et apaisantes, dont la provitamine B5, le Baume Lèvres Nourrissant permet de retrouver la souplesse naturelle de vos lèvres.

Sans parfum, à la texture translucide et onctueuse ultra-confortable, ce baume apporte un réel cocon d’hydratation aux lèvres sèches, abîmées ou gercées de toute la famille. Son petit format lui permet d’être emporté partout, comme dans un sac à main ou dans une trousse de toilette.',11300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/enocare-baume-levres-nourrissant.jpg?v=1723885768',10,1,'7699153289391','43066702987439','https://beautymarket.ma/products/codexial-enocare-baume-a-levres',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/enocare-baume-levres-nourrissant.jpg?v=1723885768","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enocare-baume-levre-nourissant.jpg?v=1723885774"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Fenioux valeriane 90 gélules','Fenioux','Bien-être','Plante au port majestueux et au feuillage élégant, la Valérianne pousse dans, les lieux humides de toute l''Europe',12000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/srtdt.png?v=1704448649',10,1,'7699217154223','43067104493743','https://beautymarket.ma/products/fenioux-valeriane-90-gelules',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/srtdt.png?v=1704448649"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ISDIN TEEN SKIN ACNIBEN 3 ON THE GO MINIMISEUR D''IMPERFECTIONS','Isdin','Visage','Les lingettes séchantes pour le visage Acniben ON THE GO sont la solution idéale pour minimiser les imperfections même lorsque vous n''êtes pas chez vous. Leurs ingrédients offrent une triple action sur la peau : ils désobstruent les pores, éliminent l''excès de sébum et nettoient en profondeur, aidant à éliminer les boutons, points noirs et imperfections.',13800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LySkin-Isdin-acniben-on-the-go-imperfections-minimizer-wipes-30-units-ISD00152.webp?v=1772450630',10,1,'7699781091503','43070222401711','https://beautymarket.ma/products/isdin-teen-skin-acniben-3-on-the-go-minimiseur-dimperfections',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LySkin-Isdin-acniben-on-the-go-imperfections-minimizer-wipes-30-units-ISD00152.webp?v=1772450630"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
