INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAVAILLES MOUSSE APAISANTE Huile D''olive BIO 70g','Rogé Cavaillès','Visage','Le Nettoyant Visage Solide Rogé Cavaillès Mousse apaisante est un soin nettoyant spécialement formulé pour nettoyer et prendre soin de votre visage. En effet, exposée en permanence aux agressions extérieures (chaleur, soleil, froid, vent, pollution..), la peau du visage est mise à rude épreuve. Sa barrière naturelle peut alors être endommagée et laisser s’échapper l''hydratation de votre peau, laissant place à une peau sèche, terne et en manque de vitalité. La sécheresse cutanée et le stress oxydatif peuvent également favoriser l''apparition d''imperfections telles que des rougeurs ou des boutons. Il est donc essentiel de nettoyer son visage en en prenant le plus grand soin.',11200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/TERSTR.png?v=1742828823',10,1,'7699920453807','43070539628719','https://beautymarket.ma/products/roge-cavailles-mousse-apaisante-huile-dolive-bio-70g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/TERSTR.png?v=1742828823"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAVAILLES MASQUE ECLAT CONCOMBRE BIO 70G','Rogé Cavaillès','Visage','La peau du visage est plus fine, plus exposée aux agressions du quotidien (soleil, pollution…).

Ce masque la nettoie et purifie en douceur. Formulé avec 92% d’ingrédients d’origine naturelle, il régule l’excès de sébum et aide à resserrer les pores : la peau retrouve ainsi son éclat naturel.

Sans savon, il respecte son pH physiologique.

Il se transforme en une mousse onctueuse aux douces notes fruitées.',11200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SRFER.png?v=1704469534',10,1,'7699937231023','43070557323439','https://beautymarket.ma/products/cavailles-masque-eclat-masque-eclat-70g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SRFER.png?v=1704469534"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAVAILLES GOMMANT DOUX Riz BIO 70G','Rogé Cavaillès','Visage','La PEAU du visage est plus fine, plus exposée aux agressions du quotidien (soleil, pollution…). Notre soin nettoyant solide, contenant de la poudre de riz bio de Camargue et du surgras végétal Pro-régénérant®, la nettoie et l’exfolie en douceur. Formulé avec 92% d’ingrédients d’origine naturelle, il élimine les peaux mortes et redonne à votre peau un aspect lisse. Sans savon, il respecte son pH physiologique.

• Un moment de BIEN-ÊTRE : il se transforme en une mousse onctueuse aux douces notes poudrées.

• Un geste pour la PLANÈTE : Vegan, 0 plastique, emballage 100% recyclable.',11200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/roge-cavailles-le-visage-gommant-doux.jpg?v=1704469830',10,1,'7699958497455','43070580654255','https://beautymarket.ma/products/roge-cavailles-gommant-doux-riz-bio-70g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/roge-cavailles-le-visage-gommant-doux.jpg?v=1704469830","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SRTERT.png?v=1704469830"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAVAILLES GEL DOUCHE CREME DE LAIT PEAUX SECHES 200 ML','Rogé Cavaillès','Corps','Jour après jour, il vous apporte une hydratation optimale pendant et après la douche ! Enrichi d’un complexe lacté concentré (glycérine et protéines de lait), le Gel douche hydratant Crème de lait est formulé pour réhydrater** intensément et régénérer les peaux sèches à très sèches. Sa formule riche en agents surgras nettoie en douceur et aide à protège votre peau des agressions extérieures. ** hydratation des couches supérieures de l’épiderm',6100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SERTZERQ.png?v=1704470089',10,1,'7699967082671','43070589993135','https://beautymarket.ma/products/roge-cavailles-gel-douche-creme-de-lait-peaux-seches-200-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SERTZERQ.png?v=1704470089"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
