INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Cavaillès savon crème nourrissante 100 g','Rogé Cavaillès','Corps','Rogé Cavaillès Savon Crème Beurre de Karité et Magnolia 115 g est un savon qui concentre toute l''onctuosité d''une crème et idéal pour l''hygiène des peaux sensibles et sèches,

Ce savon contient une formule qui associe des ingrédients nourrissants à une base végétale : il contient ainsi du Beurre de Karité et du Magnolia, Il nettoie et protège les peaux sèches et sensibles tout en les nourrissant,

Sa texture mousse enveloppe votre peau d''un parfum délicat aux notes de fleurs de Magnolia

Formulé sans paraben, sans phénoxyéthanol, Hypoallergénique,

Testé sous contrôle dermatologique,



CONSEILS D''UTILISATION :

Sous la douche ou dans le bain, frottez le savon dans le creux de votre main et laissez-vous enivrer par son parfum,

Faites mousser sur tout le corps puis rincez abondamment à l''eau claire,
Indication : Hygiène du corps et du visage,

Contenance :100g',6500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/roge-cavailles-cavailles-savon-creme-beurre-de-karite-et-magnolia-100g_1.jpg?v=1772020796',10,1,'7699995885743','43070637768879','https://beautymarket.ma/products/roge-cavailles-savon-creme-nourrissant-beurre-de-karite-magnolia-115g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/roge-cavailles-cavailles-savon-creme-beurre-de-karite-et-magnolia-100g_1.jpg?v=1772020796"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAVAILLES SAVON HUILE VELOUTANT 100G','Rogé Cavaillès','Corps','Rogé Cavaillès Savon Huile Veloutant Huile d''Argan et Amande 115 g est un savon huile qui permet de nettoyer le corps et le visage tout en douceur. Il est idéal pour l''hygiène des peaux sensibles normales à sèches et pour toute la famille.
Ce savon est enrichi en huile d''argan et en huile d''amande reconnus pour leurs propriétés nourrissantes pour la peau. Il nettoie et protège les peaux sèches et sensibles tout en préservant leur hydratation.
Sa formule non grasse et sa texture voluptueuse fond sur votre peau tout en l''enveloppant d''un doux parfum aux notes orientales et sucrées.',6500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/63617661696c6c65732d7361766f6e2d6875696c652d76656c6f7574616e746571d7ac4e_jpg.webp?v=1742817583',10,1,'7699997491375','43070641209519','https://beautymarket.ma/products/roge-cavailles-savon-huile-veloutant-115g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/63617661696c6c65732d7361766f6e2d6875696c652d76656c6f7574616e746571d7ac4e_jpg.webp?v=1742817583"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAVAILLES SAVON Crème Relaxante BEURRE D''AMANDE ET ROSE 115G','Rogé Cavaillès','Corps','Associant ingrédients nourrissants et base végétale, le Savon crème Visage & Corps nettoie et protège les peaux sèches et sensibles en offrant une expérience sensorielle unique. Intensément nourrissante, sa formule crémeuse fond sur votre peau pour la laisser douce et souple. Sa mousse généreuse vous invite à une parenthèse de douceur et dépose sur votre peau un parfum délicat et féminin. Le Savon Crème Amande & Rose est spécifiquement formulé pour nettoyer au quotidien les peaux sensibles et sèches.

Conseils d’utilisation
Sous la douche ou dans le bain, frottez le Savon crème dans le creux de votre main et laissez-vous enivrer par son parfum.Faites mousser sur tout le corps puis rincez abondamment à l’eau claire.Avec son extrême douceur, vous pouvez l’utiliser quotidiennement sur le visage comme sur le corps.',6200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/9000733-1-3596490007331-cavailles-savon-solide-creme-relaxante-100gr.jpg?v=1742818063',10,1,'7699998736559','43070643011759','https://beautymarket.ma/products/roge-cavailles-savon-creme-beurre-damande-et-rose-115g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/9000733-1-3596490007331-cavailles-savon-solide-creme-relaxante-100gr.jpg?v=1742818063"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
