INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Philips Avent Gobelets de conservation du lait maternel réutilisables 0 mois + 180 ml x10','Philips Avent','Bébé & Maman','Philips Avent Gobelets de conservation de lait maternel réutilisables 0 mois + 180 ml x10 offrent une solution de stockage polyvalente et très efficace conçue pour simplifier le parcours d''allaitement de toute maman. Conçu pour votre commodité, ce produit vous permet d''exprimer, de stocker et de nourrir votre lait maternel avec un seul système compatible. En d’autres termes, ces gobelets de conservation sont compatibles avec les tire-lait Philips Avent ainsi qu’avec les tétines Classic, Classic+ et Natural. Cela signifie moins de transfert de lait et une expérience d''alimentation plus simplifiée. À cette fin, ce pack comprend deux adaptateurs pratiques inclus pour une transition sans tracas de l’expression à l’alimentation. De plus, ces tasses peuvent être conservées au réfrigérateur ou au congélateur, garantissant ainsi une organisation optimale. De plus, les gobelets permettent un étiquetage facile afin que vous puissiez suivre les dates et le contenu sans effort',24600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8710103671596.jpg?v=1785514372',10,1,'7702692987055','43081123233967','https://beautymarket.ma/products/philips-avent-gobelets-de-conservation-du-lait-maternel-reutilisables-0-mois-180-ml-x10',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8710103671596.jpg?v=1785514372","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8710103671596e.jpg?v=1785514372"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('OLAPLEX N°4 C BOND MAINTENANCE CLARIFYING SHAMPOO 250ML','Olaplex','Cheveux','Le No.4C Bond Maintenance Clarifying Shampoo d'' Olaplex permet un nettoyage en profondeur détoxifiant qui libère en profondeur les cheveux des résidus et des impuretés indésirables. Il élimine entre autres les dépôts minéraux, le chlore et le sébum. Sa formule innovante garantit que les cheveux ne se dessèchent pas. De plus, il donne plus de souplesse et de brillance et sa technologie brevetée Olaplex Bond-Building Technology™ aide les cheveux stressés par son effet réparateur et fortifiant.
Les cheveux ont l''air plus sains et peuvent à nouveau briller.',29900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/2026_N4C_250ML_ProductPackshot_01_GBL_1440x1440_4cddd08b-76d7-4ddb-9df5-de054fc7ab54.webp?v=1787765124',10,1,'7703035281583','43083720065199','https://beautymarket.ma/products/olaplex-n4-c-bond-maintenance-clarifying-shampoo-250ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/2026_N4C_250ML_ProductPackshot_01_GBL_1440x1440_4cddd08b-76d7-4ddb-9df5-de054fc7ab54.webp?v=1787765124","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/eib1esahmril.webp?v=1787765084","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/qezrezr.png?v=1763999759"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
