INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HT CEUTIC AHA CRÈME POST-PEELING CRÈME APAISANTE HYDRATANTE 200ML','HT Ceutic','Visage','Découvrez HTCEUTIC AHA Crème Post-peeling, une crème faciale apaisante, régénératrice, réparatrice et hydratante spécialement formulée pour renforcer et restructurer la peau qui a subi un peeling médical. Cette crème aide à corriger l’aspect de la peau après les traitements dermatologiques.

Pour une utilisation optimale, appliquez la crème AHA POST-PEELING le matin sur votre visage. Pour des résultats encore plus probants, associez-la à la crème solaire professionnelle HTCEUTIC PROTEK SPF50+.

Profitez des bienfaits de cette crème pour aider votre peau à se régénérer et à retrouver son éclat après des traitements dermatologiques. Le produit est conditionné dans un tube de 200 ml, offrant une solution pratique pour prendre soin de votre peau.',57000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/POOOOOF.png?v=1705587534',10,1,'7708745302191','43121742610607','https://beautymarket.ma/products/ht-ceutic-aha-creme-post-peeling-creme-apaisante-hydratante-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/POOOOOF.png?v=1705587534"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
