INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Vichy Capital Soleil UV-Age Daily spf50+ 40ml','Vichy','Solaires','Prévenir le photovieillissement cellulaire est essentiel pour conserver une peau ferme, rebondie et éclatante. Cela passe notamment par l’application quotidienne d’une protection solaire visage toute l’année.
UV Age Daily SPF50+ CAPITAL SOLEIL est une crème solaire visage SPF50+ qui offre une protection avancée contre les rayons UVA et UVB grâce à sa technologie multi-brevetée Netlock. Dotée d’actifs anti-rides et anti-taches (4 % de peptides et 2 % niacinamide), la formule de ce fluide solaire anti-âge est cliniquement prouvée sur les signes du photovieillissement, dont les taches pigmentaires, les rides et le manque de fermeté.
Conçue pour tous les types de peaux, sa texture fluide ultra légère agit comme un film protecteur très résistant contre les UV et invisible sur la peau, avec une sensation peau nue.
Chaque jour, la peau est protégée des méfaits du soleil et retrouve de la fermeté et de l’éclat, pour un teint homogène.',21000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail12_24559657-fb3b-4a2c-afe0-b3bce205d240.png?v=1752230650',10,1,'7709136519343','43123996033199','https://beautymarket.ma/products/vichy-capital-soleil-uv-age-daily-spf50-40ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail12_24559657-fb3b-4a2c-afe0-b3bce205d240.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail18_f2ded138-43c5-4d83-9306-0f87f29db0a5.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail17_b5be9d78-0917-4cb7-84d8-47c029f18ece.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail9_44681fcf-cf0d-45f5-bc91-7a69104bd0ec.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail3_3426f6c0-73ba-48a8-b19f-f8e06acac86c.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail13_a58c3f51-4a0f-465a-8aa5-87abef32a886.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail1_554a952d-2451-4457-bfb0-215116c41fa0.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail8_450376f7-1f1b-4d0c-99d0-83a590f35121.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail2_09165b89-6dea-4705-abef-c1e153647e15.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail16_4df22967-8dfe-4d03-97fc-621951dbf814.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail10_cd3fb85e-4db5-4721-88a9-baadc9bcb0ab.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail21.png?v=1752230650","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Plandetravail14_7c8b5108-da0f-4399-82fa-0cc36119b57b.png?v=1752230650","https://cdn.s