INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Dominance creme contour yeux 30ml','Dominance','Visage','La crème contour yeux Dominance est un produit spécialement conçu pour prendre soin de la zone délicate du contour des yeux et révéler tout son éclat.

Tout d’abord, cette crème est formulée avec des ingrédients de haute qualité, soigneusement sélectionnés pour leurs propriétés bénéfiques. Sa formule avancée offre une hydratation intense et ciblée, réduisant les signes de fatigue et de vieillissement autour des yeux.

Grâce à sa texture légère et non grasse, la crème contour yeux pénètre rapidement dans la peau, offrant une sensation de confort immédiate. Elle aide à réduire l’apparence des ridules, des cernes et des poches, donnant à la zone du contour des yeux une apparence plus lisse et plus lumineuse.',28400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Dominance-Creme-Contour-Yeux-30ml-nova-prapharmacie-maroc.webp?v=1706007506',10,1,'7711576228015','43140262854831','https://beautymarket.ma/products/dominance-creme-contour-yeux-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Dominance-Creme-Contour-Yeux-30ml-nova-prapharmacie-maroc.webp?v=1706007506"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('JANSSEN COSMETICS POUDRE FIXANTE PARFAITE 30 G','Janssen Cosmetics','Maquillage','Perfect Powder Fixing pour un fond de teint résistant à l´eau et aux frottements extérieurs.

APPLICATION

Après avoir appliqué Perfect Cover Cream saupoudrez la peau généreusement avec la poudre à fixer en une couche épaisse avec un pad. Elle reste environ 10 minutes sur la peau. Enlevez l´excédent de poudre avec une brosse souple et douce.',18100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/qsersererer.png?v=1706023309',10,1,'7711905841327','43142083805359','https://beautymarket.ma/products/janssen-cosmetics-poudre-fixante-parfaite-30-g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/qsersererer.png?v=1706023309"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIODERMA SENSIBIO HUILE NETTOYANTE DEMAQUILLANTE 150 ML','Bioderma','Visage','La 1ère huile micellaire écobiologique qui nettoie et prend soin de la peau

- Elimine le maquillage persistant, en particulier le maquillage waterproof des yeux et des lèvres.

-Nettoie les impuretés de la peau (pollution, écrans solaires quotidiens).

- Apaise la peau

- Nourrit la peau

- Préserve le pH naturel de la peau

Sa texture huile se transforme en lait au contact de l''eau pour une expérience de nettoyage sensorielle et un rinçage facilité.
Texture sans frottement. Pas de vue brouillée ni de film gras laissé sur la peau.',16500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Offert_7_15a3c14b-4035-4d0c-9b75-1313fe07c9b4.png?v=1778494356',10,1,'7712303906991','43144900444335','https://beautymarket.ma/products/bioderma-sensibio-huile-nettoyante-demaquillante-150-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Offert_7_15a3c14b-4035-4d0c-9b75-1313fe07c9b4.png?v=1778494356"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
