INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BELLA AURORA CREME ANTI AGE SUBLIME INTENSE JOUR','Bella Aurora','Solaires','Crème Anti-Age Sublime Intense Jour un traitement anti-âge exclusif qui protège et améliore le microbiome de la peau, retardant ainsi les signes du vieillissement. • Renforce la peau en favorisant l''adhésion du microbiote bénéfique.• Favorise l''équilibre et la diversité du microbiote, ainsi que l''augmentation des bactéries bénéfiques. Un traitement anti-âge exclusif qui protège et améliore le microbiome de la peau, retardant ainsi les signes du vieillissement. • Renforce la peau en favorisant l''adhésion du microbiote bénéfique. • Favorise l''équilibre et la diversité du microbiote, ainsi que l''augmentation des bactéries bénéfiques. •Peaux à partir de 50 ans concernées par les rides et les lignes d''expression, devant être redensifiées et illuminées. Tous types de peaux, même les plus sensibles et les plus délicates.',40900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/sxrtesrser.png?v=1706261998',10,1,'7713127301295','43150966620335','https://beautymarket.ma/products/bella-aurora-creme-anti-age-sublime-intense-jour',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/sxrtesrser.png?v=1706261998"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
