INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BELLA AURORA Gel Exfoliant anti-taches illuminateur 75ml','Bella Aurora','Visage','Nettoie la peau en profondeur, en éliminant en douceur les impuretés et les cellules mortes.• Accélère le processus de dépigmentation et unifie le teint en favorisant la pénétration des principes actifs.• Stimule le renouvellement cellulaire tout en prévenant le vieillissement de la peau.• Agit en effectuant une exfoliation enzymatique pour dissoudre les cellules cornées desquamées, et une exfoliation physique, grâce aux particules qui entraînent les cellules mortes. Testé sous contrôle dermatologique.',15800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/EEE_5710aecb-7f2f-40b7-bcf0-eb655681467a.jpg?v=1792435732',10,1,'7713130447023','43150977663151','https://beautymarket.ma/products/bella-aurora-gel-exfoliant-anti-taches-illuminateur',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/EEE_5710aecb-7f2f-40b7-bcf0-eb655681467a.jpg?v=1792435732"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
