INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DOPPEL HERZ AKTIV COENZYME Q10 30 CAPSULES','Doppelherz','Corps','Des niveaux suffisants en coenzyme Q10 sont nécessaires pour assurer le fonctionnement de la chaîne respiratoire, cette voie métabolique indispensable à la production d’énergie cellulaire et au fonctionnement musculaire. La coenzyme Q10 joue de plus un rôle important en tant qu’antioxydant puisqu’elle est capable de neutraliser les radicaux libres qui sont en partie responsables du vieillissement cellulaire et cutané.

