INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('AMS DHEA 50 MG 60 CAPSULES','AMS','Bien-être','La DHEA est une hormone produite par les glandes surrénales de votre corps. Ce sont des glandes juste au-dessus des reins. Il fonctionne comme un précurseur des hormones sexuelles masculines et féminines, y compris la testostérone et les œstrogènes, où la production de testostérone et d''œstrogènes diminue généralement avec l''âge. Les suppléments DHEA peuvent augmenter et réguler le niveau de ces hormones. Outre la régulation des hormones, l''apport des suppléments de DHEA contribue à augmenter la densité minérale osseuse chez les hommes et les femmes.

Conseils d''utilisation:

Prenez 1 comprimé par jour avec un repas.',27000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/FCGXFTFR.png?v=1708017640',10,1,'7725997785263','43211448287407','https://beautymarket.ma/products/ams-dhea-50-mg-60-capsules',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/FCGXFTFR.png?v=1708017640"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
