INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('IVADERMA Crème AI Acné 3+ 30ml','Ivaderma','Visage','IVAderma Crème AI Acné 3+ 30ml est une formule équilibrée qui combine un effet peeling et apaisant.
Cette Crème désincrusté les pores et corrige les imperfections persistantes jour après jour.

-Désincruste et réequilibre
-Stimule le renouvellement cellulaire
-Réduit les marques

CONSEILS D’UTILISATION :
Appliquer IVAderma Crème A.I Acné 3 sur une peau préalablement nettoyée avec IVAderma Gel Acné 3 A.I, une fois votre peau propre et sèche, appliquez une fine couche sur le visage et corps une à deux fois par jour.',15900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ivaderma-ivaderma-creme-a-i-acne-3-30-ml-soins-anti-imperfections.jpg?v=1708593293',10,1,'7730641141935','43230008213679','https://beautymarket.ma/products/ivaderma-creme-ai-acne-3-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ivaderma-ivaderma-creme-a-i-acne-3-30-ml-soins-anti-imperfections.jpg?v=1708593293"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CHOLLEY CLEANSING DERMPURE Gel Nettoyant 200ML','Cholley','Visage','CHOLLEY Cleansing Dermpure Gel est un splendide gel nettoyant parfaitement équilibré pour purifier la peau et lui donner énergie et fraîcheur. Il est idéal pour le soin quotidien de la peau et pour éliminer le maquillage et les impuretés en profondeur.

– Assure un nettoyage et une purification de l’épiderme
– Protége la peau et renforce les membranes cellulaires
– Hydrate et apaise la peau

Conseils d’utilisation:

Après avoir légèrement humidifié la peau avec de l’eau, appliquez, CHOLLEY Cleansing Dermpure Gel, sur le visage et le cou. Frottez-le doucement dans une mousse et rincez à l’eau tiède. Pour tous les types de peaux.',18900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/715V-CHOLLEY-Cleansing-Dermpure-Gel-200-ml.jpg?v=1708680164',10,1,'7731529384111','43233362837679','https://beautymarket.ma/products/cholley-cleansing-dermpure-gel-nettoyant-200ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/715V-CHOLLEY-Cleansing-Dermpure-Gel-200-ml.jpg?v=1708680164"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('KETOPANE MOUSSE DERMATOLOGIQUE ANTI-SEBORRHEIQUE 200ML','Ketopane','Visage','Associe des propriétés anti-séborrhéique à des propiétés restructurantes et calmantes des peaux sensibles. formulé à partir d’une base lavante douce, il associe  un mélange lipidique enrichi en cérimides, cholestérol, linoléate et palmitate. renforce la cohésion de la couche cornée agressée et désagrégée.

Ketopan mousse est indiqué pour l’hygiène , le controle et la prévention des états séborrhéiques de l’adulte, sous leurs différentes formes.',19500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Ketopan-Mousse.jpg?v=1708784811',10,1,'7731595608239','43233694515375','https://beautymarket.ma/products/ketopan-e-mousse-dermatologique-anti-seborrheique-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Ketopan-Mousse.jpg?v=1708784811"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('APAISEPT SOIN LAVANT ANTISEPTIQUE 200ml','Apaisept','Corps','Gel conçu Pour Peaux et Muqueuses Délicates pour les Désinfecter , les apaiser et Calmer leurs Irritations et démangeaisons.Indications: Hygiène gynécologique : en cas de vaginite , irritation vulvaire ou suite à l’accouchement. Hygiène intime. Hygiène de la peau et de la muqueuse irritées. Acné. Hémorroïdes et Fissures Anales.Pour toute la Famille.Caractéristiques: pH Neutre. Sans Paraben , Sans Colorant. Testé sous contrôle gynécologique.

Utilisation: 1 à 2 fois par jour. Faire mousser une noix de gel , procéder au nettoyage de la zone à traiter puis rincer abondamment.Eviter le contact avec les yeux.',6500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Apaisept-Soin-Lavant-Antiseptique-200ml-beautymall-parapharmacie-casablanca.jpg?v=1708784978',10,1,'7731681853615','43234481602735','https://beautymarket.ma/products/apaisept-soin-lavant-atiseptique-200-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Apaisept-Soin-Lavant-Antiseptique-200ml-beautymall-parapharmacie-casablanca.jpg?v=1708784978"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CODEXIAL Enocare Pro Emulsion Relipidante 400ml','Codexial','Corps','Lait corps nourrissant enrichi en provitamine B5. Il hydrate, nourrit et apaise les sensations de tiraillements et de picotements, tout en prévenant et en réduisant les irritations et les sécheresses cutanées sévères.',24200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-emulsion-relipidante.jpg?v=1708707415',10,1,'7731685949615','43234519646383','https://beautymarket.ma/products/codexial-enocare-pro-emulsion-relipidante-400ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-emulsion-relipidante.jpg?v=1708707415"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CODEXIAL ENOCARE CREME CORPS HYDRATANTE 200 ML','Codexial','Corps','A la texture onctueuse et au complexe d''actifs reconnus pour leur pouvoir hydratant d''extrait de salicorne et de glycérine, la Crème Corps Hydratante permet une hydratation et une nutrition intense et durable de la peau.

Comment avoir une peau douce au toucher, confortable et soyeuse ?

Grâce à son duo ultra-hydratant d''extrait de salicorne et de glycérine, la Crème Corps Hydratante est la réponse aux problèmes des peaux sèches, qui sont généralement plus sujettes aux inconforts cutanés.

Apaisante et protectrice, cette crème apporte la quantité d''eau dont les peaux sèches ont besoin ainsi que confort à l''ensemble du corps. Les sensations de tiraillements, de démangeaisons et de picotements dues à la sècheresse cutanée sont alors apaisées et la barrière de la peau est renforcée.

Véritable crème légère à la texture enveloppante, elle pénètre facilement sans coller ni laisser de film gras sur la peau.

Nourrie, la peau retrouve confort, douceur et est durablement protégée.

CONSEILS D''UTILISATION :

Appliquez votre Crème Corps Hydratante 24H sur l''ensemble du corps en massant délicatement la peau par mouvements circulaires.

À conserver à une température inférieure à 25°C.',22800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enocare-creme-corps-hydratante-200-ml.jpg?v=1708707630',10,1,'7731687653551','43234537275567','https://beautymarket.ma/products/codexial-enocare-creme-corps-hydratante-200-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enocare-creme-corps-hydratante-200-ml.jpg?v=1708707630"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CODEXIAL Enoliss Perfect Skin Peel 5 AHA 100ml','Codexial','Visage','Eau tonique pré-exfoliante concentrée en acide glycolique. Elle exfolie, libère les pores obstrués, élimine les points noirs et prépare la peau aux micro-peelings.',24500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enoliss-perfect-skin-peel-5-aha-100ml.jpg?v=1708766003',10,1,'7732554629295','43236840538287','https://beautymarket.ma/products/codexial-enoliss-perfect-skin-peel-5-aha-100ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enoliss-perfect-skin-peel-5-aha-100ml.jpg?v=1708766003"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CODEXIAL Enoliss Perfect Skin Regul CRÈME VISAGE 30ml','Codexial','Visage','Hydrate, purifie, réduit les imperfections et effet matifiant

Formule enrichie en post-biotique

préserve l’équilibre de la peau

Renouvelée, la peau est purifiée et lumineuse

Développée sur-mesure pour les peaux sensibles et intolérantes aux AHA, l’émulsion exfoliatrice douce Perfect Skin Regul est idéale pour hydrater, purifier et réduire les imperfections cutanées et apporter un effet matifiant. Renouvelée, la peau est purifiée et lumineuse.

Comment hydrater sa peau tout en atténuant efficacement ses imperfections ?

La formule du Perfect Skin Regul est composée de gluconolactone et d’acide lactobionique (PHA). D’origine naturelle, ces exfoliants doux affinent le grain de peau et libèrent les pores obstrués. Le zinc gluconate, aux propriétés purifiantes, apaise les rougeurs et réduit les zones de brillance du teint. Enrichie en post-biotique et ferment de Lactobacillus, ce soin préserve l’équilibre naturel de la peau et renforce la barrière cutanée.

Sa texture légère en fait un soin agréable à appliquer quotidiennenement. L’émulsion exfoliatrice douce Perfect Skin Regul peut s’utiliser seule ou juste après notre lotion Perfect Skin Peel 5 AHA. Elle est une excellente base de maquillage.',30200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enoliss-perfect-skin-regul-creme-visage.jpg?v=1708766562',10,1,'7732732166319','43237027250351','https://beautymarket.ma/products/codexial-enoliss-perfect-skin-regul-creme-visage-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enoliss-perfect-skin-regul-creme-visage.jpg?v=1708766562"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Codexial Enocare Creme Visage Hydratante 30ml','Codexial','Visage','La Crème Hydratante Visage apporte l’hydratation optimale dont la peau a besoin tout au long de la journée, grâce à un complexe d’actifs ultra-hydratants d’extrait de salicorne et de glycérine.

Comment retrouver une peau confortable, douce et intensément hydratée ?

Une peau sèche est une peau qui a perdu sa capacité en eau et souffre de déshydratation et d’un manque de lipides.

Grâce à sa concentration optimisée en extrait de salicorne, un actif naturel de l’hydratation de la peau, la Crème Visage Hydratante apporte la quantité d’eau dont les peaux sèches ont besoin. Cette crème atténue significativement les sensations de tiraillement et de picotement dues à la sécheresse cutanée et repulpe durablement la peau.

Combiné à un second actif hydratant, la glycérine, cette crème répond parfaitement aux besoins des peaux en manque d’hydratation.

A la texture légère qui ne laisse pas de film gras sur la peau, la Crème Visage Hydratante 24H est l’indispensable à avoir dans sa routine beauté. Elle permet à la peau d’être à la fois hydratée, régénérée et protégée des agressions extérieures (effet asséchant du soleil, pollution, stress, …).

PRODUITS RECOMMANDÉS',16900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Enocare-Creme-Visage-Hydratante-30ml.jpg?v=1708766851',10,1,'7732825882799','43237121196207','https://beautymarket.ma/products/lightbox-enocare-creme-visage-hydratante-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Enocare-Creme-Visage-Hydratante-30ml.jpg?v=1708766851"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CODEXIAL Enoliss Perfect Skin Oil 20ml','Codexial','Visage','L’huile concentrée anti-imperfections Perfect Skin Oil est idéale pour hydrater et purifier les peaux à imperfections sans les graisser.

Comment hydrater sa peau tout en traitant efficacement ses imperfections ?

Pour une peau purifiée et des imperfections lissées, l’huile Perfect Skin Oil offre une combinaison d’huiles non-grasses de pépins de raisin, de nigelle et de noisette reconnues pour leurs propriétés hydratantes, purifiantes et désincrustantes. Allié aux pouvoirs lissants et exfoliants de l’acide salicylique ainsi qu’à l’actif matifiant Alpha-avocuta, ce complexe d’huiles nobles et pures réduit les zones de brillance, améliore le grain de peau et favorise l’élimination des imperfections.

Perfect Skin Oil propose une double utilisation. Seule, cette huile concentrée permet de minimiser les effets sensibilisants provoqués par les traitements anti-acnéiques grâce à son complexe d’huiles protectrices. Combinée ou diluée avec notre micro-peeling Perfect Skin 10, 15 ou encore 20 AHA, elle augmente considérablement son efficacité, pour une peau plus nette.

Au toucher sec, l’huile anti-imperfections Enoliss Perfect Skin Oil agit sur les imperfections et l’excès de sébum pour une peau plus belle, saine et matifiée.

Actifs :

Acide salicylique
Acide de fruits lissant et exfoliant. Issu de l’écorce de saule ou de bouleau, l’acide salicylique favorise l’élimination des imperfections et améliore le toucher et l’apparence de la peau.

Alpha Avocuta
Reconnu pour son activité matifiante.

Huiles de pépins de raisin, de nigelle et de noisette
Complexe d’huiles purifiantes et protectrices qui prévient la déshydratation, particulièrement adapté aux peaux à imperfections.

Conseils d’utilisation :

L’huile Perfect Skin Oil peut s’utiliser de deux façons :

En huile seule : prélevez quelques gouttes d’huile au creux de vos mains, faites-les chauffer et appliquez par légères pressions sur l’ensemble du visage avec le plat des mains.
Combiné dans votre crème micro-peeling : prélevez une noisette de crème dans le creux de votre main, déposez-y quelques gouttes d’huile et émulsionnez l’ensemble pour obtenir un mélange homogène. Appliquez le soin en mouvements circulaires sur l’ensemble du visage en évitant le contour des yeux.
Par précaution, ne pas utiliser chez la femme enceinte ou allaitante.
Ne convient pas aux peaux sensibles.',41900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enoliss-perfect-oil.jpg?v=1708767647',10,1,'7733075968175','43237373509807','https://beautymarket.ma/products/codexial-enoliss-perfect-skin-oil-20ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enoliss-perfect-oil.jpg?v=1708767647"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CURASEPT BROSSE A DENTS EXTRA SOFT 012','Curasept','Hygiène','CURASEPT BROSSE À DENTS EXTRA SOFT 012',4500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/curasept-brosse-a-dents-extra-soft-012.webp?v=1708768640',10,1,'7733105295535','43237406539951','https://beautymarket.ma/products/curasept-brosse-a-dents-012',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/curasept-brosse-a-dents-extra-soft-012.webp?v=1708768640"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Bella Aurora Bio10 Forte Pigment Stop Sérum 30 ml – Soin anti-taches intensif éclat du teint','Bella Aurora','Visage','Bella Aurora Bio10 Forte Pigment Stop Sérum – Soin intensif anti-taches



    Le Bella Aurora Bio10 Forte Pigment Stop Sérum est un traitement dépigmentant intensif
    conçu pour corriger, prévenir et atténuer les taches brunes dues au soleil, au vieillissement ou aux déséquilibres hormonaux.
    Sa formule innovante agit directement sur la production de mélanine pour un teint plus clair, uniforme et éclatant.



Un sérum anti-taches hautement concentré


Technologie B-CORE 221™



    Grâce à la technologie brevetée B-CORE 221™, les actifs sont transportés en profondeur au cœur du mélanocyte
    pour une action rapide, ciblée et efficace sur les taches pigmentaires installées ou récentes.
    Ce système d’encapsulation améliore la pénétration et la performance du soin.



Correction et prévention des taches pigmentaires



    Le sérum inhibe la tyrosinase, enzyme responsable de la production de mélanine,
    et prévient ainsi la formation de nouvelles taches.
    Jour après jour, les taches existantes s’estompent visiblement et le teint s’unifie.



Hydratation et éclat



    Enrichi en agents hydratants et antioxydants, ce soin renforce la barrière cutanée et apporte un effet bonne mine immédiat.
    Sa texture fluide et légère convient à tous les types de peau, même sensibles.



Conseils d’utilisation



Appliquer matin et soir sur une peau propre et sèche, avant la crème de jour ou de nuit.


Masser délicatement jusqu’à absorption complète.


Utiliser quotidiennement une protection solaire pour optimiser les résultats.




Résultats visibles



Réduction visible des taches en 6 à 8 semaines


Teint plus lumineux et uniforme


Peau lissée, hydratée et éclatante







    spécialisée dans les soins anti-taches et dépigmentants.
    Découvrez la gamme Bio10 Forte Pigment Stop pour des résultats professionnels à domicile.



Où acheter Bella Aurora Bio10 Forte Pigment Stop au Maroc ?



    Commandez le Bella Aurora Bio10 Forte Pigment Stop Sérum 30 ml sur
    et retrouvez un teint éclatant, lisse et sans taches.',33100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BVBVHBGH.png?v=1708785331',10,1,'7733283586223','43237823611055','https://beautymarket.ma/products/bella-aurora-bio10-forte-pigment-stop-serum-30-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BVBVHBGH.png?v=1708785331"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CODEXIAL ENOCARE HUILE VISAGE NOURRISSANTE PEAUX SECHES 20 ML','Codexial','Visage','A la formule courte sans ingrédients controversés, comprenant du squalane végétal ainsi que des huiles d''avocat, d''amande douce, de carthame et de cameline, l''Huile Visage Nourrissante est une véritable défense quotidienne pour les peaux sèches. Elle hydrate et nourrit durablement la peau, réduit les sensations de tiraillement, d''inconfort et de picotement tout en renforçant la barrière cutanée.

Confrontées à de nombreux facteurs néfastes quotidiens (le stress, la pollution, l''usage de traitements intensifs, le froid...) ainsi que souvent plus sensibles et réactives, les peaux sèches ont tout particulièrement besoin d''attention.

Pour réhydrater votre peau, qui a perdu sa capacité en eau et souffre donc de déshydratation, l''Huile Visage Nourrissante allie dans sa formule les vertus hydratantes et apaisantes du squalane végétal aux propriétés ultra-nourrissantes et régénérantes d''huiles végétales pures.

Légèrement parfumée et à la texture soyeuse, cette huile visage hydratante vient compléter votre routine beauté, en apportant l''hydratation nécessaire dont la peau a besoin.

Intensément nourrie, votre peau est plus douce, confortable et moins réactive.

Conseils d''utilisation:

En huile seule : prélevez quelques gouttes de votre huile au creux de vos mains, faites-les chauffer et appliquez par légères pressions sur l''ensemble du visage avec le plat des mains.

Incorporée dans une crème : prélevez une noisette de votre crème dans le creux de votre main, déposez-y quelques gouttes de votre huile et émulsionnez l''ensemble pour obtenir un mélange homogène. Appliquez le soin en mouvements circulaires sur l''ensemble du visage le contour des yeux et les paupières, puis massez délicatement pour faire pénétrer.

Éviter le contour des yeux.',34200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/VCHGVBHN.png?v=1708786407',10,1,'7733298626735','43237842059439','https://beautymarket.ma/products/codexial-enocare-huile-visage-nourrissante-peaux-seches-20-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/VCHGVBHN.png?v=1708786407"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ALGOLOGIE TRESOR DE LA PRESQU’ILE','Algologie','Visage','Crème de la Presqu’île : La Crème Repulpante & Redensifiante est enrichie en Laminaria digitata pro-jeunesse et boostée en Cellules souches de Criste marine pour combattre tous les signes de l’âge.
Masque de la Presqu’île : Le Masque Repulpant & Redensifiant est enrichi en Acide salicylique et boostée en Cellules souches de Criste marine pour lisser tous les signes de l’âge et illuminer la peau instantanément.

Conseils d’utilisation :

Crème de la Presqu’île : Appliquer matin et/ou soir sur le visage, le cou et le décolleté
Masque de la Presqu’île: Appliquer sur le visage et le cou 1 à 2 fois par semaine, en évitant les yeux. Laisser poser 15 à 20 minutes puis rincer.',67700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/tresor-de-la-presqu-ile-coffret-creme-de-la-presqu-ile.jpg?v=1708786842',10,1,'7733300330671','43237847138479','https://beautymarket.ma/products/algologie-tresor-de-la-presqu-ile',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/tresor-de-la-presqu-ile-coffret-creme-de-la-presqu-ile.jpg?v=1708786842"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ALGOLOGIE Coffret Trésor des Vagues Coffret','Algologie','Visage','-La Crème des Vagues (50ml) : légère et fondante, est enrichie en acide hyaluronique et actifs marins pour hydrater et désaltérer la peau durablement.
-Le Masque Nuit des Vagues (50ml) : ressource la peau en agissant tout au long de la nuit pour une peau souple et infiniment douce dès le réveil.

Conseils d’utilisation :

Crème des Vagues (50ml):
Appliquer matin et soir sur le visage et le cou parfaitement démaquillés.

Nuit des Vagues (50ml):
Appliquer le soir sur le visage, le cou et le décolleté, en couche moyenne et laisser agir toute la nuit. Peut également s’utiliser dans la journée. Appliquer alors en couche épaisse et laisser poser 15 minutes, puis rincer.',28500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3700244689906.jpg?v=1708787283',10,1,'7733302100143','43237850742959','https://beautymarket.ma/products/algologie-coffret-tresor-des-vagues-coffret',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3700244689906.jpg?v=1708787283"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ALGOLOGIE TRESORS DU RIVAGE Coffret Crème du Rivage & Baume du Rivage Ressurfaçant','Algologie','Visage','Votre duo anti-âge pour réduire l’apparence des signes de l’âge et un effet peau neuve !

Crème du Rivage 50ml:
Cette crème onctueuse, particulièrement hydratante est concentrée en actifs marins pour lutter en synergie contre tous les signes de l’âge.

Baume du Rivage (Tube 50ml):
Grâce à des AHA, ce soin de nuit exfolie et lisse la surface cutanée tout en améliorant la texture de la peau pour un effet « resurfaçant ».',66400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3700244689913.jpg?v=1708787497',10,1,'7733302886575','43237852151983','https://beautymarket.ma/products/algologie-tresors-du-rivage-coffret-creme-du-rivage-baume-du-rivage-ressurfacant',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3700244689913.jpg?v=1708787497"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Ziaja Med Anti-acne Creme 50ml + Toner 200ml OFFERT','Ziaja','Visage','ZIAJA Med Anti-acne Creme 50ml

Débarrassez-vous enfin des imperfections. Le soin ciblé anti-acné visage et corps Ziaja Med Antibacterial Care apporte une solution aux peaux à problèmes. L’émulsion active aide à réduire les symptômes de l’acné. Elle favorise une régénération rapide et améliore l’apparence générale de la peau.

ZIAJA Lotion faciale astringente pour les peaux grasses et mixtes

Nettoie, démaquille et apporte une légère activité exfoliante.

Il agit également en préparant la peau aux traitements cosmétiques ultérieurs.',11500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ziaja-med-anti-acne-creme-toner-pack.jpg?v=1709029675',10,1,'7738309148847','43263692570799','https://beautymarket.ma/products/ziaja-med-anti-acne-creme-50ml-toner-200ml-offert',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ziaja-med-anti-acne-creme-toner-pack.jpg?v=1709029675"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LSI SODERMIX PATCH','LSI','Bien-être','Sodermix Patchs Réduction de Cicatrices 13 x 21 cm 2 unités Les patchs Sodermix sont spécialement conçus pour réduire les cicatrices',30500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/sodermix-sodermix-patch-visage.jpg?v=1709223047',10,1,'7739804188847','43269656805551','https://beautymarket.ma/products/sodermix-patch',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/sodermix-sodermix-patch-visage.jpg?v=1709223047"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ECLADERM HydraDerm Creme Hydratante 50ml','Ecladerm','Visage','La crème hydratante visage hydrate au quotidien et aide à préserver la barrière protectrice du visage et du cou. sa texture ultra légère enrichie à la provitamine b5 et l’acide hyaluronique procure une hydratation tout au long de la journée, et dès la première',11400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/TFYXDFT.png?v=1721207620',10,1,'7741610328239','43273383936175','https://beautymarket.ma/products/lightbox-ecladerm-hydra-derm-creme-hydratante-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/TFYXDFT.png?v=1721207620"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NUXE Crème Bonne Mine Effet Liftant, Merveillance Lift','Nuxe','Solaires','Merveillance LIFT - La Crème Bonne Mine Effet Liftant

Un effet tenseur et bonne mine instantané grâce au nouveau soin Merveillance LIFT 2-en-1 [lift + glow] (1) : 100% des femmes sont convaincues (2) !

Cette crème liftante infusée d''huile de Micro-Algue ultra-corrective est subtilement colorée grâce à un extrait végétal de tomate.

Dès l''application, la peau est lissée, lumineuse et comme défatiguée pour 100% des femmes (2). Jour après jour les rides sont corrigées, la peau est plus ferme. Plus belle, même sans maquillage, elle paraît visiblement plus jeune.

Idéale pour tous les types de peaux et toutes les carnations grâce à sa texture fondante à la teinte universelle.',44500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bvhbhbn.png?v=1723722766',10,1,'7741679108271','43273686548655','https://beautymarket.ma/products/creme-bonne-mine-effet-liftant-merveillance-lift',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bvhbhbn.png?v=1723722766"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NEW OIL COSMETICS HUILE DE RICIN 30ml','New Oil Cosmetics','Cheveux','New Oil Cosmetics huile d’abricot est une huile aux vertus illuminantes de la peau.

Grâce à sa composition riche en acides gras et en vitamine A et E commes constituants actifs, elle apporte un véritable coup d’éclat et effet bonne mine et radiant pour toutes les peaux ternes, asphyxiées et fatiguées.

L’huile d’abricot est une huile revitalisante et tonifiante pour les peaux sèches et les peaux altérées par les signes de l’âge.

Conseils d''utilisation :

En soin quotidien : l’huile d’abricot remplace votre crème visage et redonne un excellent effet bonne mine.
En soin corporel : l’huile d’abricot enveloppe votre corps pour une peau souple et éclatante.

- Astuce cheveux : En soin des cheveux : utilisez votre huile d’abricot avant votre shampoing : imbibez vos cheveux d’huile de noyau d''abricot.
Envelopper vos cheveux dans une serviette chaude.
Laissez poser pendant 15min.
Faites 2 shampooings pour bien éliminer l’huile.',12400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hvbhgy.png?v=1709568736',10,1,'7744853049519','43280274063535','https://beautymarket.ma/products/new-oil-cosmetics-huile-de-ricin-30ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hvbhgy.png?v=1709568736"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NEW OIL COSMETICS HUILE DE CHANVRE 30 ml','New Oil Cosmetics','Cheveux','Extraite à partir de la graine de la plante, l’huile de chanvre est dotée de multiples vertus bienfaisantes pour la peau et les cheveux. Enrichit la peau du cuir chevelu, nourrit la fibre capillaire et améliore l''élasticité du cheveu.
L’huile de chanvre est une huile lissante qui facilite le peignage des cheveux abîmés, secs et difficiles à coiffer. Elle hydrate les cheveux et leur apporte de la brillance et les nutriments dont ils ont besoin.
Très efficace pour les cheveux très fins, l’huile de chanvre améliore le volume .

Conseils d''utilisation :

 Pour des cheveux très secs et crépus: Appliquer l''huile de chanvre en masque , sur toute la chevelure, avant le shampoing. Puis sur les pointes uniquement après le nettoyage.

Pour des cheveux normaux à gras: Appliquer l''huile de chanvre sur les pointes avant ou après le shampoing.',20900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/nbjbjhnj.png?v=1709569603',10,1,'7744857473199','43280284418223','https://beautymarket.ma/products/new-oil-cosmetics-huile-de-chanvre-3oml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/nbjbjhnj.png?v=1709569603"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NEW OIL COSMETICS HUILE D''ARGAN 30ml','New Oil Cosmetics','Cheveux','L’huile d’Argan de New oil Cosmétics est l’huile miraculeuse pour les peaux abimées, asséchées, altérées par les signes de l’âge.
Huile nourrissante, régénérante, restructurante et protectrice du viellissement cutané prématuré.

Conseils d''utilisation:

Excellent soin de nuit protecteur pour le visage : quelques gouttes sur le visage et le cou, puis massez délicatement.
Au réveil, la peau est sublimée.',15200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/nhjkk.png?v=1709569225',10,1,'7744860651695','43280291168431','https://beautymarket.ma/products/new-oil-cosmetics-huile-dargan-30ml-previous-product',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/nhjkk.png?v=1709569225"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
