INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ACM NOVOPHANE REACTIONAL LOTION ANTI-CHUTE 100ML','ACM','Cheveux','La lotion anti-chute Novophane Reactional agit à différents niveaux pour freiner les chutes de cheveux réactionnelles (stress, fatigue, post-partum etc.) qui peuvent apparaitre chez l’homme et la femme, stimuler la repousse* et fortifier les cheveux fatigués.

