INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Uriage Ecran Extrême 90 Spf 50ml','Uriage','Solaires','Son complexe anti-UV associe des filtres solaires Haute Tolérance pour convenir à la peau sensible, les actifs hydratants assurent le maintien du taux d’hydratation de la peau, les actifs antioxydants protègent la peau des radicaux libres et du vieillissement prématuré. Enfin, l’eau thermale d’Uriage confère à cette crème solaire ses propriétés apaisantes, hydratantes et anti-radicalaires.
