INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Maybelline New York, Superstay Matte Ink Lipstick - Music Collection Limited Edition — 15 Lover','Maybelline','Maquillage','Découvrez votre style, que la confrontation des couleurs de 16 heures commence ! L''encre Super Stay Matte est dotée d''un applicateur de flèche unique pour une application précise et est disponible dans des teintes super saturées.

Le rouge à lèvres liquide Super Stay Matte Ink™ de Maybelline est un incontournable pour obtenir un fini mat impeccable et longue durée. Cette collection de rouges à lèvres liquides offre une large gamme de nuances super saturées, vous permettant de trouver la couleur parfaite qui correspond à votre style et à votre humeur. La formule est connue pour sa pigmentation et sa tenue exceptionnelles, garantissant que la couleur de vos lèvres reste vibrante et mate tout au long de la journée. Avec le rouge à lèvres liquide Super Stay Matte Ink™, vous pouvez en toute confiance adopter un look audacieux qui dure et est impeccable.',10900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/0782c82970acab591b96413020e128ec.png?v=1712593899',10,1,'7805817028783','43506594447535','https://beautymarket.ma/products/maybelline-new-york-superstay-matte-ink-lipstick-music-collection-limited-edition',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/0782c82970acab591b96413020e128ec.png?v=1712593899","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/71-VD9-KR1L._AC_SX425.jpg?v=1712595291","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/713mZo1MbDL._AC_SX425.jpg?v=1712595345","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/71eBd5gbzrL._AC_SX425.jpg?v=1712595398","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/71nc_YV1oFL._AC_SX425.jpg?v=1712595532","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/71Vn2uAOSVL._AC_SX425.jpg?v=1712595664","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/71cB-1mrikL._AC_SX425.jpg?v=1712595709"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
