INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Medela Pièce de rechange Swing Tuyau','Medela','Bébé & Maman','Le tuyau de rechange pour tire-lait “Swing” de Medela servira à exprimer votre lait.

Garanti sans Bisphénol-A

Pièce détachée. Compatible avec les tire-laits Medela.

Les accessoires pour tire-laits Medela sont garantis sans Bisphénol-A (BPA), comme tous les produits Medela entrant en contact avec le lait maternel.

Les produits sont fabriqués en polypropylène, un plastique alimentaire sûr ne contenant pas de BPA. En plus de la sécurité, ce matériau présente l’avantage d’être très résistant et incassable contrairement au verre.',11400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UntitlYFed-1.jpg?v=1712936879',10,1,'7819589353647','43542297542831','https://beautymarket.ma/products/medela-piece-de-rechange-swing-tuyau',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UntitlYFed-1.jpg?v=1712936879"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
