INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('FIXAZINC VITALITÉ & ÉNERGIE 60 GELULES','Fixazinc','Bien-être','INDICATIONS :
? Améliorer les défenses naturelles
