INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('L''Oréal Professionnel absolut repair molecular shampooing 300 ml','L''Oréal Professionnel','Cheveux','Le Shampoing Absolut Repair Molecular est une formule brevetée, formulée à base de liant peptidique + 5 acides aminés.

