INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('VITIS Junior Gel Dentaire 75ml – Protection complète pour  des  enfants','Vitis','Hygiène','VITIS Junior Gel Dentaire 75ml


