INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('President Bain de bouche pour enfants de 6 à 12 ans, 200 ml','President','Hygiène','Bain de bouche pour enfants de 6 à 12 ans, 200 ml, Président

Propriétés :
