INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('APOLOGIE CRÈME ANTI-AGE 50 ML','Apologie','Visage','Notre crème anti-âge à l’efficacité cliniquement prouvée est composée à +99% d’ingrédients d’origine naturelle. Ses actions :

Anti-ride
