INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Desert Drops Argile Ghassoul marocaine','Desert Drops','Cheveux','Poudre d''argile Ghassoul, 100 % traditionnelle et naturelle Extraite de la montagne de l''Atlas au Maroc, cette poudre riche en minéraux purifie et détoxifie les cheveux et la peau.

