INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('GIFRER SERUM PHYSIOLOGICA BTE X 40 UNIDOSES 5ML','Gifrer','Bébé & Maman','Physiologica est un sérum physiologique pour le nez, il est préconisé pour le lavage des fosses nasales quotidien des bébés, enfants et adultes. Physiologica® sérum physiologique facilite le nettoyage du nez des tout-petits souvent obstrué par du mucus. Il favorise l’élimination des sécrétions excessives. Grâce à son action humidi?ante, il soulage rapidement la sécheresse nasale chez l’adulte. Unidoses stériles de 5 ml sans agent conservateur.Le produit Sérum physiologique lavage nasal est un dispositif médical. Ce dispositif médical est un produit de santé réglementé qui porte, au titre de cette réglementation, le marquage CE. Lire attentivement les instructions figurant sur l’étui.
Conseils d’utilisation: Sérum physiologique à utiliser en lavage dans chaque narine 1 à 6 fois par jour, en fonction des besoins pour l’hygiène nasale.
Ingrédients: Chlorure de Sodium à 0,9 g. Eau purifée q.s.p. 100 ml.',6800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UntitledSSSS-1.jpg?v=1718208127',10,1,'7972997955759','43954944573615','https://beautymarket.ma/products/gifrer-serum-physiologica-bte-x-5-unidoses-5-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UntitledSSSS-1.jpg?v=1718208127"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ARGAN D''OR Huile d''argan alimentaire bio','Argan D''or','Cheveux','C’est une huile obtenue par pression à froid des amandons de l’arganier, Argania Spinosa, une espèce endémique du Maroc. Riche en vitamine E et très riche en acides gras insaturés de type oléique-linoléique dans une proportion de 80%, l’huile d’Argan est traditionnellement utilisée dans les soins de la peau, des cheveux et des ongles; Ce qui a suscité un grand intérêt en cosmétique.

Grâce à ses propriétés antioxydants, raffermis santés, nutritives, adoucissantes et cicatrisantes, elle agit efficacement contre le vieillissement physiologique précoce des peaux sèches, rides, dévitalisés et dés- hydrates auxquelles elle redonne élasticité et souplesse.

De même, l’huile d’Argan combat les gerçures, les cicatrices d’acné et les brûlures superficielles et fortifie les ongles cassants et fragiles. Utilisée en onction, elle assainit le cuir chevelu et fortifie les cheveux secs et ternes auxquelles elle procure force et brillance.',27000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ZZ33.png?v=1718275025',10,1,'7976102690991','43962770686127','https://beautymarket.ma/products/argan-dor-huile-dargan',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ZZ33.png?v=1718275025"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
