INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Erborian CC Dull Correct à la centella Asiatica 45 ML','Erborian','Autres soins','CC DULL CORRECT est un soin illuminateur multiple qui contribue à améliorer l’apparence de la peau en corrigeant automatiquement la perte d''éclat, en unifiant le teint et en floutant les imperfections. De plus, elle apaise et hydrate la peau tout en rehaussant son teint, pour une peau visiblement plus belle et éclatante.

Pour appliquer CC Dull Correct, rien de plus simple. Utilisez-le comme un soin de jour ou comme une base de maquillage, avant l''étape du fond de teint. Appliquez-le en couche fine sur le visage, en évitant le contact avec les yeux.',48900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UntiZDZtled-1.jpg?v=1740395973',10,1,'7976340422831','43964089172143','https://beautymarket.ma/products/erborian-cc-dull-correct-a-la-centella-asiatica-45-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UntiZDZtled-1.jpg?v=1740395973","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/USSSntitled-1.jpg?v=1740395973","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UntDDZZAitled-1.jpg?v=1740395973"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Erborian CC Eye crème contour des yeux 10 ML — DORÉ','Erborian','Visage','CC EYE prend soin de votre contour de l''oeil tout en l''illuminant et corrigeant l''aspect des poches et des cernes, elle contribu à hydrater et lisser les rides et les ridules, camoufler instantanément l''apparence des poches et des cernes et Illuminer le regard.

