INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Erborian BB Crème au Ginseng SPF20 40 ML — CLAIR','Erborian','Autres soins','La crème teintée qui sublime votre peau grâce à son action mi-teint mi-soin, pour un effet « peau de bébé » instantané. Elle se fond sur la peau pour unifier et parfaire son teint, camoufler les petites imperfections, affiner visiblement son grain de peau, hydrater pour une peau plus « rebondie », et donner un fini velouté et non gras.

Il suffit d’en mettre une petite noisette sur le bout de votre doigt, puis de l’appliquer sur la peau en l’étirant de l’intérieur vers l’extérieur sur l’ensemble de votre visage et le cou. BB CRÈME se travaille au doigt ou au pinceau, selon votre préférence.',48900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/clair1_1.png?v=1758396252',10,1,'7976376860847','43964259795119','https://beautymarket.ma/products/erborian-bb-creme-au-ginseng-spf20-40-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/clair1_1.png?v=1758396252","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/nudee_1_cf0dc353-996e-4b2b-86a5-c29a63fcca83.png?v=1758396252","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bbcremedore_1.png?v=1758396252"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
