INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('EVAWIN ROSAWIN ECRAN SOLAIRE INVISIBLE SPF 50+ 50 ML','Evawin','Solaires','ROSAWIN® Ecran Solaire Invisible SPF 50+ est une protection extrême à large spectre contre les UVA I, UVA II et UVB. Une texture spécialement riche en Bisabolol, extrait de Calendula, et en huile essentielle d’arbre à thé, destiné aux peaux sensibles pour une protection maximale contre les dommages cutanés causés par l’exposition prolongée au soleil.

ROSAWIN® Ecran Solaire s’étale facilement et adhère parfaitement à la peau pour un confort et une protection maximale.

ROSAWIN® Ecran destiné pour la rosacée et la couperose, résistant à l’eau. Garantie une bonne hydratation sans fini gras.

Sans paraben, sans parfum.',15100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/IOOP.jpg?v=1718983821',10,1,'7993362710703','44033117880495','https://beautymarket.ma/products/evawin-rosawin-ecran-solaire-invisible-spf-50-50-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/IOOP.jpg?v=1718983821"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DERMO Z ANTI ROUGEURS AR CREME APAISANTE 50 ML','Dermoz','Visage','Pour les peaux sensibles, sujettes aux rougeurs et à tendance couperosique, DERMOZ crée la crème anti-rougeurs AR thermorégulatrice anti-récidive.
Soin « à thermostat » qui contrôle durablement les rougeurs, calme instantanément et durablement les sensations d’échauffements et rougeurs et prévient leur réapparition.
