INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Forte Pharma FORTE DETOX ACTION GLOBALE X5 CITRON 500 ML','Forte Pharma','Bien-être','Avant l’été, pour la rentrée ou avant les fêtes de fin d’année, avez-vous pensé à la détox ? Pour aider votre corps à éliminer les toxines accumulées, Forté Détox 5 organes est la formule idéale !
Aux actifs d''origine naturelle, son association de plusieurs plantes permet une action globale pour détoxifier, purifier et reminéraliser votre corps.

L’association unique de cinq plantes au service de votre organisme :
- l’Artichaut participe au bien-être et à la protection de votre foie.
- le Bouleau favorise les fonctions d’élimination des reins, les organes d’élimination de l’organisme !
- la Chlorelle est connue pour ses actions d’élimination des métaux lourds. Ceux-ci proviennent majoritairement des rythmes de vie. Son action de détoxification du système intestinal contribue à un bon fonctionnement de celui-ci.
- le Romarin est traditionnellement utilisé pour ses propriétés au niveau des poumons.
- la Bardane participe au maintien d’une peau saine.
- l’Ortie piquante présent dans la formule est connue pour son action reminéralisante.

Pour une action globale détoxifiante, purifiante mais aussi reminéralisante !

De plus, sa formule à base d''ingrédients naturels ne contient ni colorants, ni sucres ajoutés*, ni aspartame et convient parfaitement aux végétariens !

Une formule basée sur l’action de cinq plantes en association pour aider votre corps à éliminer les toxines accumulées. Chacune des plantes cible spécifiquement un des cinq organes d’élimination.

Foie, le filtre des déchets de l’organisme :
L’Artichaut est un légume connu pour protéger le foie mais aussi le détoxifier.

Les reins, les filtres de votre corps :
Le Bouleau possède des propriétés diurétiques. Il favorise les fonctions d’élimination des reins.

Système intestinal, la route de l’élimination :
La Chlorelle contient de la chlorophylle. Elle est connue pour son action de détoxification du système intestinal.

Poumon, les filtres aériens :
Le Romarin est connu pour ses propriétés au niveau des poumons.

Peau, la frontière entre l’interne et l’externe :
La Bardane, détoxifiante et purifiante, participe au maintien d’une peau saine.

COMPOSITION:

eau purifiée, bouleau (Betula pendula Roth) (4000 mg), jus concentré de citron (765 mg), bardane (Arctium lappa L.) (2500 mg), artichaut (Cynara scolymus L.) (5000 mg), acidifiant (acide citrique), ortie piquante (Urtica dioica L.) (600 mg), arômes naturels, chlorelle (Chlorella vulgaris Beijerinck) (300 mg) (mollusques, poissons, crustacés), conservateurs (sorbate de potassium, benzoate de sodium), romarin (Rosmarinus officinalis L.) (100 mg), édulcorant (sucralose).

CONSEILS D''UTILISATION:

1 bouchon de 50ml à diluer dans un verre d''eau, 1 fois par jour, de préférence le matin, pendant 10 jours.
Programme renouvelable 3 semaines à chaque changement de saison.',19900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Forte-detox-5-organes-detoxoifiant-fortepharma.webp?v=1790859582',10,1,'8005669585071','44075529404591','https://beautymarket.ma/products/forte-pharma-forte-detox-action-globale-x5-organes-500-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Forte-detox-5-organes-detoxoifiant-fortepharma.webp?v=1790859582","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Attribut1000x1000_ForteDetox5organes.webp?v=1790859585","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DDDZZZ.jpg?v=1719595509"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HEI POA SPRAY LACTE APRES SOLEIL 150ML','Hei Poa','Solaires','Spray Lacté Après-soleil de Hei Poa contenant du Monoï de Tahiti et de l''aloé véra apaise et calme les sensations d''échauffement liés à l''exposition du soleil. Sa formule contenant du Menthyl lactate offre un effet froid très rafraichissant. L''Aloe Vera offre son bienfait apaisant. Ce lait après soleil est enrichi en Monoï de Tahiti AO pour hydrater* et nourrir la peau sous un parfum subtil de fleurs de tiaré.
Avec sa texture fluide et légère alliant le Phototan, un actif prolongateur de bronzage, ce soin ne colle pas la peau et aide à prolonger efficacement le bronzage.

Conseils d''utilisation:

Vous pouvez l''appliquer, en couche généreuse sur l''ensemble de votre corps après chaque exposition au soleil, afin de d''apaiser et hydrater votre peau.',12700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/HEIPOA.jpg?v=1719596546',10,1,'8005684527279','44075573280943','https://beautymarket.ma/products/hei-poa-spray-lacte-apres-soleil-150ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/HEIPOA.jpg?v=1719596546"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
