INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Neutraderm Savon Doux Surgras dermo-protecteur 200g','Gilbert','Visage','Enrichi en Aloé Vera, le savon surgras au léger parfum lavande, nettoie sans dessécher la peau, Son principal agent actif, la glycérine est connue pour apporter élasticité et souplesse à la peau, L''huile d''amande douce contenue dans ce savon surgras, apporte hydratation* et douceur aux peaux délicates,

