INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Gamarde White Efferct Soin Eclat Jour 40ml','Gamarde','Solaires','Au complexe éclaircissant GWE® d’origine végétale

Idéal pour les peaux ternes et/ou à taches brunes (imperfections pigmentaires). Ce soin est formulé avec le complexe
éclaircissant GWE® certifié bio qui diminue la production de mélanine responsable des taches. Le teint est unifié et son éclat ravivé. La taille et l’intensité des taches brunes sont diminuées pour 100% des personnes l’ayant testé',23800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Gamarde-soin-eclat-JOUR-40ml.jpg?v=1721040910',10,1,'8032722944175','44169143025839','https://beautymarket.ma/products/gamarde-soin-eclat-jour-40ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Gamarde-soin-eclat-JOUR-40ml.jpg?v=1721040910"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
