INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PHYTO DETOX - Masque Purifiant Pré-Shampooing - 125 ml','Phyto','Cheveux','Le Masque Purifiant Phyto Détox Pré-shampooing de Phytosolba convient spécialement pour les cheveux pollués. Grâce à la présence de Ghassoul dans sa composition, il élimine efficacement les impuretés asphyxiantes présentes sur le cuir chevelu : la pollution, l’eau de calcaire ainsi que les résidus de produit.

