INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PANIER DES SENS Crème pour les mains - Provence Énergisante 30ml','Panier Des Sens','Maquillage','Une crème pour les mains format voyage, facile à glisser dans son sac à main ou à emporter partout pour des mains douces et hydratées en toutes circonstances.

?? 97% d’ingrédients d’origine naturelle
?? Parfume délicatement les mains
