INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PANIER DES SENS Savon de Marseille liquide Fleur d’Oranger 500ml','Panier Des Sens','Corps','Fabriqué à partir d''huiles végétales, ce savon liquide est cuit au chaudron dans la plus pure tradition marseillaise.
