INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Forte Pharma EXPERT AUTOBRONZ 60 GUMMIES 3EN1','Forte Pharma','Solaires','Et si on vous disait qu’il était possible d’avoir bonne mine toute l’année, sans trop d’effort ? Donc Avec Expert Autobronz Gummies formulé à base de caroténoïdes, de pigments d’origine végétale, d’acide aminé, de vitamines et minéraux, vous afficherez un teint hâlé et lumineux !

Expert Autobronz Gummies c’est une formule complète en générale en format pratique et au bon goût multifruits !

60 gummies.



Pas évident de garder bonne mine toute l’année quand le soleil se fait rare et que l’été est déjà loin ?

Expert AutoBronz Gummies c’est LE produit 3 en 1 qui vous aide à garder un teint hâlé, qui prépare votre peau au soleil et qui sublime votre bronzage tout ça en vous faisant plaisir.

Une formule fortement dosée en caroténoïdes

Composée de caroténoïdes tels que le bêtacarotène, le lycopène et la lutéine, et une sélection de pigments d’origine végétale contenus dans l’extrait de carotte et de rocou.',27000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/AUTO.jpg?v=1721905074',10,1,'8042658627759','44209293656239','https://beautymarket.ma/products/forte-pharma-expert-autobronz-60-gummies-3en1',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/AUTO.jpg?v=1721905074","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/GHCGYTY.png?v=1721905074"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
