INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Mixa Crème Céramide Protection - Visage, Corps, Mains 400ml','Mixa','Solaires','Les peaux très sèches exigent des soins hydratants et protecteurs hautement concentrés qui respectent leur sensibilité : notre crème nutritive et protectrice est hypoallergénique, non grasse, non collante et pénètre instantanément.

Cliniquement prouvé : réduit la sècheresse de 60%*.*Test clinique réalisé sur 24 femmes, après 2 semaines.

Jour après jour, la barrière cutanée est renforcée pour mieux protéger de la sécheresse sévère, variations de température et pollution. Formulée avec de puissants actifs dermo-cosmétiques et adaptée aux peaux sensibles.

CÉRAMIDES : Naturellement présents dans la peau, ils sont connus pour leurs rôles essentiels dans le renforcement de la barrière cutanée.

SQUALANE : Connu pour aider la peau à maintenir son hydratation.',10500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Artboard1copy11_1f457772-4ab2-45cf-945e-d7f1e175b1b0.jpg?v=1775214469',10,1,'8043252383919','44212557938863','https://beautymarket.ma/products/mixa-creme-ceramide-protection-400ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Artboard1copy11_1f457772-4ab2-45cf-945e-d7f1e175b1b0.jpg?v=1775214469","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Artboard1copy_d316b4c9-7953-4b30-8701-51a97cdb9a2f.jpg?v=1775214469","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Artboard1copy9_ee1d791e-05a3-4cf1-9b07-0aadeeae058f.jpg?v=1775214469","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/nbhjbhbjk.png?v=1775214469","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dwdrserser.png?v=1775214469","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Artboard1_d433501f-6361-42cf-8fdd-9d51bfd0bd41.jpg?v=1774442297","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Artboard1copy6_20a72ff1-d608-408f-aabb-941050d10a4b.jpg?v=1774442297"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
