INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Mixa Crème Panthénol Confort - Visage, Corps, Mains 400ml','Mixa','Solaires','Découvrez la nouvelle gamme innovante de Mixa qui nourrit et répare, la Crème panthénol confort qui apaise les sensations d’irritations, sècheresse, rougeurs, et rugosités.

Les peaux très sèches et réactives exigent des soins hydratants et apaisants hautement concentrés qui respectent leur sensibilité : notre crème nourrissante et anti-démangeaisons est hypoallergénique, non grasse, non collante et pénètre instantanément.

Jour après jour, les femmes déclarent avoir une peau plus confortable (90%)*, moins de tiraillements (84%)** et de démangeaisons (80%)***.

Formulée avec de puissants actifs dermo-cosmétiques et adaptée aux peaux sensibles.

PANTHÉNOL : Connu pour ses propriétés apaisantes.

GLYCÉRINE : Connue pour ses propriétés d’hydratation intense et de protection.

OMEGA 6&9 : Connus pour leurs propriétés lissantes.

Testé sous contrôle médical. Résultats cliniquement prouvés.

Testé sur 100% de peaux sensibles****.

Test consommateur après 4 semaines d’utilisation sur 71 femmes*, 53 femmes** et 36 femmes***. ****Tests réalisés sur la liste des produits Mixa à retrouver sur mixa.fr.',10900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Artboard1copy11_889c5de4-395c-45da-bec3-afabfc9b96dd.jpg?v=1775214793',10,1,'8043291639983','44212627701935','https://beautymarket.ma/products/mixa-creme-panthenol-confort-400ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Artboard1copy11_889c5de4-395c-45da-bec3-afabfc9b96dd.jpg?v=1775214793","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Artboard1copy8_1a265398-0799-48da-915c-fb49276bb019.jpg?v=1775214793","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Artboard1copy9_1b9acb93-44f4-4410-9f5d-dfcd8ea5b6f9.jpg?v=1775214793","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/PANTHENOL3.jpg?v=1775214793","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/PANTHENOL2.jpg?v=1775214793","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/PANTHENOL1.jpg?v=1775214793"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
