INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('L''Oréal Professionnel liss unlimited masque 250ml','L''Oréal Professionnel','Cheveux','Le masque lisseur intense de L''Oréal Professionnel pour cheveux indisciplinés est enrichi en Pro-kératine, qui renforce les cheveux, et en huiles de Kukui et d''Onagre connues pour les protéger. En plus de permettre un lissage intense, il laisse vos cheveux nourris et protégés.

