INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DERMINA SENSELINA SPRAY APAISANT PEAUX INTOLERANTES 250 ML','Dermina','Visage','Le Spray Apaisant Peaux Intolérantes de DERMINA rafraîchit instantanément à tout moment de la journée. Plus que de la fraîcheur, il procure une sensation d’apaisement immédiate avec ses extraits de Centella, de Cacao et de Thé vert. Il hydrate également la peau grâce à l''Allantoïne qui limite le dessèchement cutané. La peau est rafraîchie, apaisée et hydratée.

À tout moment de la journée, vaporiser en fine brume sur l''ensemble du visage. Ne pas tamponner après utilisation.',12400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dfgdgdr.png?v=1722446782',10,1,'8047116845231','44227942219951','https://beautymarket.ma/products/dermina-senselina-spray-apaisant-peaux-intolerantes-250-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dfgdgdr.png?v=1722446782"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
