INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('D-Cap Réparation Totale Après-Shampooing 250Ml','D-Cap','Cheveux','L’après-shampooing D-Cap Réparation Totale est un baume spécialement conçu pour les cheveux abîmés. Sa formule enrichie en huile de macadamia permet de démêler les cheveux tout en douceur, de contrôler les frisottis et de renforcer leur structure. Les extraits de myrtille présents dans la formule apportent un effet antioxydant naturel, revitalisant ainsi les cheveux. Ce baume est sans sulfates, sel ni silicone, ce qui en fait un choix idéal pour ceux qui recherchent un soin capillaire doux et respectueux de la fibre capillaire.',21900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/33RR.jpg?v=1722531211',10,1,'8047860580527','44230684868783','https://beautymarket.ma/products/d-cap-reparation-totale-apres-shampooing-250ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/33RR.jpg?v=1722531211"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
