INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NUXE NUXURIANCE ULTRA Le Sérum Correcteur de Taches 30ml','Nuxe','Visage','Corrigez visiblement les principaux signes de l''âge grâce à la TECHNOLOGIE ALFA [3R]* et réduisez l''apparence des taches avec la haute efficacité de la Vitamine C.

