INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NEOSTRATA ENLIGHTEN GEL ANTI-TACHE','Neostrata','Visage','Le gel éclaircissant NeoStrata Enlighten aide à réduire les taches pigmentaires existantes, mais aussi à éviter l’apparition de nouvelles.Le complexe d’acides AHA/PHA assure un gommage respectueux de la peau pour favoriser son renouvellement rapide. Le résultat est une peau éclaircie et unifiée qui paraît beaucoup plus jeune.

Conseils d''utilisation:

Appliquez le gel NeoStrata Enlighten Pigment Lightening chaque soir pendant 2 semaines directement sur les zones pigmentées de la peau. Massez délicatement une petite quantité de produit sur la peau propre et sèche. Si votre peau supporte bien ce gel, augmentez la fréquence d’application en utilisant ce gel matin et soir. N',33500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/neostrata-neostrata-enlighten-gel-anti-tache-soins-anti-imperfections.jpg?v=1723828800',10,1,'8055694459055','44272504209583','https://beautymarket.ma/products/neostrata-enlighten-gel-anti-tache',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/neostrata-neostrata-enlighten-gel-anti-tache-soins-anti-imperfections.jpg?v=1723828800"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
