INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Nature''s Isolari Emulsione apres soleil hydratante 200ml','Isolari','Solaires','Il donne à la peau luminosité et élasticité, sublimant son bronzage. La teneur en Eau d''Orange Douce Unicellulaire, en Eau de Melon et en Lait d''Abricot rend cette émulsion particulièrement hydratante, nourrissante et veloutée. Parfait pour reconstituer l''hydratation de la peau, il procure une sensation immédiate de confort et de fraîcheur, qui réduit les irritations et les rougeurs liées à l''exposition au soleil.',18500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/gcfytfy.jpg?v=1723884398',10,1,'8056179982511','44274009047215','https://beautymarket.ma/products/natures-isolari-emulsione-apres-soleil-hydratante-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/gcfytfy.jpg?v=1723884398"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CODEXIAL Enoliss Perfect Skin 20 AHA 30ml','Codexial','Visage','Eno By Codexial Enoliss Perfect Skin Peel 20 AHA 30ml est un micro-peeling quotidien à destination des peaux grasses à imperfections persistantes de l’adulte. Il a un effet matifiant et assainit les peaux grasses.

L’acide glycolique, concentré à 20% dans ce soin, est un acide de fruit lissant et exfoliant. Issu de la canne à sucre, naturel ou de synthèse, l’acide glycolique améliore le toucher et l’apparence de la peau, désincruste les pores, corrige les imperfections de votre visage, élimine les cellules mortes et redonne ainsi tout son éclat à votre teint.

Résultats : Les imperfections et boutons sont réduits, les pores moins dilatés et la peau est plus nette, visiblement plus saine.',30200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/xenoliss-perfect-skin-20-aha.jpg.pagespeed.ic.bMaG8sfNzx.webp?v=1723884416',10,1,'8056180048047','44274009145519','https://beautymarket.ma/products/codexial-enoliss-perfect-skin-20-aha-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/xenoliss-perfect-skin-20-aha.jpg.pagespeed.ic.bMaG8sfNzx.webp?v=1723884416"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CODEXIAL ENOLISS PERFECT SKIN BODY 25 AHA 100ml','Codexial','Visage','La lotion exfoliante et lissante Perfect Skin Body 25 AHA est une lotion corps pour peaux normales à grasses. Elle corrige les imperfections et rugosités, élimine les cellules mortes, lisse et affine le grain de peau.

Corrige les imperfections et les rugosités

Elimine les cellules mortes

Lisse et affine le grain de peau

Conseils d’utilisation :

Appliquer une à deux fois pressions, sur une peau nettoyée et parfaitement sèche.

Espacer les applications en cas de picotements. Ne pas appliquer sur muqueuses, peau lésée ou irritée. Limiter l’exposition au soleil et utiliser une protection solaire, le cas échéant. Par précaution, ne pas utiliser chez la femme enceinte.',34700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enoliss-perfect-skin-body-25-aha-lotion-exfoliante-lissante-100ml-prix-maroc-parapharmacie-en-ligne-parachezvous.jpg?v=1723885352',10,1,'8056191025327','44274027561135','https://beautymarket.ma/products/codexial-enoliss-perfect-skin-body-25-aha-100ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enoliss-perfect-skin-body-25-aha-lotion-exfoliante-lissante-100ml-prix-maroc-parapharmacie-en-ligne-parachezvous.jpg?v=1723885352"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CODEXIAL ENOCARE PRO CREMA CALMINE 200 ML','Codexial','Visage','La crème Calamine est un soin non parfumé qui stoppe rapidement les démangeaisons et diminue l''incitation au grattage grâce à son complexe d''actifs:

la Calamine : fortement concentrée, soulage et apaise les désagréments cutanés,

la Glycérine et le Beurre de Karité : hydratent et réparent la barrière cutanée,

le Sulfate de Zinc : assainit la peau.

Cette crème peut être utilisé contre l''eczema atopique

Conseils d''utilisation:

Appliquer une à deux fois par jour sur les zones concernées.',23300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enocare-pro-crema-calmine-200-ml.jpg?v=1723886780',10,1,'8056218943663','44274074386607','https://beautymarket.ma/products/codexial-enocare-pro-crema-calmine-200-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/codexial-enocare-pro-crema-calmine-200-ml.jpg?v=1723886780"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
