INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('skin Chemists Acide Hyaluronique Aqua Repair Hydratant de Nuit 50 ml','SkinChemists','Visage','Améliorez votre teint pendant que vous dormez avec notre hydratant de nuit Aqua Repair à l''acide hyaluronique.
Travaillant pour améliorer l''élasticité et la douceur de la peau, et aider à réduire et à protéger contre les rides et ridules, l''acide hyaluronique, connu pour sa rétention d''humidité, maximise ses bienfaits pendant la nuit lorsque nos cellules cutanées effectuent la majorité de leur travail de réparation. Nous avons combiné cela avec des lipides naturels ; les acides gras tels que les huiles organiques qui se sont avérés conditionner et hydrater la peau pour un teint confortable et d''apparence saine.',37800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/NBKJHNJ.png?v=1724408747',10,1,'8059321680047','44289311932591','https://beautymarket.ma/products/skinchemists-hyaluronic-acid-aqua-repair-serum-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/NBKJHNJ.png?v=1724408747"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
