INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Cantabria Biretix Cleanser 400ml','Cantabria','Visage','Gel nettoyant doux adapté aux peaux mixtes à grasses et en association aux traitements anti-acnéiques.

- ACTIVITE ANTIBACTERIENNE : Biopep-15, pirotone olamine, extrait de propolis, aminate G

