INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Tommee Tippee Tasse d’apprentissage Anti-fuite +6m 300ml Bleu','Tommee Tippee','Bébé & Maman','Tommee Tippee Tasse d’Apprentissage Anti-Fuite 300ml 6M+ – Bleu :

