INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LAINO SOIN DES LEVRES CERISE','Laino','Solaires','Le soin des lèvres au délicieux goût grenadine de Laino est le soin indispensable des lèvres fragilisées. Enrichi en extrait de Calendula, ce stick répare, protège et parfume les lèvres pour une bouche à croquer tout au long de l''année. Fruité et coloré il associe le plaisir au soin.

