INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAVAILLES LINGETTES INTIME EXTRA DOUX 15 UNITES','Rogé Cavaillès','Bébé & Maman','Rogé Cavaillès Lingettes Intime Extra Douces Aloé Vera 15 Unités

