INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Garnier ultra doux hair food masque lissant noix de coco 390 ml','Garnier','Cheveux','Découvrez le masque 3in1 Ultra Doux coconut Hair food pour les cheveux

cheveux frisés et crépus.

