INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LUXEOL Après-shampooing Antichute 200ML','Luxéol','Cheveux','Vos cheveux ont tendance à tomber ? Ils sont fragilisés ? Découvrez l''Après-Shampooing Antichute Luxéol, enrichi en extrait de kératine obtenu à partir d''un procédé de fabrication breveté.

