INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LUXEOL Masque Antichute 200ML','Luxéol','Cheveux','Le masque antichute enrichi en extrait de kératine, diminue la chute de cheveux de 38%* et apporte volume et brillance aux cheveux. Ils seront visiblement plus résistants, plus doux au toucher et retrouveront vitalité.

