INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LUXEOL SHAMPOOING ANTICHUTE 200 ML','Luxéol','Cheveux','Le Shampooing Antichute diminue de 42% la chute de cheveux(1), apporte volume(2), brillance(3) et hydratation(4) aux cheveux.

