INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ECODENTA Dentifrice Blanchissant au Charbon Actif 100ml','Ecodenta','Hygiène','Le dentifrice blanchissant ECODENTA au charbon actif est le dentifrice pour les personnes qui recherchent un dentifrice innovant, naturel et non conventionnel pour des dents plus blanches. Le charbon actif possède un puissant effet blanchissant. Le Teavigo™ protège contre le tartre, élimine efficacement la plaque dentaire et procure une sensation de fraîcheur durable. Un dentifrice de couleur noire, que vous pouvez utiliser quotidiennement et qui rend vos dents vraiment plus blanches.

