INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LADOZE écran Teinté spf 50+','Ladoze','Solaires','Combine une protection solaire avancée avec une formule teintée légère qui unifie le teint et masque les imperfections. Enrichi en antioxydants et hydratants, il offre une défense efficace contre les rayons UVA et UVB tout en laissant la peau douce, lumineuse et naturellement éclatante

