INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LADOZE Sérum Correcteur 30ml','Ladoze','Visage','Conçu avec une formule avancée contenant du rétinol encapsulé, du Sodium Ascorbyl Phosphate (vitamine C), d’extrait d’orange japonaise et de la niacinamide (vitamine B3), ce sérum dépigmentant offre une solution ciblée pour révéler un teint éclatant et uniforme.

