INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('THE ORDINARY SÉRUM MULTI-PEPTIDES POUR CILS ET SOURCILS 5ML','The Ordinary','Autres soins','Un sérum volumateur pour les cils et les sourcils, pour un regard plus épais, plus fourni et plus sain.
Le sérum multi-peptides pour cils et sourcils est une formule légère et non grasse conçue pour favoriser des cils et des sourcils plus épais, plus fournis et d''apparence plus saine.
En utilisant 11 ingrédients actifs, dont quatre complexes peptidiques et une série d''extraits naturels, ce sérum à utiliser deux fois par jour aide à nourrir et à protéger vos cils et vos sourcils tout en améliorant leur densité et leur apparence générale en seulement quatre semaines.',27900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/the-ordinary-multi-peptide-lash-and-brown-serum-5-ml.jpg?v=1731317587',10,1,'8112949330095','44600638505135','https://beautymarket.ma/products/the-ordinary-multi-peptide-lash-and-brown-serum-5-ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/the-ordinary-multi-peptide-lash-and-brown-serum-5-ml.jpg?v=1731317587"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
